window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"○○○○○는 인천 최초로의 상수도 시설이자 도시계획 시설로 1905년 중도(中島)박사에 의해 경인수도 설계가 완성됨에 따라 1906년 11월 착공하여 1908년 준공되었다. 또한 1910년 10월 노량진 수원지 정수시설이 준공되어 동년 12월 급수를 하기 시작하였다. ○○○○○는 표고 56.8m에 위치하고 있으며 규모는 부지면적 36,780㎡, 5,000㎡로 저수조 3개를 갖추고 있다.","a":"송현 배수지 제수변실","c":"문화유산자료","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659586.jpg"},{"q":"충청남도 홍성군 홍북면 ○○○에 있는 거대한 마애불이다. 민머리에 가늘고 긴 눈, 넓적하고 낮은 코, 비교적 작은 입이 평면적으로 표현되었고, 입가의 희미한 미소가 부드러운 인상을 풍긴다. 신체 역시 입체감 없이 평면적인데, 두 손을 아래위로 나란히 대고 있는 것만 표현했을 뿐 다른 것은 거의 생략되었다. 지방양식을 잘 드러내고 있는 관촉사 미륵보살입상(보물 제218호) 등 충청도 지방에 남아 있는 거대한 불상들과 비슷한 계열의 작품으로 보인다.","a":"홍성상하리미륵불","c":"시도유형문화유산","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639144.jpg"},{"q":"조선 전기의 문신 어계 조려(1420∼1489) 선생이 태어난 집이다. 조려 선생은 생육신의 한 사람으로 단종을 위해 벼슬을 버리고 영월에서 단종의 시신을 거두어 장례를 치룬 뒤 왕의 얼을 동학사에 모셨다. 그 후 어계 선생은 이곳에서 낚시로 여생을 보냈으며 지금은 후손들의 재실로 사용하고 있다. 대문채·재실·사당으로 구성되어 있는데 대문채는 3칸으로 가운데 문을 높여 세운 솟을대문을 두었고 양쪽은 방으로 만들었다. 재실은 앞면 4칸·옆면 2칸 규모로 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"함안 어계고택","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641755.jpg"},{"q":"수원시 팔달구 화서동에 있다. 화성부 서쪽에 축조된 수리시설로 수원 화성의 서쪽에 있다 하여 서호(西湖)라고도 불린다. 정조가 화성을 쌓으면서 1795년(정조 23)에 내탕금 3만냥을 들여 축조한 관개저수지다. 축만제는 천년만년 만석의 생산을 축원한다는 뜻을 가지고 있다. 제방 양쪽 끝에 두 개의 수문이 설치되어 있는데, 이는 축만제에 가두어둔 물을 활용하기 위한 장치였다. 국가적으로 중요한 제방이었으므로 제언 관리를 위하여 감관 1명, 감고 1명이 배치되어 있었다. 축만제 아래쪽에 설치한 축만제 둔전은 총 규모가 답 83석 15두 4승락에 달했다.","a":"수원축만제","c":"시도기념물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647269.jpg"},{"q":"○○○○○이 있는 월평사지는 현전하는 문헌자료에서는 기록을 찾아볼 수 없으나 당간지주와 함께 ○○이 잔존하고 있고, 주변에서 기와편 등이 확인돼 절터였음을 추정할 수 있다. 이 ○○은 현재 3층까지 잔존하나 구전에 의하면 원래 7층이었다고 하며, ○○의 지대석은 흙에 묻혀 있어 전체가 확실히 보이지 않으나 동쪽 변은 보이고, 긴 장대석을 2단으로 쌓아 마치 2중 기단의 ○○처럼 보인다. ○○은 마모가 심하며 각 부재가 제 위치에 있지 않아 원형을 파악하기 어렵지만, 잔존하는 지대석, 기단부와 탑신, 옥개석 등으로 볼 때 고려시대에 제작된 것으로 추정된다.","a":"영광 단주리 석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101609373300.jpg"},{"q":"○○○과 그 자손 이휘음(1575∼1809)의 유묵과 동도회첩 등이다. ○○○의 자는 대중(大仲), 호는 성오당(省吾堂) 또는 양졸당(養拙堂)이다. 학봉 김성일(金誠一)의 문인으로서 일찍이 효행과 학식으로 널리 알려졌고, 임진왜란 때는 의병장으로서 공을 세워 원종공신이 되었다. 영주 지역에 뿌리를 내리고 살면서 서울과 지방에 많은 명사들과 폭넓은 관계를 유지함으로써 여러 필첩을 남긴 것이다.","a":"영주이개립문중소장문적","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641065.jpg"},{"q":"충청북도 ○○시 덕산면 와룡산의 ○○○ 응진전에 봉안된 나한상(羅漢像)이다. 나한이란 아라한(阿羅漢)의 준말로, 소승불교의 수행자 중 가장 높은 지위에 있는 성자를 말한다. 우리나라에서는 경주 석굴암의 10대 제자상이 걸작으로 손꼽힌다. 사찰의 기록에 의하면 ○○○는 신라말 고려초에 도선국사가 창건한 것으로 나타난다. 그러나 절에서 수습되는 기와조각, 청자조각 등은 고려에서 조선시대의 유물들이 주종을 이루고 있어 확실하게 알 수 없다. 관음보살상과 더불어 응진전에 모셔진 나한상은 조선 중기에 만든 것으로 추정된다.","a":"제천 고산사 석조나한상군","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638701.jpg"},{"q":"서울특별시 도봉구 ○○○에 모신 불상이다. ○○○은 현재 석굴법당만 남아있을 뿐이지만 벽에 불상을 만든 연대가 기록되어 있어 석불상 연구에 중요한 자료가 된다. 여기에 남아 있는 기록으로 보아 만들어진 시기는 1700년대 전후로 여겨지며 연대의 하한은 1784년이다. 아담한 얼굴의 이 불상은 사람키에 가까운 높이, 단정한 체구, 양 어깨를 감싸며 입은 옷 등으로 미루어 보아 조선 후기의 뛰어난 석불상으로 여겨진다.","a":"만월암 석불좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636299.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 태조 6년(1397)에 지은 ○○○○는 임진왜란(1592) 때까지의 내력은 자세히 알 수 없다.『산양지』에 의하면 언제인지 확실하지 않지만 구계동에서 현 위치로 옮겼다가 양청산으로 옮겼다고 전한다. 정유재란(1597) 때 불타 없어지자 선조 35년(1602)에 다시 지금의 위치로 옮겼다고 한다. 순조 32년(1832)에 고쳤으며, 그 이후에 여러 차례 수리가 있었다. 현재 남아있는 건물은 대성전·동무·서무·명륜당·동재·서재 등이 있다.","a":"보성향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639952.jpg"},{"q":"담양 ○○○는 담양군의 서남부에 위치하는데 오례천과 증암천이 영산강 본류에 합류하면서 형성된 넓은 충적지의 북쪽에 위치한다. 마을의 북서쪽에 있는 삼인산(570m)의 남쪽 사면은 해발 100m 정도까지는 급경사를 이루고 내려오다가 해발 40m까지는 구릉성 대지를 이루고 영산강변에 형성된 해발 30m 내외의 충적지에 연결되고 있다. 고분은 남쪽으로 길게 뻗어내린 해발 50m 정도의 구릉에 위치하고 있는데 구릉의 능선을 따라 10기 내외의 고분이 분포되어 있었던 것으로 추정된다.","a":"담양고성리월성산고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654341.jpg"},{"q":"○○○○』의 서문을 찬술한 사람은 柳致明(1777-1861), 노계일고의 서문을 찬술한 사람은 金基纘(1809-?)ㆍ金相稷(1779-?), 뇌곡일고의 서문을 찬술한 사람은 金基纘이며, 노계일고와 뇌곡일고의 발문을 찬술한 사람은 李彙寧(1788-1861)ㆍ李源祚(1792-1871), 『○○○○』의 발문을 찬술한 사람은 李晩慤(1815-1874)이다. 『○○○○』 말미에는 安命玉과 李源祚가 찬술한 ｢耽津安氏世譜序｣가 첨부되어 있다. 이들 서발문에는 하나같이 찬술 연월일이 기록되어 있지 않다.","a":"합천 탐진세고 목판","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666566.jpg"},{"q":"한채의 비각 안에 나란히 서 있는 2기의 비로, 향덕의 효행을 기리고 있다. 향덕은 신라 경덕왕대의 사람으로, 흉년과 전염병으로 인해 부모님이 가난과 병에 시달리자 자신의 살을 베어 봉양하는 등 지극정성으로 모셨다. 왕이 그의 효행을 듣고 벼 300석과 집 한채, 토지를 내려 주었으며, 비를 세워 널리 알리도록 하였다. 이후 향덕이 살던 마을을 ‘효자리’라 하였다. 앞에서 보아 오른쪽에 서 있는 것이 더 오래된 비로, 윗부분이 잘려 아랫부분만 남아있다.","a":"공주소학리효자향덕비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639170.jpg"},{"q":"이 광배는 신라시대의 사찰로 전하는 대흥사(大興寺)가 있던 곳에서 출토된 것이다. 높이 1m, 너비 1.1m의 크기로 중간 부분이 잘록한 물방울 모양이며 머리광배와 몸광배가 표현되었다. 끝 부분의 일부는 파손되었으나 나머지는 비교적 완전하며 새겨진 문양도 뚜렷하다. 광배의 중간에는 불상과 연결되어 있는 구멍이 남아 있다. 동그란 머리광배 중심부에는 연꽃무늬와 구슬목걸이를 조각하였고, 타원형의 몸광배에는 덩쿨무늬와 꽃무늬를 새겼다. 머리광배와 몸광배의 바깥부분에는 불꽃무늬를 꽉차게 배열하였고, 경계선에는 구름에 앉아 있는 작은 부처를 대칭으로 조각하였다.","a":"창녕 사리 석조광배","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641610.jpg"},{"q":"경상남도 마산시 무학산 남쪽 기슭의 낮은 야산 계곡을 둘러 쌓고 있는 산성이다. 이곳에 서면 남서쪽으로 마산만이 한눈에 내려다 보이고, 북동쪽으로는 ○○의 평야지대를 살펴볼 수 있다. 이곳 주민들은 ‘자산산성(玆山山城)’이라고 부르고 있으나, 실제로는 옛 ○○○의 관아건물이 있던 곳으로 행정상의 구실과 군사상의 구실을 겸한 유서깊은 곳이다. 성벽은 야산 능선을 따라 폭 4.3m, 높이 1.7m 크기로 둘러져 있다. 주로 흙을 다져서 쌓았는데, 성벽 안팎의 끝 부분은 돌을 쌓아 마무리하였다.","a":"창원 회원현성지","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655284.jpg"},{"q":"○○○○○의 축조시기는 6세기 후반에서 7세기 전반을 중심으로 한 시기에 조성된 것으로 일부 지역에 대한 조사결과 백제시대 고분 21기가 상당히 밀집된 상태로 횡혈식석실분, 횡구식석실분, 수혈식석곽분 등 다양한 묘제가 확인되었으며 내부에서는 단경호, 직구단경호, 소형 병, 개배, 금동세환이식, 철부, 철겸, 방추차, 관못 등이 출토되었음.","a":"서천당정리고분군","c":"시도기념물","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020052709554600.png"},{"q":"임진왜란 때 순국한 주논개의 초상화를 모시고 제사 지내는 사당이다. 논개는 진주성이 함락될 때 왜장을 유인하여 함께 남강에 투신하였다. 논개의 순국 사실은 입으로만 전해 오다가 유몽인의 『어우야담』에 수록되면서 글로도 전하게 되었다. 그러나 임진왜란 중에 충신·효자·열녀를 수록한 『동국신속삼강행』에는 기생의 정열(貞烈)을 표창할 수 없다는 이유로 누락되었다.","a":"논개사당","c":"시도기념물","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653481.jpg"},{"q":"서울 종로구 창신동의 ○○○에 있는 ○○○○○상으로 1909년에 만들어진 것이다. 돌로 불상이 들어 앉을 반원형의 공간을 만들어 중앙에 관음전(觀音殿)이라 새기고 그 안에 불상을 조각한 것으로 전체 높이 3.53m이다. 불상 좌우에 연꽃이 조각되어 있는 팔각기둥이 세워져 있어 전각 같은 느낌을 준다. 불상은 전체적으로 묵중하고 풍만한 느낌을 주는데, 조각선은 그리 깊지 않지만 자세가 안정적이며, 넓고 각진 어깨가 중량감있어 보인다. 이러한 양식은 고려말 조선초 양식을 계승한 것으로 조선 후기 서울 지역의 마애불 양식을 보여주는 좋은 예이다.","a":"안양암 마애관음보살좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636304.jpg"},{"q":"○○○○○은 충신강 동쪽에 위치한 회덕마을의 북쪽 구릉상에 위치하고 있다. 회덕마을 입구에서 마주 보이는 구릉의 능선을 따라 남서-북동 방향으로 3기가 분포하고 있다. 1호분은 3기의 고분 중에서 가장 서남쪽에 있는 것으로 구릉 능선의 말단부에 자리하고 있다. 마을 입구 정자나무와 가까이에 자리하고 있는데 정자나무 주변이 휴게시설로 정비되면서 끝자락이 훼손되고 민가가 들어서거나 석축을 만들면서 그 형태를 알아 보기 힘들게 되었다. 조사 결과 1호분은 평면형태가 사각형인 것으로 확인되었다.","a":"화순천덕리회덕고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654349.jpg"},{"q":"대벌 마을 입구에 서 있는 높이 360㎝의 돌기둥으로, 이 마을의 당산이다. 당산은 신이 있다고 믿는 민간신앙의 대상물로, 이 지방에서는 마을의 평안과 풍농·풍어 등을 기원하고, 병과 재앙을 막아주며, 자손의 번창을 도와주는 마을 공동신이 되고 있다. 굵직한 돌기둥 위로는 두 마리의 새를 조각하여 올려놓았다. 새를 얹어 두는 것은 새의 활동영역이 하늘·땅· 물 등으로 광범위하여 신과 인간을 연결해주는 매개체로 믿는데서 비롯된 것으로 보인다.","a":"쌍조석간","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658304.jpg"},{"q":"이 비는 고려말 문신인 信齋公 沈漢의 神道碑이다. 심한이 1361년(공민왕10)에 벼슬을 버리고 삼척으로 낙향하자 공민왕이 ‘노인이 동쪽으로 돌아간다’는 뜻으로 “東老”라는 이름을 내렸으며, 후에 眞珠君에 봉하여졌다. 비는 ○○시 발한동 시가지 도로변에 접하여, 도로를 제외한 주위가 민가에 둘러싼 비각 안에 위치하고 있다. 비석의 전면에는 ‘高麗禮儀判書號信齋沈公神道碑銘’이라는 篆이 있고, 전면에는 ○○○의 선조와 공의 내력, 후면에는 기문과 후손의 이름을 기록하였으나 측면에는 내용이 없다.","a":"동해 신재공 심동로 신도비","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660679.jpg"},{"q":"○○○는 선덕여왕 15년(646)에 자장율사가 지은 절로 우리나라 3대 사찰 중 하나이다. ○○○은 ○○○의 중로전에 있는 3개의 법당 중 하나로 가장 앞쪽에서 남향하고 있으며 그 뒤로 용화전과 대적광전이 있다. 조선 영조 원년(1749) 용암대사가 지었고 그 뒤 여러 번 보수를 해서 오늘에 이르고 있다. 앞면 3칸·옆면 3칸의 규모로 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위한 공포는 기둥과 기둥 사이에도 있는 다포양식이다. 내부는 관세음보살상을 모셨으며 벽에는 석가모니의 일생을 그린 벽화가 있다.","a":"양산 통도사 관음전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642050.jpg"},{"q":"○○○란 전망 좋은 산봉우리에 설치한 전근대적 통신수단의 하나로 밤에는 횃불[烽]을 피우고, 낮에는 연기[燧]를 올리는 방식으로 외적의 침입 등 위급한 상황이 발생했음을 알릴 때 사용되었다. ○○○○봉수는 조선전기 이전에 축조된 것으로 추정되는 연변봉수(沿邊烽燧)로 이 ○○○가 위치한 봉화산은 조선시대 당시 산등성이의 형세가 소의 등처럼 생겼다하여「○○」이라 불렀다. 이 봉수는 왜구의 침범을 경보하고, 주변 해역에서 일어나는 정세를 요망(瞭望)하고자 축조된 것으로 역사성이 깊은 국방유적이다.","a":"통영 우산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657591.jpg"},{"q":"○○○은 낙동강이 굽이도는 연안 마을 등성이에 북향으로 배치되어 낙동강을 바라보고 있다. 초창은 1420년대이나 1636년에 폐하였다가 다시 중건하였다. 1827년 경상감사(慶尙監司)로 부임한 정기선(鄭基善)에 의해 중건되었다. 그 후 세 차례 이건하였으나 1909년에 구기(舊基)에 다시 돌아와 중건되었다. 또한 옛 모습을 비교적 잘 지니고 있으며, 가운데 마루방을 둔 평면형식은 아주 드문 예로 희소가치가 크다.","a":"예천 삼수정","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663542.jpg"},{"q":"신라 문무왕(재위 661∼681) 때 원효가 머물었다는 광주 무등산에 있는 ○○○ 대웅전을 신축하던 중 발견된 유물들이다. 수 백점이 발굴되었으나 그 중 금동·청동불상 12점, 소조불상 18점, 청동거울 2점이 문화유산으로 지정되었다. 근래에 8∼9세기의 해무리굽 청자 조각이 발견되어, 이 절의 창건연대를 높이는 단서가 되었으며, 조선시대 분청사기의 파편들이 다수 발견되어 학계의 주목을 받고 있다. 금동·청동불상들은 대부분 부식상태가 심하여, 다른 불상이 가지고 있는 몸 뒤의 광채 즉, 광배와 받침인 좌대를 잃어 버렸다.","a":"원효사출토유물","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637144.jpg"},{"q":"갈평출장소 내에 자리하고 있는 탑으로, 일제시대 때 일본인들에게 빼앗겼던 것을 이웃주민들이 다시 찾아 이 곳에 옮겨 세웠다. 탑은 전체의 무게를 받치는 기단(基壇)을 1층으로 두고, 그 위로 5층의 탑신(塔身)을 올린 모습이다. 기단의 4면에는 모서리와 가운데에 기둥모양을 본 떠 새겼다. 탑신의 두꺼운 지붕돌은 윗면의 경사가 완만하고, 밑면에는 4단의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식받침)과 복발(覆鉢:엎어놓은 그릇모양의 장시)이 남아 머리장식을 하고있다. 전체적으로 무거운 느낌을 주나, 5층을 이루면서도 안정감이 느껴진다.","a":"문경갈평리오층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640645.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상이다. 바닥에 화문석을 깔지 않은 점, 배경에 문양이 없는 점, 안면부의 윤곽선과 세부표현, 그리고 의복표현 등 화곡당 계천영정과 유사한 흐름으로 보인다. 화면 향좌측에 ‘○○○○○대사지진(月㠊堂戒淸大師之眞)’의 화제만이 있을 뿐이다. 화면 크기는 가로 67.4cm, 세로 100.0cm으로, 4폭의 저본(苧本)으로 이어져 있다.","a":"월허당 계청 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643008.JPG"},{"q":"청동기시대부터 통일신라시대에 걸쳐 조성된 대규모 ○○○으로 태화강과 척과천 사이의 구릉지대에 형성되어 있다. 1993년과 1995년의 발굴조사 결과, 청동기시대의 마을과 무덤 위에 다시 삼국시대 및 통일신라시대의 무덤이 더해진 복합유적임을 알게 되었다. 청동기시대 문화층에서는 긴 네모꼴의 움집터들이 확인되었고, 민무늬토기 등 청동기시대를 대표하는 토기와 돌촉 등의 석기류가 출토되었다.","a":"다운동고분군","c":"시도기념물","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645878.jpg"},{"q":"옥과 ○○○ 안에 보존되어 있는 남녀 한 쌍의 목상(木像)이다. 민간신앙에서 신으로 여기던 대상물로, 남자상은 서 있고, 여자상은 앉아 있는 모습인데, 높이가 각각 84㎝, 68㎝이다. 남자상은 무당들이 쓰는 모자를 쓰고 발등까지 내려오는 사제복 형태의 옷을 입고 허리끈을 매었는데, 끝이 길게 늘어져 있다. 둥근 얼굴에 크고 굵은 눈썹이 표현되었고 눈이 돌출되었다. 여자상은 머리에 고깔을 쓰고, 양 손가락 끝을 붙여 아래로 향하게 하였는데, 무언가를 들고 기원하는 모습이다. 얼굴 표현은 남자상에 비해 정교하며 자세도 다소곳하다.","a":"옥과성황당목조신상","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658345.jpg"},{"q":"효령대군의 8대손으로 성리학자였던 이구(1613∼1654) 선생의 문집『○○○○○』을 간행하기 위해 만든 ○○이다. 『○○○○○』은 시(詩)·부(賦)·서(書)·소(疏)·부록 등을 수록하고 있으며, 판각된 ○○ 수량은 140매이다. 내용은 성리학에 대한 깊은 지식을 담고 있으며, 역사에 대한 그의 평론과 천문, 역법 등에 관한 것이다. 이와 더불어 간행한 문집 8권 4책이 전존되어 있다.","a":"활재선생문집 목판","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638635.jpg"},{"q":"‘○○○○’은 불교의 여러 보살과 부처 중에서 서쪽의 극락세계의 아미타부처님을 모신 불전으로 ○○○의 중심 불전이다. 다른 이름으로는 무량수전, 보광전, 아미타전 등이 있다. 이후 고려 말 나옹 선사 혜근스님이 1376년에 이곳에서 돌아가신 후 왕실의 후원을 받아 크게 다시 지었다. 조선 시대에 들어서는 세종대왕의 능인 영릉(英陵)이 인근으로 옮겨지면서 왕릉을 수호하고 필요한 물건을 준비하는 능침사찰이 되어 1472년에 다시 크게 수리하였다. 임진왜란 이후 다시 크게 수리가 이뤄지면서 1678년에 지금의 ○○○○이 다시 세워졌다.","a":"신륵사극락보전","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637594.jpg"},{"q":"○○ 장씨 소유의 정자인 봉림정사 앞에 서 있는 3층 석탑으로, 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올렸으며, 현재 탑신의 3층 지붕돌은 없어진 상태이다. 아래층 기단에는 안상(眼像)을 새겨 놓았고, 위층 기단에는 기둥 모양을 조각하였다. 탑신의 몸돌에도 기둥 모양을 조각하였으며, 특히 1층 몸돌에는 문모양을 새겨 장식하였다. 지붕돌은 네 귀퉁이가 살짝 치켜올라 갔으며, 밑면에 4단의 받침을 두었다. 꼭대기에는 네모난 받침돌 위에 둥근 돌이 놓여 머리장식을 하고 있다. 전체적으로 통일신라의 일반적인 석탑양식을 따르고 있어, 이 때에 세운 것으로 추정된다.","a":"안동 봉림사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641265.jpg"},{"q":"19세기 후반 건물로 뒤편에 산이 있고 앞쪽에 개울물이 흐르는 곳에 있는 집이다. 조선 중기에 이곳으로 온 심명한(1654∼1711) 공의 7대손인 ○○○ 심동섭(1846∼1924) 공이 지은 건물이다. 집 구성은 ㄱ자형 안채와 ㄴ자형 사랑채가 전체적으로 튼 ㅁ자형을 이루고 있다. 실용성이 잘 가미된 조선 후기의 전형적인 양반 가옥이다. 특히 이곳은 항일운동 단체인 신간회의 중앙간사를 지내고 안동 신간회를 조직해서 일어 사용과 창씨 개명에 반대운동을 전개한 심규하(1906∼1976) 공이 항일운동 본부로 사용하였던 곳이다.","a":"인금리월오헌고택","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663153.jpg"},{"q":"○○○는 진주강씨의 동족마을인 동화리에 위치한 서당건물이다. ○○○의 건립과정은 ○○○에 걸려 있는 ○○○서 현판에 의하면 집안이 대대로 청빈하였던 탓에 총명한 인물이 배울 장소가 없을 만큼 곤궁하였고 이에 집안의 인재들을 교육할 수 있는 장소가 없음을 안타까워한 강태한이 터를 잡고 그의 형 태윤이 도와 건물을 마련하였다 전하고 있다. 건축년도는 현판에 ‘甲戌’이라 표기되어 있는데, 강태한의 생몰년으로 미루어 1934년으로 추정된다.","a":"아산 원천재","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661582.jpg"},{"q":"대전 ○○○ 광명농장 안에 있는 ○○○로, 모두 2기가 확인되었다. 1호 가마는 경작과 개간으로 심하게 파손된 상태로 가마의 몸체와 굴뚝의 바닥면이 약간 남아 있고, 아궁이 부분과 천장·벽은 확인할 수 없다. 이 가마의 사용기간 중에 폐기된 퇴적층이 주변에 존재하지 않는 점과 가마벽의 두께가 얇고 불에 익은 정도가 약하며, 무너진 가마 천장부분의 단면에 보수흔적을 거의 찾아 볼 수 없다는 점에서, 단기간 이용되었거나 구조상의 결함같은 이유로 바로 폐기되었을 것으로 보인다.","a":"구완동상감청자가마터","c":"시도기념물","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645833.jpg"},{"q":"○○○는 통일신라 후기의 대학자인 최치원 선생이 세상을 피해 지리산에 들어가기 전 낚시를 즐기던 곳이라 전하고 있다. 바위에 ‘○○○치원서(靑龍臺致遠書)’라는 글자를 새겨 놓았는데, 글씨체로 보아 최치원의 친필로 여겨진다. 최근 후손들에 의해 이를 기리는 ○○○비(靑龍臺碑)가 건립되었다. 당시에는 이곳에 밀물과 썰물이 드나들었다고 하나, 지금은 뭍(육지)으로 변하였다.","a":"창원 청룡대 각석","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656374.jpg"},{"q":"안채, 사랑채, 헛간채를 가지고 있는 19세기 후반의 가옥으로, 전체적으로 트인 ㅁ자형 배치를 보인다. 안채는 ㄱ자형으로 가운데의 대청을 중심으로 왼쪽에 부엌과 안방, 오른쪽에 건넌방이 배치된 전형적인 중부지방의 평면구성이다. 안채의 남쪽에 一자형으로 자리잡은 사랑채는 왼쪽에 대문과 문간방을 두고 오른쪽에 대청과 사랑방을 두어 행랑채를 겸하고 있다. 조선 후기 세련된 건축기술의 흔적을 엿볼 수 있는 주택이다.","a":"김우열가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658258.jpg"},{"q":"조선 중기 문신이며 대학자인 퇴계 이황(1501∼1570) 선생의 종가이다. 원래 있던 집은 없어지고 이 건물은 1926∼1929년 사이에 선생의 13대손 하정 공이 옛 가옥의 규모를 따라 새로 지었다. 앞면 6칸·옆면 5칸 규모의 ㅁ자형 집으로 총 34칸으로 이루어졌다. 높은 석축 위에 둥근 기둥과 네모난 기둥을 사용하여 지었으며, 전면에 솟을대문을 갖추었다. 오른쪽에 있는 ‘추월한수정’은 앞면 3칸·옆면 2칸 규모의 정자인데 마루에는 ‘도학연원방’이라는 현판이 걸려 있다.","a":"퇴계종택","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654456.jpg"},{"q":"○○ 정씨의 3대 가족무덤이다. 고려 충숙왕 때 숭정대부 의정부 찬성사를 지낸 정신중의 부부 합장무덤과 조선 전기 대유학자이며 문장가인 문정공 정이오 부부의 무덤, 그리고 조선 전기에 우의정을 지내고 단종을 위해 순절한 충장공 부부의 무덤이다.","a":"진주 상대동 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655935.jpg"},{"q":"강진군과 영암군을 경계로 동쪽으로는 장흥, 서쪽으로는 해남, 남쪽으로는 완도를 비롯한 다도해를 바라보는 곳에 있는 ○○○은 천황봉을 최고봉으로 하여 구정봉, 사자봉, 도갑봉, 주거봉 등 깎아지른 듯한 기암절벽이 많다. 『동국여지승람』에 의하면 신라 때에는 월나산(月奈山), 고려 때에는 월생산(月生山)이라 불렸다고한다. ○○○은 그 아름다움으로 인하여 예로부터 많은 시인들의 칭송을 들어왔는데, 고려시대 시인 김극기는 “○○○의 많은 기이한 모습을 실컷 들었거니, 그늘지며 개고 추위와 더위가 서로 알맞도다”라고 예찬을 하였다.","a":"월출산","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653931.jpg"},{"q":"○○○○○은 조선 중기의 사림을 대표하는 성리학자인 ○○○을 중심으로, 그의 조부인 이세좌, 부친인 이수원, 아들 이호약, 손자 이광악의 묘가 위아래 5대에 걸친 ○○ 조성의 전통을 잘 보여준다. 여러 가지 석물들이 당시의 형태를 그대로 유지하고 있어 조선시대 15세기 말에서 17세기 전반에 걸친 시기의 문인석 조각 수법의 변화상을 한 곳에서 엿보고 학습할 수 있는 귀중한 자료이다.","a":"괴산 이연경 묘역","c":"시도기념물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651641.jpg"},{"q":"앞면에 ‘○○북거이십리(晋州北拒二十里)’라 적혀있는 비로, 한양으로 가는 길을 안내하는 이정표 역할을 하던 비로 짐작된다. 전하는 이야기에 따르면, 천태산 마구 할머니가 ○○성을 쌓기 위해 바위 3개를 가져오는데, 하나는 머리에 이고, 하나는 지팡이로 짚고, 1개는 치마에 담아 가져오다가 도중에 ○○성이 다 만들어졌다는 소식을 듣고 지금 이 자리에 지팡이로 짚고 오던 바위를 꽂아놓았다 한다. 전설에서 처럼 비의 모습은 기다랗고 가는 기둥 모양을 하고 있다.","a":"진주 냉정리 이정표석","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664269.jpg"},{"q":"조선 중기의 문신 심정(14714∼1531)의 묘로, ○○ 안에는 그의 아들 심사손, 심사순, 손자 심수경 등 ○○○○ 가문의 묘 60여 기가 함께 마련되어 있다. 심정은 연산군 1년(1495) 생원시에 합격한 뒤 여러 관직을 역임하다가 1506년 중종반정 때 공을 세워 화천군(花川君)에 봉해졌다.","a":"풍산 심씨 문정공파 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587831.jpg"},{"q":"악양 마을 북쪽 절벽에 있는 정자로, 조선 철종 8년(1857)에 세운 것이라 한다. ○○○는 전망이 아주 좋은 곳에 자리잡고 있는데, 정자 아래로는 남강이 흐르고, 앞으로는 넓은 들판과 법수면의 제방이 한눈에 들어온다. 한국전쟁 이후에 복원하였으며, 1963년에 고쳐 지어 오늘에 이르고 있다. 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 정자의 이름은 중국의 명승지인 ‘악양’의 이름을 따서 지었다고 전한다. 옛날에는 ‘기두헌’이라는 현판이 있었다고 하나, 지금은 청남 오재봉이 쓴 ‘○○○’라는 현판만 남아 있다.","a":"함안 악양루","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664285.jpg"},{"q":"고니는 여름에는 먹이가 풍부한 북쪽의 툰드라 지역에서 번식한 다음, 가을이 되면 추위를 피해 우리나라의 동해안과 남해안에서 겨울을 나고 봄이 되면 다시 북쪽으로 이동하는 겨울철새이다. 우리나라에서는 큰고니 무리와 함께 겨울을 나며, 주로 호수·저수지·하천·해안 등지에서 생활한다. 보통 고니는 큰고니·흑고니와 함께 백조라고 불린다. 돌산 ○○○ 고니 ○○○는 굴양식장으로 유명한 돌산도 굴전해안에 있다. 매년 늦가을에 50∼150여 마리의 고니가 찾아들어 이듬해 2월 말이나 3월 초순 북녘을 향해 떠날 때까지 이곳에서 머무른다.","a":"돌산평사리고니도래지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654085.jpg"},{"q":"1854년(철종5)에 남양부(南陽府)에서 뜻을 같이 하는 선비들과 관직을 은퇴한 양반들이 예의와 도덕 미풍양속을 진흥하기 위하여 건립하였다. 기로회를 처음 조직할 때 남양부사 홍길모는 기로회가 사회의 본이 되기를 바라는 마음으로 당호를 ‘미풍미화美風美化’의 의미를 담아 ‘풍화당風化堂’이라고 명하였다. 1854년에 기로회가 조직될 당시 건물을 새로 짓지 않고 남양부에서 공창(工廠)을 빌려 사용하였다. 1867년(고종4)에 남양군의 내아(內衙)로 건립된 건물을 1929년에 증여받아 기로소로 사용하여 현재의 풍화당이 되었다.","a":"남양풍화당","c":"문화유산자료","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660232.jpg"},{"q":"이 불상은 흙으로 만들어진 것으로, 높이가 59cm에 달한다. 몸체에 비해 큰 머리를 갖고 있으며, 상체가 낮으면서도 안정감을 주는 등 조선 후기의 특증이 보이는 불상이다. 머리는 곱슬곱슬한 나발이며, 머리 위로는 상투와 같이 우뚝 튀어난, 즉 육계가 높이 솟아 있다. 머리와 육계 사이에는 반달 모양의 계주, 즉 장식물이 있다. 얼굴은 정방형의 형태로 정면을 응시하면서 다소 근엄한 표정을 짓고 있다. 옷 모양새는 양어깨를 모두 가리고 있으며, 가슴 이하의 복부를 가려주는 승기지와 대의를 입고 있다.","a":"이조여래좌상","c":"문화유산자료","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666838.jpg"},{"q":"○○○○는 결구가 치밀하며 치목과 세부 수법이 우수한 근대 한옥의 특징을 잘 보여주며, 영남의 기호사림의 학맥을 이어온 관련 인물의 유학사적 비중을 고려할 때 건축적 특징과 상징성을 지니고 있다.","a":"김해 화산정사","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666772.jpg"},{"q":"○○○은 사찰의 야간법회시 불을 밝히거나 또는 숯을 피워 주변을 따뜻하게 하는 기능을 가진 석물로 \"불우리\", \"노반지주\", \"광명대\", \"화사석\", \"정료대\"등 많은 이름을 가지고 있다. 단층기단의 탑잉 유독 문경지역에만 집중적으로 나타나듯이 ○○○ 또한 문경에 남아 있는 독특한 문화유산 중의 하나이다. ○○○은 석등의 원초적 형태로 분류되지만 현재 남아 있는 것은 모두 조선시대 중,후기가 대부분이다. ○○○○○의 형태는 사각형 지대석을 놓은 뒤, 사각기둥을 한가운데 세우고 그 위에 받침이 있는 화반(化盤)을 올려놓았다.","a":"문경대승사노주석","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641206.jpg"},{"q":"○○○은 우리나라에서 오래된 은행 점포의 하나로 1909년 준공 당시 대한천일은행(현 우리은행)의 본점이었으며, 현재는 우리은행 종로금융센터로 사용되고 있다. 가까운 곳에 광통교가 있어 ○○○이라 불렸다. 1907년에 탁지부 건축소에서 설계와 시공을 담당하였고, 1908년 2월에 착공하여 1909년 5월에 준공하였다. 건물의 1층은 대한천일은행, 수형조합(手形組合)에서 사용했으며 각각 전용 출입구가 있었고, 2층은 집회 장소로 회의실, 흡연실, 대기실로 사용되었다. ○○○은 벽돌과 석재를 혼용하여 만든 절충주의 양식의 건축물이다.","a":"광통관","c":"시도기념물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2021111213572100.jpg"},{"q":"이 작품은 영조 36년에 실시된 청계천 준천공역(준설)을 성공적으로 완공한 것을 기념하여 그린 일종의 기록화첩이다. 목활자본의 준천소좌목(濬川所座目)이 1폭 2면에 걸쳐 있고 그 뒤에 영화당친임사선도(暎花堂親臨賜膳圖), 수문상친임관역도(水門上親臨觀役圖) 그림 2폭 4면, 어제어필(御製御筆) 2폭 4면, 어제시(御製詩) 1폭 2면, 입시대신(入侍大臣)과 대관(侍官), 준천에 참여한 사람들 16명이 영조가 지은 시의 운자(韻字) ‘력(力)’과 ‘국(國)’자에 차운(次韻)하여 지은 이른바 갱운시(賡韻詩) 8폭 16면의 순서로 이루어진 견본채색의 서화첩이다.","a":"어전준천제명첩","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636745.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상이다. 화면은 주색 상단벽면과 돗자리의 이단구도이며, ○○선사는 왼손엔 주장자를 오른손엔 염주를 쥐고 돗자리위에 가부좌하고 있다. 화면 향좌측에 ‘○○○대사○○지진(秋波堂大師芝沾之眞)’의 화제가 있고 향우측엔 영찬이 있다. 이 영찬의 기록에서 1887년에 조성되었음을 확인할 수 있다. 화면크기는 가로 76.6cm, 세로 103.7cm이며 바탕은 1폭의 면본으로 이루어져 있다.","a":"추파당 지첨 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643030.JPG"},{"q":"보관(寶冠)과 양손을 따로 만들어 불신(佛身)에 결합시킨 조선시대 ○○○○○이다. 현재 보관은 결실되고 없지만 이마 위에 단을 지어 보관을 안치했던 흔적이 남아있으며, 머리 정상부에 머리카락을 쓸어 올려 묶은 보계(寶髻)가 드러나 있다. 귀의 앞뒤로 흘러내린 머리카락이 귓볼 부근에서 교차하며 어깨 위에서 세 개의 원을 이루고, 다시 세 갈래로 나뉘어 흘러내리고 있다. 얼굴은 네모난 형태로 가늘게 뜬 눈은 아래를 향하고 있으며, 백호(白毫)가 뚜렷하다.","a":"목조보살좌상(1990)","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018111915290000.jpg"},{"q":"여표비란 정려(旌閭:충신·효자·열녀 등의 언행과 정신을 기리기 위해 그들을 표창함)의 표시로 세워두는 비로, 이 비는 조선시대의 사람인 ○○○의 효행을 기리고 있다. ○○○은 임진왜란 중에 그가 지극정성으로 모시던 할머니와 어머니가 함께 돌아가시자, 난을 피하지 않고 밤낮으로 크게 통곡하였다. 이곳을 지나가던 왜장이 그의 효심에 감복하여 “출천지효(出天之孝 : 하늘에서 내린 효자) 라는 글씨를 써서 왜병으로부터의 침범을 막아주었는데, 이것이 여표비의 유래가 되었다 한다. 현재 비는 담장이 둘러진 비각 안에 마련되어 있다.","a":"밀양 박양춘 여표비각","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664307.jpg"},{"q":"조선 중기의 문신인 ○○ 선생의 ○○이다. ○○ 선생은 이조참판, 형조참판을 지낸 이로, 임진왜란 때 선조임금을 의주까지 호위한 공을 인정받아 호성공신에 봉해지기도 했다. 비단 위에 그려 놓은 그림은 가로 90㎝, 세로 167㎝의 크기이다. 의자에 앉아 있는 전신상으로, 시선은 오른쪽을 바라보며, 두 손은 소매 안에서 마주잡고 있다. 사모를 쓰고, 중요의식 때 입었던 관복을 입고 있으며, 가슴에는 두 마리의 학이 그려진 흉배가 표현되어 있다. 선생이 57세 되던 선조 40년(1607) 때의 모습을 김이섭이 그린 것으로, 조선 중기의 화풍을 잘 보여주고 있다.","a":"신잡 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638464.jpg"},{"q":"요지는 자기나 기와·그릇들을 만들어 굽던 가마터를 말한다. ○○○ 손항마을에서 2㎞ 떨어진 곳에 1호 가마터가 있고, 이곳에서 손항마을 쪽으로 1.5㎞ 정도 내려온 곳에 2호 가마터가 있다. 1호 가마터는 산사태로 전부 파괴되었고, 2호 가마터는 도로공사로 인해 가마터의 중심부가 완전히 파괴되었다. 1, 2호 가마터에서 채집된 유물은 대접·접시·종지·병의 조각들로 그릇모양과 문양은 비슷하다. 그러나 자기를 만드는 바탕흙인 태토와 유약에 있어서 1호 가마터의 것이 2호 가마터에 비해 질이 떨어진다.","a":"산청 장천리 도요지","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654810.jpg"},{"q":"1603년(선조 36년) 3월에 세워진 이 비의 석질은 자갈이 듬성듬성 박힌 사암이며, 이후 어느 시기에 깨어져 세 부분으로 분리되었다가 접착제를 이용하여 다시 붙였다. 비의 전면에는 평해군 북쪽 10리 월송변에 하나의 사천이 바닷물과 서로 통해 사시로 물이 넘쳐 민들의 일상생활과 상인들의 통행이 어려워 당시 주민들이 생활의 불편함을 없도록 하기 위해 평해군수 조인징의 허락을 얻어 돌다리를 만들고 이를 기념하기 위해 비석을 세웠다.","a":"평해북천교비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641125.jpg"},{"q":"성재 금난수의 종가이다. 금난수(1530∼1604)는 조선 중기 학자로 퇴계 이황의 제자이다. 정유재란 때에는 고향에서 의병을 일으켜 활약했으며 후에 봉화현감을 지냈다. 지금의 건물을 지은 정확한 연대는 알 수 없으나 건축 양식이 조선 후기의 것으로 보인다. 안채 대청이 오른쪽으로 치우쳐 있으며 상방(웃방)이 대청 앞으로 돌출되어 있다. 또한 안방 윗부분을 통다락으로 구성하고 있어 특이하다.","a":"안동 성성재 종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658943.jpg"},{"q":"묘법연화경은 줄여서 법화경이라고도 부르는데 우리나라 천태종의 근본경전으로 부처가 되는 길이 누구에게나 열려 있음을 기본사상으로 하고 있다. 화엄경과 함께 우리나라 불교사상의 확립에 가장 크게 영향을 끼쳤으며 삼국시대이래 가장 많이 유통된 불교경전이다. 묘법연화경 ○○○○ 영각사 중각본은 반곽 23.3×17.8cm, 전곽 30.7×19.9cm 로서 간기를 통해 볼 때 영각사에서 1539년에 중각한 것으로서 7권 28품의 완질이 전하고 있으며 제1권의 변상도와 제7권에 증각에 대한 연기가 기록되어 있다.","a":"조앙사소장묘법연화경 권제1, 권1-7","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639801.jpg"},{"q":"춘천 ○○○가옥은 1917년에 세운 집으로 ㄱ자형 안채와 ㄴ자형 사랑채가 배치되어 전체적으로 ㅁ자 평면을 이루고 있다. 안채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 대청을 중심으로 왼쪽에는 웃방·안방·부엌을 두었고 오른쪽으로는 건넌방을 꾸몄다. 지금은 생활하기에 편리한 구조로 개조하였는데, 부엌을 입식으로 고치고 안방과 웃방 사이의 벽과 바깥쪽 툇마루를 없애 방을 넓혀 쓰고 있다. 사랑채는 대문 왼쪽에 외양간·광·방을 배치하였고 오른쪽에는 부엌·방·광을 놓았는데, 왼쪽은 삼량구조이나, 이 오른쪽 부분은 평사량구조를 취하고 있다.","a":"춘천최재근가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660454.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○의 가례초등학교를 중심으로 남북에 자리하고 있는데, 북쪽 들판에 3기, 남쪽의 밭에 1기가 있다. 북쪽의 1·2·3호는 모두 한 줄로 늘어서 있으며 바둑판식이다.","a":"의령 수성리 지석묘군","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656428.jpg"},{"q":"○○시 대곡면 대곡리에 위치한 죽방산(일명 송대산, 해발 312m) 정상부에 2개의 봉우리를 감싸고 있는 성이다. 이 산성은 남강의 중류에 인접하여 솟아 있는데, 산성에서 아래의 강변이 훤히 조망된다. 따라서 산성의 설치 목적이 강을 이용한 통로의 확보 혹은 차단과 관련된 관망용이었음을 알 수가 있다. 성은 석축 또는 토석 혼축으로 축조되었던 것 같으며, 성벽은 대부분 붕괴되었으나 하단부 혹은 기단의 석축의 흔적은 군데군데 남아 있다. 성과 관련된 시설로는 문터 2개소, 건물터 다수, 우물 등이 남아 있다.","a":"진주 전 송대산성","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657124.jpg"},{"q":"○○○○○은 4면이 모두 열려 있는 개방형 정자로 가구 기법에서 자연스럽게 휜 대들보 상부로 양측에서 곡이 있는 충량이 얹혀지는 ‘+’형이 특히 눈에 띄는 등 역사성, 장소성, 건물의 조형성 등 가치 있다. 조선후기 정자로서 건립 기록(1876년)이 확인 되고 정려와 정자 등 전통 마을 유교경관의 중심지이다.","a":"영광 침류정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662341.jpg"},{"q":"석탑의 일부분으로, 1940년 신라의 옛 사찰인 무진사터로 전하는 곳에서 발견되어 관음사 경내로 옮겼다가, 1992년 강릉시립박물관으로 옮겨 놓았다. 이들은 모두 2개인데 하나는 위층 기단(基壇)의 일부로 여겨지고, 다른 하나는 탑신(塔身)의 1층 몸돌이었을 것으로 보인다. 기단으로 보이는 석재는 각 면의 모서리와 가운데에 기둥 모양을 새겨 칸을 만든 후 각 칸마다 8부신상(八部神像: 불교에서 불법을 수호하고 대중을 교화한다는 여덟무리)을 조각해 놓았고, 탑신의 1층 몸돌로 보이는 석재에는 네 모서리마다 기둥 모양의 조각을 두어 각 면에 불상을 새겨 놓았다.","a":"강릉옥천동석탑재","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660307.jpg"},{"q":"선종(禪宗)의 6대조인 혜능(慧能)의 수도하는 과정과 문인들을 위해 설법한 내용을 담고 있는 자서전적 일대기로, 한 권의 목판본이다. 선조 2년(1569)에 평안도 상원 해탈사에서 개판하고, 다시 심곡사로 옮겨 간행하였다. 특징을 보면 첫째 혜능을 중심으로 선사들의 법맥을 강조하는 학풍이 생겼다는 점, 둘째 자기성찰을 떠난 부처는 없다는 점, 셋째 선종의 수행방법은 깨달음인데 그 근본이 되는 것이 바로 이 책이라는 점이다.","a":"범어사 육조대사법보단경","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636669.jpg"},{"q":"낙동강을 앞에 두고 있는 작은 산성이다. 신라 진흥왕 23년(562)에 초계, 의령 방면의 왜적을 방어하기 위해 쌓았다고 전해지며, 임진왜란 때 곽재우 장군이 일으킨 의병이 이곳에서 왜군을 무찔렀다고도 한다.","a":"창녕 성산산성","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664017.jpg"},{"q":"산을 등지고 자리잡은 이 집은 안채와 사랑채가 접하여 ㄷ자형 구조를 이루고 있는데, 一자형 헛간채가 배치되어 전체로는 ㅁ자형 배치를 띠고 있다. 안채는 툇마루를 설치한 대청마루를 중심으로 오른쪽에 웃방·안방·부엌을 직각으로 배치하였다. 왼쪽으로는 건넌방이 접하여 ㄱ자형을 이루고 있는데 이는 영서·중부 지방 민가 형식이다. 사랑채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸며 높고 경쾌한 구성을 보이고 있다.","a":"영월 창원리 고택","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660466.jpg"},{"q":"○○○의 향안은 일부 향안이 상당부분 도할된 채로 보관되어 있고, 또 일부 향안에는 당시 향안이 훼손된 상황을 알려주는 글이 있어 당시 향안입록을 둘러싸고 각 가문과 계층간에 첨예하게 대립했던 모습들을 알려주는 내용을 담고 있다. 또한, 향안의 원본으로서 다른 곳에서는 발견되지 않는 당시 사회모습의 일단을 그대로 보여주는 중요한 자료이다. 현재 각 가문에는 1910년에 만들어진 연방안과 계방안을 한 책으로 합쳐 인쇄하거나 필사한 책자인 ＂연계안＂이 소장되어 있는 경우가 많다.","a":"진주 연계재 고문헌","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642492.jpg"},{"q":"굴암산 중턱의 병풍처럼 둘러싸인 암벽에 자연동굴이 있고 그 안에 불상이 있다. 연꽃무늬가 새겨진 4각의 대좌(臺座)위에 양 발을 무릎 위로 올린 모양으로 앉아있는데, 신체는 전체적으로 네모진 모양이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 넓고 높게 표현되어 얼굴을 길어 보이게 한다. 어깨는 좁아서 움추린 듯 하며, 양 어깨에 걸쳐 입은 옷은 형식적으로 표현되었다. 무릎은 높으면서 폭이 좁고, 허리가 길게 표현되어 불안정한 자세를 보여준다.","a":"비안면자락동석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640344.jpg"},{"q":"충청남도 공주에 있는 갑사 뒷산 사자암에 약사여래입상, 갑사 부도와 같이 있던 것을 갑사 진해당(振海堂)에 옮겨 보관하고 있다. 얼굴은 마멸이 심해 분명하지 않으나 코가 오똑하고 눈은 감은 듯 하다. 옷은 양 어깨를 감싸고 있는데, 한 자락이 오른손 손목을 거쳐 등쪽으로 넘겨졌다. 하체에 걸쳐진 옷은 선이 부드럽고 얇아서 신체의 굴곡을 충실히 표현하고 있다. 가슴부분의 오른손은 뭔가 들고 있는 듯 하나 분명하지 않고, 왼손은 팔을 내려 무릎 부분에서 목이 긴 병을 들고 있다. 전체적으로 잘록한 허리, 어깨 등 조각수법이 세련된 백제시대의 작품으로 보인다.","a":"갑사석조보살입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639088.jpg"},{"q":"제주시 영평동, 월평동 마을의 본향당으로 제주상업고등학교 남쪽 동산 '신대기마르' 과수원 안에 있다. 당 안에는 보호수로 지정된 커다란 팽나무가 있고, 그 주위를 둥그렇게 에둘러 울타리를 쌓았다. 왼쪽 담을 의지하여 나지막한 제단을 마련하였다. 제단 뒤에 있는 나뭇가지에 지전과 물색을 걸어 둔다. 규모는 작으나 신목형 신당의 원형을 잘 보존하고 있다.","a":"월평다라쿳당","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659290.jpg"},{"q":"관음사는 도의선사가 창건한 것으로 전해지는데, 임란 후 17세기 초에 중수되면서 많은 속암(屬庵)이 딸린 대규모 사원이었던 것으로 추측된다. 1707년 이 후 어느 시기에 화재를 당해 다시 재건되지 못한 채 현재에 이르고 있다. ○○○○○는 1707년(숙종 33) 자연암반에 12cm 정도의 깊이를 파 세운 것으로 대좌(臺座)와 비수(碑首)는 없다. 이 비는 폐사된 관음사의 연혁을 알 수 있는 중요한 자료로, 사면비(四面碑)에 찬자(撰者), 서자(書者), 전자(篆者)가 모두 승려라는 점에서 그 특징이 있다.","a":"상주 관음사지 사적비","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663610.jpg"},{"q":"불교의 요지를 42장으로 나누어 석가의 교훈을 적절한 비유와 함께 간명하게 풀이한 것으로 보존상태가 양호하며 판각한 글씨체를 새김에 있어 정교하고 인쇄상태의 선명성과 지질로 보아 귀중한 자료가 되므로 불교사 연구뿐만 아니라 서지학 에 있어서도 가치있는 자료이다. 크기는 가로 14.5cm, 세로 21.5cm 이며 인쇄상태 및 지질로 보아 보아 1384년 판각당시의 인출본으로 생각된다.","a":"불설사십이장경","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638896.jpg"},{"q":"나루터신(津神)을 모시고 있는 제당으로, 신라가 가야(伽倻)를 정벌할 때 왕래하던 나루터가 있던 곳에 자리하고 있다. 앞면 1칸·옆면 1칸으로 구성되어 있고, 옆면에서 볼 때 지붕선이 ‘사람인(人)’자 모양과 비슷한 맛배지붕을 올린 목조건축물이다. 내부로 들어서면 제를 올릴 때 사용하는 제상이 있고, 그 위에 머리가 셋인 용을 그려 놓은 그림이 놓여 있다. 현재의 사당은 조선 태종 6년(1406)에 세운 것으로 전하며, 옛 건축물로서 민속신앙을 보여주는 좋은 예가 되고 있다.","a":"양산 가야진사","c":"시도민속문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659045.jpg"},{"q":"백화산 정상부의 능선과 골짜기를 따라 쌓은 성으로, 신라 김유신 장군이 백제군과 격전한 곳이라고 전한다. 성은 완전하게 무너진 것을 1978년에 국방유적 보수사업으로 80m의 성벽을 복원하였다. 무너진 성벽은 약 4m 폭으로 쌓여 있었으며, 총 연장 둘레는 2∼3㎞이다. 골짜기를 내려오는 성벽의 일부는 약 30㎝ 정도의 아랫부분만 남아있다. 복원된 성벽은 밑부분의 폭이 360㎝이며, 150㎝ 정도의 높이에 군사들이 서서 활동할 수 있는 단을 설치하고, 거기서 다시 아랫폭 125㎝, 윗폭 85㎝의 성벽을 150㎝ 높이로 쌓아 올렸다.","a":"금돌성","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662655.jpg"},{"q":"○○○는 선사 시대의 돌무덤인 고인돌을 말한다. 처음에는 ○○○ 마을 앞 서쪽 들판 입구에 8기가 반경 30m안에 분포되어 있다. 주민들은 예로부터 이 ○○○를 7기로 인식하였고 ‘칠성바위’라고 부르며 일부는 보호 울타리를 둘러 관리하고 있다. 받침돌 위에 올려진 큰 돌을 덮개돌이라고 하는데 ○○○○○의 덮개돌의 규모는 대체로 30cm~60cm이다. 가장 큰 2기의 ○○○의 덮개돌은 340cm×260cm×20cm이다.","a":"고성 학림리 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654907.jpg"},{"q":"○○○○은 담암(淡庵) 백문보(白文寶), 성헌(性軒) 백현룡(白見龍)을 봉향한 서원이다. 기록에는 건립 당시에 영해지방에서 드문 41칸의 대규모였으며, 서원으로서의 면모를 고루 갖추었다고 한다. 대원군의 서원철폐령으로 폐원되었다가, 1899년에 서원 遺址에 書堂을 건립하여 1950년대까지 사설교육의 명맥을 유지하였다. 따라서 전근대교육에서 근대교육으로 이행하는 과정의 양상에서 활용된 건축물로서의 역사문화적 의미를 가진다.","a":"영덕운산서원강당","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663541.jpg"},{"q":"전라감영은 지금의 전북특별자치도와 전라남도 그리고 제주도 등을 모두 관할하였으며, 감사가 총책임자였다. 조선초기에 지은 전라감영은 정문인 포정문(布政門), 감사 집무실인 선화당(宣化堂), 감사의 주거 공간인 연신당(燕申堂) 등 모두 40 여 채의 건물을 거느린 웅장한 규모였다. 그러나 대부분의 건물이 근대화 과정에서 사라지거나, 사고로 인해 불타버렸다. 이 곳은 조선시대 전라도 행정의 중심지로서 뿐만 아니라, 1894년 동학농민혁명 당시 농민군 자치 기구인 집강소의 총본부 대도소(大都所)가 설치된 선화당이 있던 자리로서 역사적 의미가 매우 큰 곳이다.","a":"전라감영지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653712.jpg"},{"q":"고려시대의 왕족 승화후(承化侯) 왕온(？∼1271)의 묘이다. 왕온은 원종 11년(1270)에 고려와 중국 원나라 사이의 전쟁이 끝나고 강화로 피난하였던 왕실이 개경으로 돌아오는 것을 반대하던 삼별초의 배중손·노영희 등에 의하여 왕으로 추대되었다. 그러나 고려 원종 12년(1271) 고려와 몽고의 연합군에 삼별초가 크게 패하자 아들 환(桓)과 여·몽 연합군의 지휘자 홍다구(洪茶丘)에게 살해되었다. 김용규가 지은 진도군 읍지『옥주지』에 왕온의 기록이 나오며,『진도군지』에 의하면 왕온의 묘는 왕분치(王墳峙)라 한다고 한다.","a":"전왕온의묘","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654287.jpg"},{"q":"조선 전기의 문신인 권자신(?∼1456)을 가운데 두고 권책(1442∼?)과 권상길(1610∼1674)의 위패를 함께 모시고 제사 지내는 건물이다. 권자신은 조선 단종의 복위를 도모하다가 사육신과 함께 세조 2년(1456) 살해되었고, 단종 외할아버지 권전의 증손자인 권책은 13살이라는 어린 나이에 단종복위 사건으로 연루되어 영해로 위배되었다. 그는 영해에서 정착하여 살았으며 권상길은 병자호란 때 청(淸)에게 항복하는 것을 반대했던 분이다.","a":"대봉재사","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663243.jpg"},{"q":"조선 세종대의 효자 ○○○의 효행을 기리기 위하여 1633년(인조 11)에 세운 정려문이다. 규모는 정면 1칸,측면 1칸의 맞배지붕 목조기와집으로 사면을 홍전(紅箭)으로 막고, 처마 밑 중앙에는 서하(墅河) 임헌회(任憲晦)가 짓고 전우(田愚)가 쓴 정려기를 달았다. 건물 내부에는 현판 외에 효자비가 자리하고 있다.","a":"진천 김덕숭 효자각","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651357.jpg"},{"q":"북면 외감리 새터마을의 달천정(達川亭)이라는 정자 인근에 있는 우물이다. 조선 숙종 때의 유학자이며 우의정을 지낸 허목(許穆) 선생이 고향에 돌아와 달천정에 머물 때 손수 거북모양의 돌을 깎아 우물을 만들었다고 하여 ‘○○○○’이라고 전하며, 우물의 모습도 거북이 모양이다. 큰 돌을 이용하여 사각형의 우물을 만들었는데 한쪽으로 넓직한 돌을 얹어 놓아 거북의 모습을 닮았다. 이곳에서 1㎞ 쯤 떨어진 천주산 계곡에는 허목 선생이 ‘달천동(達川洞)’이라 직접 새긴 암석이 있어 이 계곡을 달천동 계곡이라 부르게 되었다.","a":"창원 달천구천","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654867.jpg"},{"q":"○○○는 802년(신라 애장왕3)에 원효에 의해 창건된 사찰(보광사)이나 임난에 소실되었다. 1661년에 학진스님이 인근에 있는 보광사 건물을 옮겨와 용연 위쪽에 터를 잡았다 하여 ○○○라고 이름을 붙이고 중창하였다. 임난 이후 호국도량으로 알려져 숙종때(1674~1720) 왕실의 축원당을 세웠고, 이후 네 번의 중수가 있었다. ○○○에는 ｢佛丘山鳳捿樓並序｣(1720년)와 ｢靈山殿天王閣鳳捿樓重修記｣(1833) 등이 남아있는 것으로 보아 초창은 1720년에, 현재의 모습을 보이는 구성의 중창은 1833년에 이루어진 것으로 판단된다.","a":"남해 용문사 봉서루","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665826.jpg"},{"q":"조선 전기 충신으로 단종 복위를 위해 애쓴 사육신(死六臣) 중 ○○○ 선생의 위패를 모시고 제사를 지내는 ○○이다. ○○○은 세종 29년(1447) 문과에 급제하고 집현전의 관원이 되어 신숙주, 유성원 등 젊은 학자들과 편찬사업에 참여하였다. 수양대군이 어린 단종의 왕위를 빼앗은 울분을 참지 못하고 자결하려 하였으나, 성삼문의 만류로 단념하고 죽음을 각오하고 단종 복위 운동을 계획하였다. 그러나 김질의 밀고로 실행하기도 전에 발각되자 그의 재주를 아깝게 여긴 세조의 회유에도 뜻을 굽히지 않다가 성삼문·하위지·이개·유성원 등과 함께 참형을 당했다.","a":"충주 박팽년 사당","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649514.jpg"},{"q":"통일신라 사찰인 ○○○ 경내에 서 있는 3층 석탑이다. 처음에는 스님들이 기거하는 요사채 앞에 있었으나 1974년 대웅전 앞으로 옮겨 세워 일부 보수한 것이다. 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 통일신라시대의 전형양식을 보이고 있다. 위·아래층 기단의 각 면에는 모서리와 가운데에 기둥 모양의 조각을 두었고, 탑신의 몸돌에는 모서리에만 기둥 모양을 새겼다. 지붕돌은 밑면에 5단씩의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식받침)과 보주(寶珠:작은 공모양장식)가 놓여 머리장식을 하고 있는데, 보주는 후대에 끼워 넣은 것이다.","a":"창원 의림사 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641504.jpg"},{"q":"몸통 부분의 세 곳에 소나무와 그 아래에 있는 집이 청화(靑畵)로 그려진 백자병으로 그림의 구도와 솜씨가 뛰어나다. 담청색이 감도는 고운 백자유약이 입혀졌는데 빙렬(氷裂)은 없으며 광택이 좋다. 굽은 단정하게 깎은 다리굽으로 굽다리 바닥에 가는 모래를 받치고 구웠다. 유면 속에 가는 기포(氣泡)가 꽉 차있어 미세하나마 반실투성(半失透性)의 유조를 보여주고 청화문양이 선명하지 않고 번진 흔적을 보이고 있다. 병의 규모와 18c전반 금사리 요지 유형이라는 점에서 특별한 점이 있고, 동 시기 백자에서는 보기 힘든 ○○○이 시문(施文)되어 회화성이 뛰어나다.","a":"백자청화송옥문병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593094.jpg"},{"q":"이 불상은 도개면 신곡리 산68번지에 위치한 문수사 경내에 있는 석불 좌상(坐像)이다. 도개중학교 교정에 있었으나, 학교 증설로 인해 2008.1.10 문수사로 옮겨왔다. 불신과 광배(光背), 대좌(臺座)가 하나의 돌로 이루어졌는데, 광배의 윗부분과 머리 부분이 깨진 상태다. 사각형의 대좌 위에 앉아 있으며, 대좌 아래까지 옷자락을 내려뜨리고 있다. 오른손은 어깨에 들어 올려 연꽃가지를 잡고 있고 왼손은 배에 대고 있는데, 손모양으로 보아 어느 본존불의 협시보살로 생각된다.","a":"선산 궁기동 석불상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640471.jpg"},{"q":"경주시 서악동에 있는 신라의 왕족 김양(808∼857)의 묘이다. 태종 무열왕의 9대손으로 흥덕왕 3년(828)에 고성 태수가 되었고 무주 도독을 지냈다. 가는 곳마다 많은 공적을 남겨 명성이 높았다고 한다. 830년에 장보고와 함께 민애왕을 죽이고 우징(신무왕)을 왕으로 추대하여 모셨으며 신무왕이 일찍 죽자 뒤를 이은 문성왕을 다시 모셨다. 문성왕 19년(857)에 나이 50세로 죽자 그에게 대각간(大角干)의 벼슬을 내리고 태종 무열왕의 릉(陵) 서열에 따라 그 곳에 같이 모셨다. 특별한 시설 없는 비교적 큰 무덤이며 흙으로 높게 쌓아 올린 원형봉토분이다.","a":"김양묘","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654439.jpg"},{"q":"광주광역시 광산구 송정동에 있는 이 성터는 태조 6년(1397) 전라도 병영을 이곳에 설치하면서 쌓았다가, 태종 17년(1417) 강진 병영성으로 옮기면서 사용하지 않은 성으로 고병영성이라고도 불린다. 『신증동국여지승람』에는 돌로 쌓은 성으로 성벽의 둘레가 1,661척이라 기록되어 있어 처음에는 돌로 쌓았음을 알 수 있으나, 성벽의 대부분은 무너지고 송정동 일대에 성과 관련된 땅 이름이 남아있는데 광주비행장이 ‘성안엣들’이라 불리웠고, 고내상 서쪽 들이 ‘성너맷들’이라 하였다.","a":"고내상성지","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659604.jpg"},{"q":"전남 해남군 북평군 이진리 해안에 돌로 쌓은 성이다. 선조 21년(1588)에 군대의 진을 세우고 인조 5년(1627)에 만호진으로 승격되었는데 이 당시에 쌓은 것으로 보인다. 『여지도서』의 기록에 보면 군 남쪽 120리에 있고 성은 돌로 쌓은 석성으로, 둘레는 1,470척, 높이 8자이며 샘이 2개있다고 전한다. 『문화유적총람』에는 둘레 2.5㎞의 성지로 인조 26년(1648)에 만호(각 진에 배치한 종4품의 무관직)를 두어 성을 세웠고, 성 주위로 바다 호수를 만들어 왜군이 침입하지 못하게 하였다고 한다.","a":"이진성지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052020401600.JPG"},{"q":"○○○○는 조선시대의 대표적 해시계로 조선 세종(朝鮮 世宗) 때 처음 만들어진 이후 다양한 형태로 제작되었는데 서울역사박물관에 소장된 이 ○○○○는 가로 3.1㎝×세로 7.2㎝×높이 3.8㎝ 크기의 옥돌에 소형 나침반을 부착하여 휴대용으로 간편하게 사용할 수 있도록 만든 것이다. 반구형(半球形)인 해시계 면의 직경은 3cm이고 나침반의 직경은 1.9cm인데 나침반 주위에 24향(向)이 표시되어 있다.","a":"앙부일구(2002)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590301.jpg"},{"q":"이 사당은 영조 4년(1728) 무신란 때 향리로 있던 신극종 · 신석현 · 신덕현 · 신치근 · 신광세 등이 창의하여 반군을 무찌르는데 용력을 다한 다섯 충신을 제향하는 곳으로 일명 오충사라고도 한다. 난이 평정된 후 정조 12년(1788)에 사우를 건립토록 하였고, 이들 다섯 충신은 후에 공조좌랑으로 추증되었다. 건물 배치는, 강학공간인 성암서당과 사당인 ○○○가 동향과 남향으로 세워졌는데 사당은 정면 3칸, 측면 2칸의 맞배지붕이고 내삼문은 정면 3칸의 솟을 대문으로 되어 있다.","a":"거창 창충사","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663989.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 태조 1년(1392)에 능주 서쪽에 지었으나 임진왜란 때 불에 타 없어져 선조 33년(1600)에 하응도가 지금의 자리로 옮겼다. 그 뒤에 여러 차례의 수리를 거쳐 오늘에 이르고 있다. 경사진 곳에 위치하여 뒤쪽 높은 곳에 대성전과 동무·서무가 제사공간을 형성하고, 앞쪽에는 명륜당과 동재·서재가 배움의 공간을 형성하여 전학후묘의 배치를 이루고 있다.","a":"능주향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639986.jpg"},{"q":"단종의 왕비인 정순왕후 송씨를 추모하기 위해 세운 비이다. 송씨는 단종이 영월에서 죽음을 당하자, ○○○에 머물며 평생동안 그의 명복을 빌었다. ○○○은 여승방(女僧房)으로 원래 창덕궁에서 그리 멀지 않은 도성안에 있는 것인데, 성 밖에 있었다는 전설에 따라 이곳에 비를 세우고 비각도 짓게 되었다. 이는 정순왕후 송씨가 동대문 밖인 이곳에서 지냈던 사실과 ○○○의 주지로 있었던 일이 얽혀서 잘못 전해온 것으로 보인다. 조선 영조 47년(1771)에 세운 비로, 비문 일부와 비각 현판의 글은 왕이 손수 쓴 것이다.","a":"정업원 터","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636049.jpg"},{"q":"○○○○는 원래의 사찰명은 알 수 없으나 그 동안의 발굴조사 결과 남북자오선상에 중문―탑(목탑)―금당순으로 건물을 배치하였던 전형적인 백제 사찰지이다. 이 사지에서 출토된 치미, 금동판, 소조불두, 금동제 과판, 청동제 등개, 벽화편 등으로 보아 백제왕실의 원찰성격이 강한 중요사찰지로서, 사지의 축조공법 또한 정교하여 백제사원 양식 연구에 중요한 유적으로서 보존가치가 크다.","a":"부여부소산성서복사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019051415102500.jpg"},{"q":"조선 정조대의 문신이자 실학의 대가였던 다산(茶山) ○○○ 선생의 묘이다. 수원 화성의 성곽제도를 만들고, 공정을 단축시키는 거중기를 제작하여 수원성을 축조하는 데에 크게 공헌하였다. 선생은 학문 연구에 전념하여 『목민심서』 · 『경세유표』 · 『흠흠신서』 등 500여 권의 저서를 남겨 민생을 위한 개혁에 크게 공헌하였다. 묘역은 부인 풍산홍씨(豐山洪氏)와 합장된 하나의 봉분 형태이다. 묘제(墓制)는 대부분 새 석물로 구성되어 있는데, 1970년대 이후에 새롭게 정비한 것이다. 봉분 정면 오른쪽에는 묘표를 1기 세웠는데, 1959년에 새로 제작하였다.","a":"정약용선생묘","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645941.jpg"},{"q":"우리나라에서 흔하지 않은 ○○○○○으로 ○○○ 대웅전 앞에 건립되어 있다. 기초가 되는 지대석은 2장의 판석으로 구성했으며, 팔각형으로 되어있다. 지대석 위에는 2매 석으로 구성된 하층 기단을 놓았는데, 측면 하단에는 상각(象脚) 문양을 조각했고, 상단에는 각 면에 사각형 액(額)으로 공간을 구획한 후에 2조의 안상(眼象)문양을 조각했다. 상층기단은 아래서부터 하대, 중대석, 상대의 순서로 배치되어있다. 하대에는 상각, 안상(眼象)문양, 복연 연판문양 순서로 표현했다. 중대석은 둥근 기둥 형태의 겹우주를 모각한 후, 8면에 안상 문양을 표현했다.","a":"남양주 묘적사 팔각다층석탑","c":"시도유형문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052014172800.jpg"},{"q":"오래된 소나무 숲 앞쪽에 자리하고 있는 이 집은 김형기씨의 11대조부터 살기 시작한 곳으로 조선 영조 2년(1726)에 지었으며, 그 후 많은 수리를 거쳤고 1922년에도 보수를 하였다. 행랑과 대문으로 구성된 별채는 후대에 지은 것으로 보인다. 안채와 사랑채는 ㅁ자형의 배치를 하고 있다. 앞면 4칸·옆면 2칸의 안채는 겹집의 형태이다. 가운데에 있는 대청을 중심으로 양쪽에 2개씩 방이 있으며, 대청 뒤쪽으로 1칸씩을 나누어 제실과 마루방을 두었다. 대청의 중앙 앞면 기둥만 원기둥으로 처리한 것이 매우 특이하다.","a":"동해 김진사 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638066.jpg"},{"q":"○○○은 남구 황성동 세죽마을 해변에서 약 150m 떨어진 바위섬이다. ○○○의 유래 전설은 『삼국유사』에 실려 있다. 신라 헌강왕(憲康王 : 재위 875~886년)이 이곳에 놀이를 와서 쉬고 있을 때, 갑자기 구름과 안개가 가려 앞을 볼 수 없었다. 일관이 동해 용(龍)의 조화이니 좋은 일을 해주어 달래주어야 한다고 보고하였다. 왕이 즉시 이 근처에 용을 위한 절을 세우도록 명령하자 구름과 안개가 걷혔다고 한다. 그리하여 이곳을 개운포라 이름을 붙였다고 한다. 또한 당시에 세운 절은 현재 울주군 청량면 율리에 터가 남아 있는 망해사(望海寺)이다.","a":"처용암","c":"시도기념물","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645859.jpg"},{"q":"조선 중기 권사균이 지은 것으로 조선 고종 4년(1867)에 화재로 불타버린 것을 이듬해 다시 세웠다. 앞면 4칸·옆면 3칸의 규모이며，지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 건물 앞면에는 정현석의 낙관이 찍힌 현판이 있으며 기둥마다 세로로 글씨가 쓰여 있다. 앞쪽 처마 위에는 고리를 설치하여 여름에는 문을 들어올려 더위를 식힐 수 있도록 하였다. 안쪽은 오른편에 방 1칸을 두고 왼편 3칸은 마루를 만들었다.","a":"보진당","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660314.jpg"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 전기 중종반정 때의 공신인 나재 ○○ 선생의 공적을 기리고 있다. ○○ 선생은 세조 14년(1468) 생원이 되고, 이듬해에 과거에 장원급제하여 사헌부감찰을 시작으로 여러 관직일을 맡아보았다.『세조실록』·『예종실록』의 편찬에도 참여하였으며, 성종 8년(1477) 홍문관 응교가 되어 도승지 임사홍의 간악한 죄상을 아뢰어 몰아내기도 하였다. 대사헌으로 있을 때에는 폐비 윤씨를 옹호하다가 왕의 노여움을 사 벼슬에서 물러났다가, 성종 16년(1485)에서야 다시 기용되었다.","a":"난재 채수 신도비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640987.jpg"},{"q":"○○○○○를 그린 불화승은 18세기 후반 전국을 무대로 활동한 인물로 설채법과 구도 및 필선 등은 18세기 후반 불화양식을 잘 반영하고 있으며, 왕실에서 발원한 의미성과 조선후기 불교회화사에서 중요한 작품이다.","a":"화성 용주사 삼장보살도","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637797.jpg"},{"q":"○○○은 비로자나불을 모시고 있는 법당으로 이곳에는 석조비로자나불좌상(보물 제433호)을 모시고 있다. 낮은 기단 위에 정남향을 바라보고 있으며, 주춧돌은 신라시대의 것을 그대로 사용하고 있는 건물이다. 그 위에 둥근 기둥을 올렸으며, 기둥은 가운데만 약간 굵게 하였다. 앞면 3칸·옆면 3칸 규모로 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 기둥 위에서 지붕 처마를 받치는 공포가 기둥위와 기둥 사이에도 있는 다포계 양식의 건물이다. ○○○○○은 조선 후기의 건축물로 전체적으로 단아하며, 당시의 건축기법을 잘 보이고 있다.","a":"괴산 각연사 비로전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638587.jpg"},{"q":"고려 전기의 사람인 ○○○·이순 형제의 효행과 형제의 의를 기리기 위해 세운 비이다. 『신증동국여지승람』의 기록에 의하면 형제가 모두 지극한 효성으로 부모를 섬겼다고 한다. 부모가 돌아가신 후에도 형은 아버지 묘를 지키고 동생은 어머니 묘를 3년간 곁에서 지키며 돌보았다. 한가지 음식이 생겨도 형제 중 한사람이 없으면 먹지 않았으며, 아침은 형집에서 저녁은 아우집에서 아침과 저녁을 같이 들었다. 조선시대의 조정은 이 사실을 표창하여 비를 세우도록 하였다. 비는 길쭉한 비몸 위로 머릿돌을 얹은 모습이며, 밑에 있는 받침돌은 후대에 와서 만든 것이다.","a":"예산이성만형제효제비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639176.jpg"},{"q":"○○○ 소장의 벽암존자○○은 전형적인 18세기 후반 초상화의 양식적 특징을 잘 보여주고는 있으며 화면 중앙에 오른쪽을 향하여 의자에 앉아 있는 벽암존자상(碧巖尊者像)을 단독 배치한 ○○으로 대각선 구도를 보여 정적인 화면에 운동감을 부여하고 있다. 근엄한 듯 자상한 얼굴에 오른 손은 무릎 위로 내려 검지손가락을 들어 변화를 주고 있으며, 왼손은 의자 팔걸이에 기댄 채 왼 어깨에 걸친불자(拂子)를 잡고 있다.","a":"합천 해인사 국일암 벽암선사 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643133.jpg"},{"q":"금성산에서 남쪽으로 흘러내린 산줄기가 다시 높아지면서 독립구릉의 정상부을 형성하는데 고분은 여기에 위치하고 있다. ○○○이 있는 독립구릉은 북쪽은 급경사를 이루고 남쪽은 완만하게 내려오는데 1호분은 구릉의 정상부에 있고 서북쪽으로 조금 떨어져서 2호분이 자리하고 있다. 1호분은 주변 지역이 밭으로 개간되고 고분 입구에 단풍나무가 심어져 있는 것으로 보아 변형이 있는 것으로 생각되지만 심하지는 않고 비교적 그 형태가 잘 남아 있다. 마을 주민들에 의하면 둥근 형태의 이 고분에 돌방무덤이 있었는데 3∼4명이 들어갈 정도로 규모가 큰 것이었다고 한다.","a":"영암금강리금산고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654348.jpg"},{"q":"李公沂는 조선시대 宣祖年間(재위 : 1567∼1608)에 어의를 지낸 인물이다. 임진왜란 때 선조를 호종한 공으로 扈聖功臣 3等에 책록 되었으며, 녹봉으로 제천의 토지를 하사받아 제천에 정착하였던 것으로 믿어진다. 제천시 송학면 도화리에는 아직도 후손 한산이씨가 집성촌을 이루고 있으며, ○○화 역시 도화리 한계군 영당에 봉안되어 있다가 교서와 함께 제천시에 기증되었다. 敎書는 선조 37년(1604) 10월에 韓溪君 李公沂에게 내린 공신 교서이다. 비단에 두꺼운 선지를 포개 붙여 만든 것으로 가로 19㎝, 세로 39㎝의 두루마리 형태이다.","a":"이공기 호성공신교서 및 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638945.jpg"},{"q":"세종실록지리지에 ○○도호부 동쪽에 하품(下品)을 생산하던 감물야촌(甘勿也村)에 1개의 자기소가 있었다는 기록이 있으며, ○○면 대감리라는 지명이 대감물야리 (大甘勿也里)가 축약되어 생긴 지명으로 조선시대 공납 자기소일 가능성이 높은 지역이다. 또한 신청지역 일부에 대한 발굴조사 결과 ○○○○ 가마 1기와 폐기장 3개소가 확인되었고 1호 가마와 1호 폐기장 하부에서 삼국시대 분묘가 확인되었다.","a":"김해 상동 분청사기 가마터","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019042213143900.jpg"},{"q":"공주 ○○○○○은 공주시 동남쪽에 위치한 월성산(月城山) 서남단 자락인 공주시 옥룡동―○○○을 연결하는 공주터널 상층부에 위치하고 있으며, 이 지역 일대는 물안주(無雁州)로 불리어져 왔다. 일제시대에 6기의 횡혈식 석실고분이 발견·조사보고 되었으며, 1960년대에는 궁륭식 석실분 1기, 1989년의 공주터널 건설공사 시에는 횡혈식 석실분 2기가 수습·조사되었다. 2000년 발굴조사 시에는 횡혈식 석실분 21기, 횡구식 석곽분 2기, 수혈식 석곽분 3기, 석곽 옹관묘 3기, 토광묘 9기, 외곽묘 1기, 수혈유구 3기, 미상유구 1기 등 총 43기의 유구가 발견되었다.","a":"공주금학동고분군","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653186.jpg"},{"q":"화강암 판석 1매에 보주형 광배와 불신을 부조한 불상으로소발위에 두터운 육계가 표현되었으며 눈썹은 반원형이며 얼굴은 통통하게 살이 쪘다. 양귀는 어깨까지 닿으며 삼도가 표현되었다. 법의는 통견이며 왼손을 가슴에 대고 그 위에 약합을 쥐고 있으며 오른손은 가슴위까지 올려 손바닥을 밖으로 향하고 있다. 대좌는 장방형 판석에 연화문을 새기고 불상을 끼우도록 되어 있으나 원래의 것은 아닌 것으로 보인다.","a":"충주 창동리 석조약사여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638906.jpg"},{"q":"한채의 비각에 걸려있는 3기의 현판과 그 안에 서 있는 2기의 비로, 한 집안내의 한 효자와 두 열녀의 언행과 정신을 기리고 있다. 박진환(1605∼1650)은 조선 중기의 인물로, 평소에도 효성이 지극하였는데 상주지역에 머물고 있던 아버지가 병으로 위독해지자, 이내 달려가 지극정성으로 간호하였다. 간호한 보람도 없이 아버지가 돌아가시자 고향으로 옮기어 묘소를 마련하였으며, 3년간 곁을 지킨 후 몸이 약해져 46세로 생을 마치었다.","a":"봉곡동 효열비각","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663279.jpg"},{"q":"‘○○○○’는 고려에 대한 충성과 절개를 끝까지 지키다가 죽은 영혼을 기리기 위해 제사를 지내는 사당 터이다. 이곳은 고려 말의 충신 여섯[조견(趙狷), 원선(元宣), 이중인(李中仁), 김양남(金揚南), 유천(兪蕆), 김주(金澍)] 사람 등의 위패를 모신 곳이다. 이들은 새 왕조인 조선의 임금 섬기기를 거부하고 세상을 피해 숨어서 살다가 여생을 마친 사람들이다. 1798년에 사당을 짓고 ‘삼귀서사(三歸書祠)’라 하였는데 1804년에 ‘송산사(松山祠)’로 이름을 고쳐 불렀다.","a":"송산사지","c":"시도기념물","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646063.jpg"},{"q":"율재 정경(1490∼1564)을 모신 사당으로 후손들이 세웠다. 정경 선생은 조선 중종 때 무신으로, 효성이 지극하고 청렴결백하여 인근에 그 이름이 알려졌다. 임진왜란으로 건물이 무너져 정조 14년(1790)에 다시 지었으며 1970년대에 와서는 처마를 아름답게 단장하였다. 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다. 대청마루를 사이에 두고 좌우에 방을 두었는데 방·부엌·마루·건넌방·건넌방 부엌으로 구성되어 있다.","a":"영동 송담재","c":"문화유산자료","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660759.jpg"},{"q":"조선 숙종 31년(1705) 이세필이 삼척부사로 있으면서 삼척의 학문을 일으키기 위해 ○○○○을 창건하고 학규 21조를 제정하여 이것을 손수 써서 판각한 것으로, 오늘날의 교칙에 해당하는 것이다. 이 ○○○○은 피나무판으로 가로 156㎝, 세로 48㎝의 크기이다. ○○○○은 그후 고종 5년(1865) 대원군의 서원철폐령으로 인해 문을 닫았다가 1966년 이곳의 사림들이 유서가 깊은 서원이라고 생각하여 지금의 건물로 새로 지어놓았다.","a":"용산서원 학규현판","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638050.jpg"},{"q":"◦ 조선후기 팔작지붕으로 된 ㅡ자형의 고택으로, 왼쪽에 부엌을 설치하고, 앞에는 마루를 설치하였는데, 마루 앞에는 분합문(分閤門)을 달았으며, 지붕 기와에 옹정8년(擁正八年)이라는 글씨가 발견되어 1730년에 지어진 건축물로 짐작할 수 있음.","a":"편무성가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661383.jpg"},{"q":"조선 세조와 성종간의 문신인 ○○○ 선생의 묘역이다. ○○○은 1455년(세조 1)에 좌익공신에 올랐다. 봉분은 부인 청주 정씨(淸州鄭氏)와 합장한 하나의 봉분이고 둘레석은 현대의 것이다. 봉분의 정면 오른쪽에 묘표가 2기 있는데, 1기는 ○○○, 다른 1기는 청주 정씨의 묘표이다. 청주 정씨의 묘표는 하엽수방부형(荷葉首方趺形; 뒤집은 연잎을 장식한 머릿돌과 사각 받침돌의 비석 형태)으로 연엽의 조각이 깊고 명확한 15세기 후반의 대표적인 형식이다. ○○○ 묘표는 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)으로 16세기 전반기의 형태이다.","a":"정창손묘역석물","c":"문화유산자료","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660128.jpg"},{"q":"종은 절에서 쓰이는 도구 중 하나로서 시간이나 의례를 알리거나, 복음을 전달하는데 사용한다. ○○○은 내원사 계곡에 있었다고 전하는 89암자 중의 하나로서, 내원사 창건 당시 암자가 폐쇄되었던 것을 조선 인조 24년(1646)에 영훈대사가 중건한 것으로 비교적 잘 보존되어 있다. 이 종은 어깨부분에 ‘범’자를 원안에 새겼으며, 몸통 위쪽 주위에는 돌출된 9개의 유두가 있었으나 2개는 파손되었다.","a":"양산 안적암 동종","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664241.jpg"},{"q":"갈계리 ○○○은 조선 명종 계해(1563)년에 안음 현감 박응순이 임훈, 임운 형제의 효행을 널리 알려 생전에 내려진 생정려 2위와 순조 임진년(1832)에 정려된 임한신과 한신의 처 고령 박씨, 고종 28년 신묘년(1891)에 정려된 임경원, 광무 9년(1905)에 정려된 임지예를 추가하여 모두 6위의 정려를 모시는 ○○○이다. 하지만 6위의 정려 현판은 물론 정려기 현판도 전해지지 않고 현재 6기의 비석이 서있다.","a":"거창 은진임씨 정려각","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666355.jpg"},{"q":"조계는 지방행정권을 외국인에게 위임한 외국인전용 주거지역을 이르며, ○○○은 이러한 지역의 경계를 표시해 놓은 일종의 푯말이다. ○○에는 1883년 일본전관조계를 시작으로, 1884년 화상지계·○○조계 등 3개의 조계가 설정되었는데, 그 중 이 ○○ 조계는 우리나라와 미국·영국·청국·일본·독일 대표 사이에 체결된 “○○제물포○○조계장정”에 따라 지정된 것이다. 약 14만평 규모의 송학동·송월동·만석동 일대 외국인 주거지역의 경계를 표시한 것으로, 각 면이 잘 다듬어진 4각을 이루고 있다.","a":"인천 각국 조계석","c":"문화유산자료","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659526.jpg"},{"q":"백산 ○○○ 선생의 ○○이다. ○○○는 독립운동가로 창남학교, 의신학교 등을 설립하여 신학문 보급에 힘을 썼으며, 민족언론의 선구자 역할도 하였던 분으로 59세로 생을 마감하였다. ○○는 안채, 사랑채 2동으로 되어 있다. 안채는 앞면 6칸·옆면 2칸 규모에 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 왼쪽에서부터 마루·방·대청·방·부엌 순으로 배치되어 있다. 사랑채는 앞면 4칸 규모의 초가 건물로 안채와 바짝 붙어 있다. 이들 건물은 모두 동쪽을 향하고 있고, 남쪽으로 마루를 1칸씩 구성하고 있어 특이하다.","a":"의령 안희제 생가","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664302.jpg"},{"q":"조선말기의 유학자인 壺山 朴文鎬(1846～1918)가 스승인 李象秀(1820～1882)가 강학하던 옛 집터에 1911년 추양정사를 건립하고 ○○○의 영정을 봉안하였다. 그 후 박문호를 비롯한 ○○○의 문하에서 배출된 梁柱承(?～1910), 梁柱學(1850～?), 朴龍鎬(1859～1927), 朴洵行(1866～1916), 양주하의 영정을 함께 봉안하고 춘추로 제향 하였으나 대청댐 건설에 따른 수몰로 1995년 현재 위치인 보은군 회남면 금곡리로 이전하였다.","a":"이상수･박순행･박용호･양주승 초상","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660831.jpg"},{"q":"고려 초기의 문인 계림(鷄林) ○○○의 묘소이다. 그는 탐라(지금의 제주) 성주로 있다가 인종 7년(1129)에 시어사가 되고 1130년에는 사신으로 금나라에 다녀왔으며 여러 관직을 역임하다 중서시랑평장사의 벼슬에까지 올랐다. 또 인조 13년(1135)에는 김부식과 함께 묘청의 난을 평정하는데 큰 공을 세우기도 하였다. 제주도의 분묘 중 방묘형태(方墓形態)로 석물 등이 가장 잘 보존되어 제주도 기념물로 지정되었으며, 매년 4월 9일에는 제주 고씨 문중의 주관으로 제향이 올려지고 있다.","a":"문경공고조기묘","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657877.jpg"},{"q":"임진왜란 당시 적의 눈을 속이기 위해 돌로 사람의 형상을 만들어 세운 것이라고 전해 오는 석조물이다. 원래 7개였다고 하나 6개는 없어지고, 두건에 도포를 입고 팔짱을 낀 전형적인 문인(文人) 형상을 하고 있는 석인상만 유일하게 남아 있다. 단, 하나의 비석으로 당시의 의인전술(擬人戰術)을 밝히기는 어려우나, 조선 중기 돌 신앙으로서의 민속학적 가치와 조각 작품으로서의 예술적 가치를 살필 수 있는 자료이다.","a":"여수석인","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639857.jpg"},{"q":"대구 ○○○ 중앙봉의 정상 가까운 절벽에 새겨진 거대한 크기의 ○○○○불상이다. 민머리 위에는 상투 모양의 머리묶음이 큼직하며, 탄력있고 우아한 얼굴은 이목구비가 세련되고 단아하다. 둥근 어깨는 탄력있어 보이며, 허리는 잘록하게 표현되었다. 무릎에서 밖으로 내려뜨린 오른손과 무릎 위에 얹어 약 그릇을 들고 있는 왼손의 세련성 등은 이상적인 사실주의 양식을 보여주고 있다. 왼쪽 어깨를 감싼 옷은 몸의 굴곡이 드러날 정도로 얇은 편인데 옷주름은 자연스럽고도 규칙적이며, 가슴에서 옷깃이 한번 뒤집히는 등 8세기 불상의 특징을 보이고 있다.","a":"팔공산마애약사여래좌상","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636843.jpg"},{"q":"면우 곽종석 선생을 추모하기 위하여 유림과 제자들이 설립한 서당이다. 곽종석(1846∼1919) 선생은 유학자이며 독립의사로 많은 후진을 양성하였다. 1919년에는 파리평화회의에 보낼 파리장서를 작성하여 보내는 과정에서 일본 경찰에 발각되어 투옥되었다. ○○○○이라고도 하는 이곳은 1920년에 세운 것으로 사우는 1919년에 세웠다. 서당은 강당, 서재, 사우로 구성된다. 강당은 앞면 5칸·옆면 1칸 반 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"산청 이동서당","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664308.jpg"},{"q":"각금당 심장세(覺今堂 沈長世, 1594 ~ 1660), 두곡 홍우정(杜谷 洪宇庭), 포옹 정양(抱翁 鄭瀁), 잠은 강흡(潛隱 姜恰), 손우당 홍석(遜遇堂 洪錫) 諸賢의 會同 交遊之處로 巖曰 竢德이요 臺曰臥仙이라 하고 亭子를 建立 臥仙亭이라 하였다. 丙子胡亂(1636)에 벼슬도 단념하고 太白山下 春陽에 隱居 大明節義를 지키며 世稱 太白五賢이라 하였다. 五賢의 遺德을 追慕하기 위하여 後孫들이 연 1회씩 會同 修稧하고 있다.","a":"와선정","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663622.jpg"},{"q":"○○○ 건물내에는 신라 최초의 김씨 임금인 13대 미추왕(味鄒王)과 삼국통일의 대업을 이룩한 30대 문무대왕(文武大王), 그리고 신라 마지막 임금인 경순왕(敬順王)의 위패를 모셨다. 원래 신라 마지막 임금인 경순왕(敬順王)의 덕을 기리기 위하여 처음 월성(月城)에 사당을 지어 영정(影幀)을 모시고 제향했으나, 조선 선조(宣祖) 25년(1592) 임진왜란으로 불타고 인조(仁祖) 5년(1627) 동천동에 새로 사당을 지어 동천묘(東泉廟)라 하고 경순왕의 위패를 모셨다.","a":"숭혜전","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662972.jpg"},{"q":"덕은사 경내에 있는 ○○○은 일두 정여창(1450∼1504) 선생이 은거하면서 학문을 연구하고 제자를 양성하던 정자이다. 조선 전기 문신이자 학자인 정여찬 선생은 김종직(金宗直)의 제자로, 경학과 성리학을 연구하였으며, 학식이 높고 행실이 단정하여 사람들로부터 칭송받았다. 건물은 15세기 말경에 지은 것으로 추정하며 고종 38년(1901)에 군수의 지원과 후세의 참여로 다시 고쳐 지었다. 1920년에 3칸이던 건물을 4칸으로 덧붙여 지었고, 1994년에 도·군의 지원으로 크게 보수하였다. 규모는 앞면 4칸이며 방·대청 2칸·방의 순으로 구성되어 있다.","a":"하동 악양정","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664361.jpg"},{"q":"대전광역시 중구 보문산 사정공원 입구의 서쪽 해발 160m의 산 위에 위치한 산성으로, 산꼭대기를 빙둘러 돌로 쌓아올렸다. ○○○은 대전에서 진산으로 통하는 길목을 지키기 위하여 쌓았던 것으로 보이며, 남쪽으로 흑석동산성, 북쪽으로는 월평동산성과 연결되어 있고, 대전 동쪽의 산성들과 연결되는 지점이기도 하다. 성벽의 둘레는 약 350m였을 것으로 짐작되지만, 전부 허물어진 상태여서 현재는 그 윤곽만 확인할 수 있을 뿐이다. 성의 안쪽은 서쪽으로 완만하게 경사를 이루고 있으며, 동남쪽 높은 곳에 건물터가 남아 있다.","a":"사정성","c":"시도기념물","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645797.jpg"},{"q":"○○○는 신라 무염대사가 처음 지었다고 전하고 있으며, ○○○은 조선 순조 19년(1819)에 세웠다고 한다. ○○○은 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 안쪽 가운데에 석가모니불을 그 좌우에 지장보살과 관음보살을 모시고 있는데, 불상의 수법과 양식으로 보아 조선시대 작품으로 추정한다. 그 외에 아미타여래후불탱화 2점, 신중탱화 1점, 현왕탱화 1점, 칠성탱화 1점과 목조나한상 1구가 있다.","a":"심곡사대웅전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661700.jpg"},{"q":"돈대란 적의 움직임을 살피거나 공격에 대비하기 위하여 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련해두는 초소이다. 대개 평지가 높은 곳에 마련해두며, 밖은 성곽으로 높게 하고, 안은 낮게 하여 포를 설치해둔다. ○○도 외포리 마을에 축조된 이 돈대는 다른 것과는 달리 둥글게 쌓여 있으며, 대포를 올려놓는 받침대가 4곳 설치되었다. 성위로 낮게 쌓은 담이 55개 있었다 하나 지금은 모두 사라지고 그 흔적만 남아있다. 조선 숙종 5년(1679) ○○유수 윤이제가 병조판서 김석주의 명을 받아 쌓은 것으로, 경상도 군위어영군 8천여명이 동원되었다 한다.","a":"강화 삼암돈대","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101617115400.jpg"},{"q":"○○○에 보존되어 있는 그림으로, ○○○○○을 중심으로 여러 보살들과 제자상들을 그린 ○○○○○도이다. 이 ○○○○○도는 비단 바탕에 채색하여 그려진 것으로, 화면은 중앙에 크게 강조된 ○○○○○ 본존을 중심으로 여러 보살들과 제자상들이 배치되어 있다. 본존의 육신부는 황백토를 바르고, 육신선은 가는 담묵선으로 처리하였다. 가사는 주색을 바르고 그 위에 백색으로 원화문(圓花文)과 소형화문(小形花文)을 흩뜨리고 있다. 본존의 머리와 몸 뒤에는 부처의 몸에서 나오는 빛을 상징하는 광배(光背)가 각각 원형으로 표현되어 있다.","a":"범어사비로자나불회도","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659358.jpg"},{"q":"본 작품은 약사전 후불탱으로 1775년 ○○○ 불화제작의 주요인물인 화사 포관(抱冠) 등이 제작한 작품이다. 본존의 신광을 중심으로 보살과 신중들이 지니고 있는 지물과 의문에 금분을 적절하게 사용하여 화면에 생기를 더하고 있으며, 신장상의 다양한 복식 또한 귀중한 자료적 가치가 있다.","a":"양산 통도사 건륭40년명 약사여래후불탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642471.jpg"},{"q":"선돌은 길쭉한 자연석이나 커다란 돌을 일부만 다듬어 똑바로 세운 기념물 또는 신앙대상물을 말한다. 입석리 마을 입구에 서 있는 이 선돌은 마을의 당산으로 수호신 기능을 하여, 재앙을 막아주고 풍년을 기원하는 대상이 되고 있다. 사각기둥 모양의 자연석으로 높이 210㎝, 너비 62㎝, 두께 40㎝의 크기이다. 윗부분은 마모가 심하여 확실치 않으나 사람 얼굴 형상과 같은 것이 표현되어 있다. 이곳에서는 매년 음력 정월보름에 당산제를 지낸 뒤 남녀로 편을 나누어 줄다리기를 하는데, 여자편이 이겨야 풍년이 든다고 믿고 있다.","a":"월촌입석","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658294.jpg"},{"q":"조선 후기 학자인 추사 ○○○의 유적으로 추사고택과 이 일대를 말한다. 이곳에는 추사의 옛집을 비롯하여 화순옹주와 남편인 김한신의 합장무덤이 있고, 그 옆으로 정조(재위 1776∼1800)가 내린 열녀정문, 백송(천연기념물 제106호), ○○○의 무덤이 있다. ○○○은 북학파인 박제가의 제자로서 중국 청나라 고증학의 영향을 받아 실사구시에 입각한 학문을 연구했다. 24세 때에는 아버지를 따라 중국 청나라에 가서 고증학과 금석학·서체 등을 배웠으며, 순조 16년(1816)에 북한산 진흥왕 순수비를 고증하여 밝혀 내었다.","a":"김정희선생유적","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651961.jpg"},{"q":"○○○는 고려 태조 13년(930) 고려 건국을 기념하고자 창건한 사찰로, 이후 폐허가 되어 절터만 남아있던 것을, 훗날 김광영 스님이 새로 건물들을 지어 ‘도광사’라 하였다가 다시 ‘○○○’로 고쳐 부르게 되었다. 절마당에 자리하고 있는 이 탑은 옛 터에 남아 있었는데, 절을 새로 지을 때 이곳으로 자리를 옮긴 것으로, 옮길 당시 아래 부분이 일부 없어져 완전한 제 모습을 갖추고 있지는 않다. 즉, 높직한 바닥돌 위로 기단(基壇)이 없어진 채, 5층의 탑신(塔身)만이 차례로 쌓여 있다.","a":"개태사오층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661321.jpg"},{"q":"순창 적성면의 선돌마을을 지나 도왕마을 쪽으로 1㎞ 정도 올라간 곳에 위치하고 있다. 약 2.5m 정도되는 바위에 새겨져 있는데 오른쪽 대좌부분이 약간 떨어져 나간 것을 제외하고 전체적으로 보존상태는 양호한 편이다. 평평한 바위면에 두광과 신광, 불신, 대좌 등을 얕은 부조로 조각하였는데 전체적으로 신체에 비하여 얼굴이 큰 편이며 항마촉지인을 결한 채 결가부좌하였다. 머리 부분은 마치 두터운 모자를 쓴 듯 투박하게 표현되었으며 민머리에 큼직한 상투 모양의 육계가 묘사되었다.","a":"석산리마애여래좌상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661884.jpg"},{"q":"<○○○○○>는 서울광장에서 남대문에 이르는 세종대로의 일부 구간에 소재하고 있으며, 유수방향은 남대문방향에서 서울광장 방향으로<서울광장 ○○○○○>의 간선으로 연결된다. 이 ○○○는 시점과 종점의 바깥 방향과 그 사이 중간이 현대식 하수관으로 교체되어 일제강점기에 축조된 적벽돌 ○○○는 남대문에 가까운 쪽의 일부와 서울광장에 가까운 일부분만 잔존하고 있다.","a":"태평로2가 지하배수로","c":"시도기념물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2565756.jpg"},{"q":"500여 년간 이 지역에 뿌리를 내리면서 살아온 밀양손씨오곡공파 후손들이 선조들을 기리기 위해 1847년(헌종 13)에 세운 재실이다. ○○○는 사우인 효충사와 재실인 ○○○, 사견당, 관리사 등으로 구성되어 있으며 대문채와 사당의 내삼문을 갖추고 있다. 대문채와 ○○○ 효충사를 축선상에 배치하고 대문채와 ○○○ 사이의 좌우로 관리사와 사견당을 배치하였는데 관리사와 사견당 부분이 돌출하여 대지의 모양은 T자형이다.","a":"진주 영모재","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665924.jpg"},{"q":"○○○○은 간소한 건물이지만, 청계마을의 민속인 동제의 제장으로서 늦어도 19세기 전반에는 창건된 사당이다. 유형 무형의 민속신앙인 동제가 지금까지 유지되고 있는 민속신앙의 구심점이라고 할 수 있다. 더구나 비록 변화를 겪긴 했지만, 인근에 전승되는 견훤관련 설화와 결합되어 후백제대왕의 신위를 모시고 제사를 지내는 것은 매우 드문 현상이다. 작은 건물로 매우 간결한 구조로 구성되어 있어서 건축 구성상의 특이점을 찾기는 쉽지 않다.","a":"상주 견훤사당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658939.jpg"},{"q":"○○○는 백제 무왕 41년(640)에 자장율사가 세웠다고 전한다. 절 경내에는 ○○○을 비롯하여 대웅전, 영산전, 대광보전, 홍성루 등 많은 건물이 남아 있다. ○○○은 지장보살을 중심으로 좌우에 명부시왕상을 모시고 있어 지장전·시왕전이라고도 한다. 지장보살은 모든 인간을 교화시키는 역할을 맡았으며, 시왕은 염라대왕을 비롯한 10명의 지옥 심판관이다.","a":"마곡사명부전","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660976.jpg"},{"q":"○○○○○, 천파공 오상(1614~1672), 충정공 오두인(1624∼1689) 등 해주 오씨의 이름난 학자들을 배출한 유서 깊은 곳이다. <안성 ○○○○○ 고택>이 위치하는 덕봉마을은 사액서원인 덕봉서원과 ○○○ 고택, 종친의 무덤이 모여 있어 해주 오씨의 역사를 보여준다. ○○○의 손자인 오핵이 남긴 기록에 따르면 고택은 덕봉리 입향조 오현경에 의해 1510년에 처음 지었으며, 1650년에 현재 위치로 옮겼다고 한다. 사랑채에 걸린 ‘퇴전당(退全堂)’이라는 현판은 ○○○의 호를 1662년에 우암 송시열의 글씨로 새긴 것이라고 한다.","a":"안성정무공오정방고택","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637714.jpg"},{"q":"○○○은 경상남도 ○○시 사등면 사등리 평지의 들판에 돌로 쌓은 성으로, 둘레 986m, 높이 6.1m이다. 『조선왕조실록』에 의하면 고려 원종 12년(1271) 왜적의 침입으로 ○○도민이 진주·거창 방면으로 피난했을 때, 수월리에서 나무 울타리를 치고 생활하다가, 세종 4년(1422)에 사등리로 관아를 옮겨 성을 쌓았다고 한다. 그후 성이 좁고 물이 부족하여 고현성으로 관아를 이전하기 전까지 ○○읍성으로 사용되었다.","a":"거제 사등성","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654747.jpg"},{"q":"경상남도 함양군과 전라남도 남원시의 경계지점인 팔령치에 있는 성산의 9부능선을 따라 쌓은 산성이다. 『신증동국여지승람』에 기록된 내용으로 보아 신라시대에 쌓은 성으로 추정한다. 현재 성벽은 거의 무너져 있으나 서북쪽 성벽은 비교적 잘 남아 있다. 직사각형으로 다듬은 자연석과 깬돌을 이용하여 쌓았는데, 성 둘레는 약 500m, 양호한 곳의 높이는 약 3m 정도이다. 서쪽 문터는 성 밖으로 작은 성처럼 쌓아 올려 후대에 고쳐 쌓았음을 나타내고 있다.","a":"함양팔령산성","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656101.jpg"},{"q":"조선시대 경남 ○○○에 보관되어 있던 칠원 제씨의 ○○원부 가운데 일부분이다. 크기는 가로1.0m, 세로 70㎝이며, 한지 두루마리로 되어 있다. 전면 일부가 약간 훼손되었을 뿐 나머지는 거의 완전하게 남아 있다. 이 ○○원부는 당시 제씨 문중의 가계(家系)와 문서 양식의 형태를 파악하는데 좋은 자료이다.","a":"창원 진해현 호적","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641706.jpg"},{"q":"조선 후기의 문신인 포저(浦渚) 조익(1579∼1655) 선생의 묘이다. 선조 35년(1602) 문과에 급제한 후 여러 벼슬을 지냈으며 광해군 3년(1611)에는 이언적·이황 등을 문묘에 배향할 것을 주장하다가 고산도찰방으로 좌천되었고, 이어 웅천 현감이 되었다. 1613년 인목대비가 폐비가 되자 벼슬을 그만두고 충청도 신창 도고산 아래 초가를 짓고 학문연구에 몰두하였다. 그로 인하여 예산과 인연이 맺어진 것으로 묘소가 예산 신양면에 있다. 1623년 인조가 즉위하자 맨 먼저 기용되어 이조좌랑이 되었고, 김육과 함께 대동법을 확대·시행하는데 기여하였다.","a":"조익선생묘","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661343.jpg"},{"q":"○○○는 1866년(고종 3)의 병인양요와 1871년(고종 8)의 신미양요를 승리로 이끈 흥선대원군이 온 백성에게 서양세력에 대한 경계심을 일깨우고자 1871년 4월부터 서울과 전국의 교통요지에 세운 비석이다. ○○○○○도 이때에 세운 것이다. ○○○○○는 원래 충청북도 ○○시 상당구 석교동의 어느 집 앞 길가의 하수구 뚜껑으로 있던 것을 1976년 2월 29일에 발견되어 현재 위치에 옮겨 놓은 것이다. 2단의 받침돌을 쌓고 그 위에 비신을 세웠는데, 비신은 윗부분이 떨어져 나갔다.","a":"청주 척화비","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649462.jpg"},{"q":"고려 말기의 학자 우탁(禹倬, 1263~1342)의 학문과 덕행을 추모하기 위해 1570년(선조 3) 퇴계 이황(退溪 李滉)선생의 발의로 인근의 사족과 수령들의 협조를 받아 예안을 포함한 안동지역에서 최로로 건립된 서원이다. 1684년(숙종10)에 사액을 받은 후 대원군의 서원철폐 때 훼철되었다가, 1969년 현 위치에 이건 복원되었고, 1991년에는 이곳으로 옮겨온 안동대학교에 기부되었다. 안동대학교 도서관 뒤편에 야산을 등지고 남향하고 있으며 제향 및 강학공간과 고직사가 각기 별도의 곽을 이루며 병렬로 배치되어 있다.","a":"역동서원","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017042810154000.JPG"},{"q":"서쪽은 산으로 둘러져 있고 앞쪽은 동을 향하는 양지바른 밭 가운데 있는 무덤이다. 지상의 봉분은 유실되어 없어졌으나 내부구조는 지하에 잘 보존되어 있다. 남북으로 긴 직사각형에 가까운 널방(현실)의 동쪽벽에 돌방(석실)으로 들어오는 널길(연도)이 달린 ㄱ자형 평면의 돌방무덤(석실묘)이다. 이 무덤에서는 부장유물을 확인할 수 없어 축조연대를 정확히 밝힐 수 없으나, 구조양식으로 보아 삼국시대 후기에 속하는 신라 무덤으로 추정된다.","a":"영동 부용리 고분","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649626.jpg"},{"q":"월간 이전 선생과 창석 이준 선생 형제의 우애를 묘사한 그림으로, 가로 21.5㎝, 세로 29㎝이다. 임진왜란 다음해인 선조 26년(1593) 봄, 병으로 거동이 힘들던 동생 창석 선생이 형인 이전 선생에게 피신하여 가문을 보존해 달라고 간청하였다. 형은 동생의 부탁 대신 위험을 무릅쓰고 끝까지 동생을 업고 백화산 정상으로 피해 겨우 생명을 유지할 수 있었다. 이 사실을 후에 창석 선생이 명나라에 가서 중국인에게 이야기를 하니 그들이 감동하여 화공을 시켜 그림을 그리게 하였다.","a":"월간창석형제급난도","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640724.jpg"},{"q":"조선 선조 때 문신인 허엽(1517∼1580)이 살던 집으로 지은 시기는 정확하게 알 수 없다. 이곳은 허엽의 딸이며 조선시대의 대표적인 시인이었던 허난설헌(1563∼1589)이 태어난 곳으로 전한다. 행랑채의 솟을대문을 지나 사랑마당을 거치면 ㅁ자형의 본채가 있다. 본채는 사랑채와 안채로 구분하고 그 사이에는 광을 배치하였다. 안채는 앞면 5칸·옆면 2칸 규모의 건물로 부엌과 방, 마루로 되어 있는데 건물 앞·뒤로도 칸을 구분한 겹집 형태이다. 사랑채와 안채 사이에는 솟을대문과 협문을 두고 공간을 구획하여 독립성을 확보하였다.","a":"강릉 초당동 고택","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018122714184800.jpg"},{"q":"○○○은 마을입구나 고개마루에 원추형으로 쌓아놓은 돌무더기로, 마을을 지키는 수호신적인 기능을 한다. 이 ○○○은 높이 4.6m에, 아랫둘레가 24.3m이다. 수많은 돌로 층층이 쌓아올린 적석총 형태인데, 500년 전에 깃대봉의 용마(龍馬)가 아이와 함께 말 무덤으로 만들었던 것이라는 이야기가 전해 내려온다. 매년 정월 대보름날이면 마을에서 공동으로 제사를 지낸다고 한다.","a":"거창거기리성황단","c":"시도민속문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659069.jpg"},{"q":"○○○은 ○○○에 속한 암자로 조선 숙종 20년(1694)에 여적당 경수대사가 창건한 후 광무 9년(1901) 당시 주지였던 남응익 대사가 중창하였다. 1950년 6.25로 소실된 뒤 1964년 행담이 중건한 암자이다. 주변에서 출토되는 유물이나 경내에 남아있는 청석탑으로 보아 고려시대에도 사찰이 있었음을 짐작할 수 있다. ○○○○○은 대석을 포함한 현재 높이 2m로서 지면에 높직한 화강암 석재 2단을 놓아 지대석으로 삼고 그 위에 화강암의 초층 옥신석을 얹었다. 옥신 좌우에는 우주를 목각하였으며, 옥개는 점판암으로 조성한 8매의 방형 지붕동 만을 첩첩이 쌓았다.","a":"보은 법주사 여적암 다층청석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638930.jpg"},{"q":"월성산 서북쪽 산기슭에 자리잡고 있는 절터로, ○○○는 『삼국유사』에 기록된 미륵선화의 내용으로 보아 백제 위덕왕(554∼598)시대에 창건된 사찰로 여겨진다. 절터는 현재 밭으로 변하였고, 탑의 석재 일부가 남아있다. 1967년 공주박물관에서 이곳을 조사할 때 작은 탑, 청동으로 만들어진 풍경, 돌부처의 머리들이 발견되었다. 공주 ○○○터는 백제 사찰로 기록이 남아 있는 중요한 유적지이다.","a":"공주수원사지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652703.jpg"},{"q":"청풍 ○○○에 있던 옛 집으로, 지금은 ㄱ자 모양의 안채만 남아있지만 일반적인 예로 보아 안마당 앞에 사랑채가 있었을 것으로 보인다. 건넌방쪽 지붕의 옆면이 여덟 팔(八)자 모양인 팔작지붕이고, 부엌쪽은 사람 인(人)자 모양인 간결한 맞배지붕으로 되어 있어 오랜된 양식을 보여준다. 중부지방의 보편적인 민가유형을 따르고 있으며, 안방 뒤에 수납공간인 웃방을 둔 점과 대청 한 구석에 상제례를 위한 상청을 둔 점이 특징이다.","a":"제천 후산리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638515.jpg"},{"q":"이 작품은 몸을 약간 왼쪽으로 튼 채 손으로 자주색 함을 받들고 선 大院君 李昰應(1820-1898)의 전신상이다. 의복 등에서 이국적인 풍모가 엿보이기도 하지만 화면 우측에 ‘大院君之肖像’이라는 묵서가 적혀 있어 ○○○의 초상임을 밝히고 있다. 이 ○○○는 서예가 오세창의 제자인 원충희(元忠喜)가 소장하던 것을 동아대박물관에서 인수한 것이다. 현재 알려져 있는 ○○○의 ○○○는 동아대학교 소장본을 포함하여, 국립중앙박물관 소장의 작자미상 금관조복본, 서울역사박물관의 이한철과 이창옥의 합작본(1880년), 서울대학교 소장의 작자미상 반신상 등 총 4점이다.","a":"대원군 초상화","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636721.jpg"},{"q":"경상남도 ○○시 ○○○ 신만사 옛 절터에 있는 ○○○○○인데, 머리를 새로 만든 것 외에 불신은 비교적 잘 남아있다. 넓은 어깨, 당당한 가슴, 잘록한 허리 등에서 통일신라 불상의 특징이 잘 나타나 있으며, 무릎 폭이 넓어 안정감을 준다. 옷은 왼쪽 어깨만 감싸고 있으며, 오른손은 무릎 아래로 향해 내리고 왼손은 가슴에 대고 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)에는 화사한 덩굴무늬와 불꽃무늬가 새겨져 있다. 통일신라 석불양식을 충실히 따르고 있는 고려 초기의 작품이다.","a":"진주 평거동 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641491.jpg"},{"q":"불암산(해발 509m) 남쪽 능선의 해발 420m 봉우리에 있다. ○○○○ 서쪽으로 3번 국도와 중랑천 수계, 동쪽으로 왕숙천 수계를 통제할 수 있는 군사적 요충지에 있다. ○○○○은 봉우리 주변의 자연지형을 따라 쌓은 석축산성이다. 평면 형태는 장방형에 가까운 다각형이며 둘레는 220m다. 전략적인 요충지에 쌓은 보루성은 요즈음의 초소와 같은 감시기능을 했을 것으로 보인다. ○○○○ 성벽은 화강암을 장방형으로 가공하여 정교하게 쌓았다. 원래 성벽의 높이는 5m 이상이었을 것으로 보인다.","a":"불암산성","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052014554400.jpg"},{"q":"이 불화는 묵서화기(墨書畵記)에 의해 1905년 범어사 청련암에서 금어(金魚) 대인에 의해 제작되어 성주사에 봉안되었다가 진해 포교당이 신축되면서 ○○○ 대웅전에 봉안되었다. 화면의 중앙에 아미타여래가 결가부좌하였고, 좌우로 유희좌(遊戱坐)를 취한 관음보살과 대세지보살이 앉아 있으며, 아미타여래의 두광 좌우로 아난(阿難)과 가섭(迦葉), 그리고 2위의 나한상(羅漢像)이 서 있다. 그리고 화면의 상단 좌우측에 6위의 보살이 3위씩 구름을 타고 내영(來迎)하고 있다.","a":"창원 정암사 아미타불회도 및 초본","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642635.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 7년(1407)에 만경동헌 서편에 있는 송전리에 처음 지었다. 광해군(재위 1608∼1623) 때 불타 없어져 인조 15년(1637)에 지금의 동문내리에 다시 지어 오늘에 이르고 있다. ○○○은 앞면 3칸·옆면 3칸의 규모이며, 지붕은 옆에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. ○○○ 안에는 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 있다.","a":"만경향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661743.jpg"},{"q":"○○○의 한분인 경은 이맹전(1392∼1480)을 추모하여 세운 건물로, 조선 정조 10년(1786)에 임금의 명으로 지어졌다. 청렴결백하다는 평판을 받았던 이맹전은 단종 1년(1453) 수양대군이 단종을 보좌하는 황보 인·김종서 등을 몰아내고 정권을 빼앗아 나라가 소란해지자, 다음 해에 벼슬을 버리고 고향으로 돌아갔다. 귀머거리·장님이라 핑계하며 친한 친구마저도 만나지 않던 이맹전은 30여 년을 문밖에 나가지 않고 지내다가 나이 90여 세에 세상을 떠났다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"생육신이경은선생부조묘","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640337.jpg"},{"q":"○○○에 보존되어 있는 그림으로, ○○○이라 함은 사람이 죽어서 3일 만에 만나서 심판을 받게 된다는 지옥의 왕과 그의 권속들을 그림으로 표현한 것을 말한다. 비단 바탕에 채색으로 그려진 이 ○○○은, 5폭 병풍을 배경으로 의자에 앉은 현왕을 중심으로 좌우측에 동자를 비롯한 권속들이 각각 6명씩 배치되어 있다. 화면의 아래쪽 부분에 있는 기록에 의하면 이 ○○○은 건륭 40년, 즉 조선 영조 51년(1775)에 조성되어 ○○○ 대법당에 안치된 것임을 알 수 있다. ○○○ 건륭 40년 ○○○은 조선시대 불교회화사 연구에 중요한 학술적 자료이다.","a":"양산 통도사 건륭40년명 현왕탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642361.jpg"},{"q":"○○○○○는 지름 112㎝, 높이 72㎝로 고려 말∼조선 초에 제작된 것으로 추정된다. 청동으로 제작된 이 수조는 바리(鉢)형태를 띠고 있고, 구연부에는 덧띠를 두르고 있으며 약간의 균열과 파손 흔적이 보이지만 모두 수리하여 양호한 상태이다. 일반적으로 사찰의 수조(水槽)는 삼국시대부터 큰 돌 내부를 파서 물을 담아 쓰기 시작하였으며 우물가에 두고 그릇 등을 씻을 때 사용하였다.","a":"강화 전등사 청동수조","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637110.jpg"},{"q":"귀신사와 가까운 곳에 서 있는 탑으로, 본래의 모습을 많이 잃어 다시 복원한 것이다. 형태는 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 아래층 기단에는 안상(眼象) 무늬를, 위층 기단에는 기둥 모양을 새겨 놓았다. 탑신의 몸돌에도 기둥 모양을 새겼으며, 네 귀퉁이가 살짝 들린 지붕돌은 밑면에 3단의 받침을 두었다. 탑신의 몸돌과 지붕돌이 부분적으로 파괴 되었다. 지붕돌이 백제의 석탑 양식을 보이고 있어, 백제 지역에 세운 고려시대 탑으로 추정된다.","a":"청도리삼층석탑","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661808.jpg"},{"q":"이 영정은 ○○○선사의 좌안8분면 바닥가부좌상으로, 왼손엔 주장자를 곧게 들고 있으며 오른손은 염주를 쥐고 앉아 있다. 인물의 뒤편은 상단벽면과 하단돗자리가 그려진 이단구도를 배경으로 녹색 법피가 드리워진 의자를 묘사하고 있다. 화면 향좌측엔 주지묵서의 ‘선교양종○○○대선사지진(禪敎兩宗普雲堂大禪師之眞)’의 화제가 있고 향 우측으로는 영찬의 기록이 확실하며, 화면 크기는 가로 79.5cm, 세로 122.5cm이다.","a":"보운당 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643036.JPG"},{"q":"이명발이 은거하던 모고산 입구에 후손인 이학이 세운 것으로, 강학과 풍류를 즐기던 곳이다. 이명발은 문종 때 승지였던 이승길의 아들로, 성균관에서 공부하던 중 단종폐위에 충격을 받고 이곳으로 내려와 지냈다. 건물은 조선 중종 15년(1520)에 지었는데 처음에는 절벽 위에 있던 것을 비바람으로 퇴락하여 현종 10년(1670) 자손인 명선이 지금 있는 자리로 옮겼다. 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다.","a":"모고재","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662856.jpg"},{"q":"충청남도 부여군 은산면에 있는 해발 60m의 낮은 산봉우리를 둘러 싼 토성으로, 안쪽의 내성과 바깥쪽의 외성으로 구분된다. 토성은 흙으로 성벽을 쌓되 산비탈의 자연적인 경사면은 더욱 가파르게 깎아 성벽으로 이용하는 것을 말한다. 성 둘레는 내성이 약 180m이고 외성이 약 250m이다. 외성은 대부분이 개간되어 평지화 되었으며, 내성은 흙으로 쌓은 형태가 부분적으로 남아있고, 북쪽에는 너비 5∼6m의 물길인 도랑이 있다. 산성의 서남쪽 기슭 암벽 아래에는 별신당이 있는데, 백제부흥운동군과 관련된 은산별신제의 전설이 전해오고 있다.","a":"은산당산성","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653092.jpg"},{"q":"○○○은 마을의 수호신을 모셔 놓은 곳으로, 주로 돌무더기와 나무로 되어있으며, ‘서낭당’이라고도 한다. ○○○ 마을은 나즈막한 야산 솔숲에 3개의 커다란 돌을 쌓은 삼첩석, 2개의 돌로 구성된 이첩석, 자연석 위에 모자형의 돌을 얹은 모관석, 작은 돌로 높이 쌓은 돌무더기 등이 있어 마을의 안녕과 무병장수를 기원하는 공동체신이 있는 성스러운 곳으로 여겨지고 있다. 삼첩석과 이첩석은 청동기시대 유적으로 추정되는데, 후에 풍수지리적으로 마을의 허한 곳을 보완해 주는 기능이 추가되었다.","a":"안동서지리성황당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658812.jpg"},{"q":"○○○는 청동기시대에 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 제주시 삼양동에 있는 고인돌은 정확한 발굴조사가 이루어지지 않아 하부구조를 알수 없으나 형태상 바둑판식으로 보인다. 이 고인돌은 남북방향으로 자리하고 있는데, 덮개돌은 길이 2.19m, 너비 0.35∼0.5m이고 형태는 직사각형 모양이다.","a":"삼양지석묘1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657661.jpg"},{"q":"유일하게 서울 4대문 안에 보존되어 있는 우물로, 조선 역대 왕들이 ○○ 왕래시 이 우물물을 마셨다고 하여 ‘○○’이라 부른다. 우물의 형태는 둥글고, 깊이는 약 8m에 지름은 1.5m로, 우물 속은 온통 돌벽으로 쌓여 있다. 우물 윗부분은 원래 사각의 긴 돌을 井자 모양으로 짠 후, 그 위를 그 모양새에 따라 돌로 쌓아 올린 형태였던 것을, 일제 시대 때 콘크리트를 발라 그 모양이 바뀌었고, 1985년 보수하면서 다시 원래의 모습을 되찾았다. 석재를 쌓는 방법과 석재가 닳은 상태로 보아 조선 전기에 만든 우물로 추정된다.","a":"종묘 어정","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636205.jpg"},{"q":"○○○는 승주 송광사, 합천 해인사와 더불어 우리나라 3대 사찰중 하나로 경내는 크게 상로전, 중로전, 하로전으로 나뉜다. ○○○은 하로전의 중심건물인 영산전 동쪽에 있는데 고려 공민왕 18년(1369)에 성곡대사가 지었다고 전한다. 앞면 3칸·옆면 3칸으로 지붕 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 되어 있다. 지붕을 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물이다. 내부에는 아미타불상을 모시고 있으며 벽은 모두 불화와 산수화로 그려져 있다.","a":"양산 통도사 극락전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641815.jpg"},{"q":"후학들을 교육하고 양성하기 위해 세운 서당이다. 월하 조운도(1718∼1796) 선생이 의견을 내고 한양 조씨·야성 정씨·함양 오씨가 주축이 되어 조선 영조 49년(1773)에 지었다고 한다. 앞면 4칸·옆면 2칸 규모를 가진 한 일자형 건물로 전망이 좋고 한적하여 공부하기 좋은 곳이다. 가운데 2칸은 마루를 만들어 대청으로 꾸몄고 양쪽은 방을 만들어 놓았는데 오른쪽은 ‘극복재(克復齋)’, 왼쪽에는 ‘존성재(存省齋)’라는 현판이 걸려 있다. 경치 좋은 곳에 자리잡고 있는 조선 후기 건축양식을 잘 간직한 건물이다.","a":"월록서당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640620.jpg"},{"q":"○○는 조선시대의 지방 관아건물로 고을 수령이 임금의 위패를 모시고 예를 올리는 정당과 중앙에서 파견된 관리들이 머물렀던 좌·우헌으로 구성되어 있다. 지어진 시기는 알 수 없고 1924년 군수 이장희가 시장용 건물로 쓰기 위해 ○○읍 술정리로 옮겼다가 1988년 이곳 만옥정에 옮기고 보수했다. 앞면 3칸·옆면 3칸의 1층 건물로, 지붕 옆모습이 사람인(人)자 모양인 맞배지붕으로 되어있다. 바닥은 따로 마련하지 않고 기단 위에 곧바로 세웠으며 기둥 사이에는 벽을 쌓지 않아 주위의 경관을 볼 수 있게 했다.","a":"창녕 객사","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641994.jpg"},{"q":"분 류 유물 / 불교회화/ 탱화/ 불도 수량/면적 1폭 지정(등록)일 2005.12.27 * 명칭변경(○○○ 석가모니후불탱 →○○○○○), 변경사유 : 동일성격문화유산 명칭통일 소 재 지 부산 강서구 명지동 445 시 대 일제강점기 소유자(소유단체) ○○○ 관리자(관리단체) ○○○ 상 세 문 의 부산광역시 강서구 문화체육과 051-970-4065","a":"청량사 영산회상도","c":"문화유산자료","nc":"","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659382.jpg"},{"q":"조선 중종(재위 1506∼1544)때 문신이자 학자인 농암 이현보(1467∼1555)의 별당이다. 농암 선생이 이 집을 짓고 94세의 아버지가 늙어가는 것을 아쉬워하며 하루하루를 사랑한다는 뜻에서 ‘○○○’이라 하였다고 한다. ○○○은 중종 7년(1512)에 처음 세워졌고, 명종 3년(1548)에 고쳐지어졌다. 지금의 건물은 조선 후기에 다시 지어진 것이다. 원래는 낙동강 안의 분천동에 있었으나, 안동댐 건설로 1975년에 이곳으로 옮겨졌다.","a":"애일당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640290.jpg"},{"q":"조선 전기의 문신인 신선경의 묘를 비롯한 거창 신씨들의 ○○이다. 신선경은 세조 1년(1456) 사헌부 장령을 거쳐 동지중추부사를 지냈다. 거창 신씨는 원래 중국 송나라 개봉부 출신인 신수(愼修)가 송나라 사신으로 고려의 수도 개경에 왔다가 고려에 귀화하여 고려인이 됨으로써 거창 신씨의 시조가 되었다. 거창 신씨 ○○ 내에 문화 류씨 ○○이 자리 잡고 있는데, 이는 공조참의 ○○○의 묘소이다. ○○○는 신선경의 사위로 이 묘는 부부합장묘이다.","a":"신선경과 류인호 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"송파구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636253.jpg"},{"q":"조선 ○○의 외숙인 염보길이 살던 집이다. ○○ 4년(1853)에 지은 이 건물은 원래 안채와 사랑채를 좌우로 두고 H자형 배치를 취하고 있었으나, 행랑채 일부가 헐려 지금은 ㄷ자 모양의 몸채만 남아 있다. 사랑채와 안채가 一자형으로 연결되어 있고 안(안채)과 밖(사랑채)의 공간을 작은 담장으로 간단히 분리하였다. 규모는 작으나 예스럽고 우아한 아름다움이 묻어나는 건물이다.","a":"강화 철종 외가","c":"문화유산자료","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659543.jpg"},{"q":"○○○맥으로 오르는 길 양쪽에 서 있는 2기의 돌장승이다. 처음에는 북쪽으로 1.2㎞ 떨어진 미루둔지에 있었는데, 40여년 전 ○○○ 망경사로 옮겼다가 다시 1987년 태백문화원의 주관하에 지금의 자리에 복원한 것이다. 복원과정에서 처음에는 없었던 자연석을 장승의 받침돌로 깔고, 받침돌에 각각 천장(天將)과 지장(地將)이라 새겨 ‘천하대장군’과 ‘지하여장군’임을 표시하였다. 그러나 그 생김새가 일반 장승의 부리부리한 모습이라기보다는 온화하고 점잖은 모습이어서 문인석(文人石)이나 미륵상에 더 가까워 보인다.","a":"태백산석장승","c":"시도민속문화유산","nc":"","r":"강원특별자치도","s":"태백시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658182.jpg"},{"q":"조선 영조 때의 성리학자인 식산 이만부(1664∼1732)가 1700년 경에 지은 정사이다. 주자의 시구에서 인용하여 ‘천운재’라 하였고, 마루방은 ‘천운당’, 온돌방은 ‘양호료’라 이름하였다. 앞면 3칸·옆면 1칸 규모의 ㄱ자형 건물이며, 마루방·온돌방·부엌으로 구성되어 있다. 마루방쪽은 지붕 옆면이 사람 인(人)자 모양인 간결한 맞배지붕이고 온돌방쪽은 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕으로 다르게 처리하여 특이하다. 건물의 앞에는 ‘조감당’이라 부르는 네모반듯한 연못이 있다. 이만부가 지은『노곡기』에는 이곳의 전체 구성에 관하여 기록되어 있다.","a":"천운정사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658764.jpg"},{"q":"이름을 알 수 없는 옛 절터에 무너져 있던 것을, 1982년 6월 마을 주민들이 발견하여 산 아래로 옮겨 놓았다. 탑신(塔身)의 1·2층 몸돌이 없어지긴 하였으나,그 외에는 완전한 3층 석탑으로 추정되는 부재를 갖추고 있었고, 1991년 탑을 복원하여 다시 세우면서 2층 기단(基壇)에 3층 탑신(塔身)이라는 구조를 갖추게 되었다. 탑신의 몸돌에는 모서리마다 기둥 모양을 새겼다. 두툼한 지붕돌은 네 귀퉁이가 치켜 올라갔으며, 밑면에 4단의 받침을 두었다. 남아 있던 부재들의 양식으로 보아 고려시대의 것으로 추정된다.","a":"상주 무곡리 삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662650.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○시 ○○○의 해안가에 있는 2기의 고인돌은 작은 받침돌 위에 덮개돌이 올려진 모습이며, 덮개돌이 지상 위에 붙어 있어서 하부구조는 자세히 알 수 없다.","a":"통영 봉평동 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655487.jpg"},{"q":"현 소유자 권기항의 8대조가 18세기 말에 세운 집이다. 안채와 사랑채가 연접하여 ㅁ자 평면을 이루고 있고 오른쪽에 사당이 배치되어 있다. 이 지방 사대부집의 일반적인 형태를 따르고 있는 집으로 사랑채의 앞면과 옆면에는 낮은 난간을 두어 격식을 갖추고 있다.","a":"영덕번호댁","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663241.jpg"},{"q":"대전광역시 유성구 노은동의 택지개발지구내 공원조성 예정지역의 낮은 언덕에 분포하고 있는 청동기시대 및 원삼국시대의 유적이다. 이 유적은 지표면에 이미 집자리 유적이 노출되어 있는 경우도 있었으며, 발굴조사에 의하면 유적들의 밀집도가 그리 높지 않은 것으로 확인되었다. 청동기시대 집자리 유적은 언덕 방향을 따라 12기가 확인되었고, 언덕 북쪽 끝부분에서 송국리형 원형주거지 1기와 사각형주거지 1기가 조사되었다. 형태는 평면 사각형으로 평지 위에 직접 기둥을 세운 구조이며, 겹아가리토기(이중구연토기)와 구멍무늬토기(공열토기)가 출토되었다.","a":"노은동유적","c":"시도기념물","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645839.jpg"},{"q":"전북특별자치도 남원에 있는 용담사(龍潭寺) 부근의 ○○○에 모셔진 석불로 연꽃잎이 새겨진 대좌(臺座) 위에 앉아 있다. 얼굴은 심하게 훼손되어 잘 알아볼 수가 없지만 목에는 3줄의 주름이 뚜렷하게 표현되었다. 왼쪽 어깨에만 걸쳐 입은 옷은 배부분에서 곡선을 그리며 무릎까지 흘러내렸다. 오른손은 무릎 위에 올려 손끝이 땅을 향하고 왼손은 배부분에서 손끝이 하늘을 향하고 있는 모습이다. 배(舟)모양의 광배(光背) 안에는 굵은 선을 도드라지게 둘러서 각각 연꽃잎이 새겨진 머리광배와 몸광배를 구분하였다.","a":"심경암석불좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639435.jpg"},{"q":"호미산성의 반대쪽 능선 정상부를 따라 분포한 무덤들이다. 현재 외형상으로 봉분을 가진 대형무덤이 30여기 인데, 그 외 주변에 많은 소형무덤이 더 있을 것으로 추정된다. 구조는 구덩식(수혈식)과 굴식(횡혈식)이 함께 섞여 있으며, 하나의 봉분 안에 2개 이상의 돌덧널(석곽)을 포함하는 여러널식(다곽식)도 있는 것으로 보인다. 내부는 가야의 전형적인 무덤형태로 자른 돌을 사용하여 내벽을 정연하게 쌓아 올렸다. 주변에서 수습된 유물과 무덤의 구조를 살펴볼 때 이 무덤들은 5세기 후반에서 6세기 전반경에 만들어진 것으로 추정된다.","a":"의령 죽전리 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655429.jpg"},{"q":"전북특별자치도 장수군 산서면 마하리 팔공산 기슭에 있는 원흥사 법당 안에 모셔져 있는 높이 4m의 거대한 ○○○○이다. 원래 노천에 방치되어 있었는데, 1904년 이 마을에 살던 이처사 부부가 꿈을 꾼 뒤 불상을 만들어 모셨으며, 그 뒤 딸 청신과 손자 김귀수가 현재의 원흥사를 세웠다고 한다. 얼굴은 살찐 모습이며 눈과 입이 작은 편이나 코는 큰 편이다. 목은 매우 짧게 표현되었으며 3개의 주름인 삼도(三道)는 분명하지 않다. 신체는 어깨와 하부의 너비가 같아 둔한 느낌을 준다.","a":"원흥석불입상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661661.jpg"},{"q":"진양하씨 ○○○○에서 소장하고 있는 ○○○들로서 분재기 3건, 노비소송 관련 입안 1건, 호구 관련 ○○○ 9건, 토지매매문기 14건, 소지·등장·품목류 54건, 완문·절목·전령·소사·수기(수표)류 12건, 위장·만장·제문류 11건, 임명 관련 서류 및 계후입안 4건 등 모두 108점이다. 분재기는 1547년·1610년·1624년 등 모두 3건이 소장되어 있다. 16세기 이전의 분재기는 전국적으로 흔하지 않을 뿐만 아니라, 대를 이어 17세기 초까지의 분재기가 여러 건 같이 보존되어 있는 경우는 거의 없어 가치가 있다.","a":"진주 송정종택 고문서","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642372.jpg"},{"q":"주희와 신재 한호겸의 위패를 모신 서원이다. 한호겸은 성리학자로서 항상 주희의 영정을 모셔왔는데, 그가 죽은 뒤 조선 선조 21년(1588)에 제자들이 그의 덕행을 추모하기 위해 신안사라는 사당을 짓고 주희와 그의 위패를 함께 모셨다. 그 뒤 정유재란으로 불탄 것을 현종 10년(1669)에 다시 세웠고, 순조 19년(1819)에는 나라의 지원을 받는 사액서원이 되어 이름도 ○○○○로 바뀌었다. 고종 5년(1868)에 흥선대원군의 서원철폐령으로 철폐되었다가 1958년에 다시 세워 오늘에 이르고 있다.","a":"신안서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661638.jpg"},{"q":"문강공 은봉(隱峰) 안방준(安邦俊, 1573~1654)은 호남을 대표하는 유학자이다. 20세에 임진왜란을 당해 박광전과 함께 의병을 일으켰고, 정묘호란과 병자호란에도 격문을 띄워 근왕(勤王)의 의기(義旗)를 높이 세웠다.","a":"보성 은봉종택과 대계서원 고문서 일괄","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640228.jpg"},{"q":"○○○의 대웅전과 선원(禪院)에 각각 따로 모셔져 있지만, 원래는 삼세불(三世佛)로 함께 만든 불상이다. 삼세불이란 과거불 · 현재불 · 미래불을 뜻하기도 하고, 현재의 공간과 동방, 서방의 세 세계를 뜻하기도 한다. 조선 시대 절에서는 흔히 가운데 석가모니불을 중심으로 그 왼쪽에 약사불이, 그 오른쪽에 아미타불이 배치되는 형식이 일반적이었다. ○○○의 두 목조불상도 크기와 인상, 옷차림새와 옷주름이 서로 비슷해 삼세불로서 함께 만들어졌음을 알 수 있다.","a":"용인화운사목조여래(아미타,약사)좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637763.jpg"},{"q":"속칭 ‘우마니들’, ‘우마니 절터’라고 불리는 경상남도 하동군 옥종면 청룡 마을 앞 들판에서 발견된 불상이다. 1954년 공사 도중에 발견되었는데, 주민들이 뜻을 모아 지은 보호각에 보관되어 있다. 불상은 머리 부분의 훼손이 심하고 얼굴은 형태를 알아보기 어려울 정도이다. 다만 목에는 3줄의 삼도(三道)가 뚜렷하고, 옷주름은 소박하게 표현하였다. 훼손이 심해서 확실하지는 않지만 손모양은 아미타불이 취하는 모습에 가깝다. 전체적으로 화려한 기교없이 소박하게 표현한 것으로 보아 고려 후기에 만든 것으로 추정된다.","a":"하동청룡리석불좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664458.jpg"},{"q":"‘○○○’은 조선시대 중앙과 지방의 관서나 해당 관원의 성명·직명·지위와 부임 및 이임일자 등을 기록한 책을 뜻한다. 1598년(선조 31)에 이임한 군수 김태허에서 시작하여 1906년 부임한 군수 김덕한에 이르기까지 309년 동안 울산에 부임한 역대 수령과 재임 시의 좌수․별감 및 호장․기관의 인명을 기록하였다. 대부분 한문으로 기록되어 있으나 이두로 작성된 부분이 일부 있으며, 특히 19세기에 이르면 이두로 작성된 사례가 증가한다. 책의 크기는 가로 37㎝, 세로 50㎝로 각 면마다 계선을 둘렀다.","a":"울산부선생안","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637284.jpg"},{"q":"○○○○○의 사랑채인 야은재는 야은(野隱) 이용중(李容中, 1841∼1919)이 만년에 주거하던 곳이다. 전면 5칸·측면 2칸의 규모이고 안채와 나란히 배치된 ‘一’자형 ○○으로서 전면과 측면에 넓은 마루가 구성되었으며 내부공간은 방이 3개, 수장고가 1개로 전체적으로 마루를 포함하여 5개의 단위공간으로 분할되어 있으며 출입구의 문들은 여닫이문을 사용하고 있다. 기단은 외벌대로서 화강석을 사용하였으며 높이는 45㎝이고 기단 위에 놓인 주초는 막돌 덤벙주초이다. 사랑채의 많은 면적을 차지하고 있는 우물마루는 높이가 60㎝이고 벽체는 재사벽이다.","a":"장성 이진환 가옥 사랑채［야은재］","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020121610091900.jpg"},{"q":"이곳은 정침 1동, 사당 1동, 정자 1동 등 모두 3동의 건물이 ‘○○○○○’이라는 명칭으로 민속문화유산으로 지정되어 있다. ○○○○의 건물배치는 뒤편의 야산을 등지고 정침, 정자, 사당, 방앗간 등이 남향으로 배치되어 있다. 배치구성은 1993년 복원된 대문간채를 들어서면 넓은 마당을 사이에 두고 정침과 정자가 나란히 배치되어 있으며, 그 뒤에는 사당이 자리 잡고 있다. 이 지역의 상류주택 특성을 잘 보여준다. 안채(정침)은 정면 7칸 × 측면 6.5칸 규모의 □자형 건물로 홑처마 맞배기와집이며, 전면 양측으로 1칸씩 돌출되어 양날개집의 형상을 하고 있다.","a":"울진 평해황씨 해월종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658935.jpg"},{"q":"○○○은 한탄강변에 있는 정자이다. 세운 시기를 정확하게 알 수 없으나, 『신증동국여지승람』에 기록된 내용에 따르면 신라 진평왕(재위 579∼632)과 고려 충숙왕(재위 1294∼1339)이 여기에서 머물렀다고 한다. 그 외에도 고려 승려 무외(無畏)의 ○○○기와 김량경의 시 등이 있다. 전해 내려오는 이야기에 따르면 의적 임꺽정이 ○○○ 앞에 솟아 있는 고석바위의 큰 구멍 안에 숨어 지냈다고 하는데, 이 바위에는 성지, 도력이 새겨져 있고 구멍 안의 벽면에는 유명대, 본읍금만이라고 새겨 있다.","a":"고석정및순담","c":"시도기념물","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647679.jpg"},{"q":"조선시대의 대학자인 한훤당(寒喧堂) 김굉필(金宏弼, 1454~1504)과 일두(一蠹) 정여창(鄭汝昌, 1450~1504)이 서로 교류하며 시를 읊고 풍류를 즐기며 후학에게 학문을 가르쳤던 곳이다. 건물 이름인 ‘이노’(二老)는 한훤당과 일두를 가리켜 부르는 것이다. ○○○을 ‘제일강정’(第一江亭) 또는 ‘제일강산’(第一江山)이라고도 하는데, 이름에 걸맞게 풍광이 아름다운 곳에 자리하고 있다. 건물이 처음 지어진 시기는 일두가 함양의 안음현감으로 부임한 1495년부터 무오사화 때 화를 입어 두 사람이 유배된 1498년 사이일 것으로 짐작된다.","a":"이노정","c":"문화유산자료","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659491.jpg"},{"q":"○○○○○ 전면에 위치하고 있는 이 ○○은 학교 교육의 초창기인 1926년도에 건축된 학교 ○○ 건물이다. ○○의 건물형태는 정면 6칸, 측면 2칸 규모로, 지붕은 팔작지붕이다. 건축당시의 역사, 건축연도, 건립동기 등이 기록된 실기(實記)에 의하면 ○○ 건립은 학부형들의 피땀어린 정성으로 이룩한 것이라는 내용과 1925년 건축공사를 착수하여 1926년 10월 17일 낙성하였다고 기록하고 있다. ○○○○ 초기의 ○○으로 건축당시의 구조 및 형태가 현재까지 변형됨이 없이 보존되어 있고, 실기(實記)가 남아 있어 중요한 자료로 평가된다.","a":"부강초등학교 강당","c":"시도유형문화유산","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643367.jpg"},{"q":"\"○○○는 임진왜란 때 호남의병을 이끌고 금산(錦山)싸움에서 순절한 고경명(高敬命,1533~1592) · 종후(從厚,1554~1593) · 인후(因厚,1561~1592) 3부자와 유팽로(柳彭老,1554~1592) · 안영(安瑛,1564~1592)을 모신 곳이다. 대원군의 서원철폐 때에도 장성의 필암서원과 함께 헐리지 않았던 전남지역 2대 서원 중 하나이다. 이 건물은 왜란 후 호남유생들이 충의로운 인물을 기리고자 세웠는데 1603년 고경명의 후손과 제자인 박지효(朴之孝)등이 임금에게 청하여 ‘포충(褒忠)’이라는 이름을 받았다.","a":"포충사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645742.jpg"},{"q":"마을 공동 규약인 중국의 ‘향약’과 우리나라에 전통 계모임이 결합된 형태인 마을 향약계에서 만든 재실이다. 『향약절목』에 따르면 당시 각 면에는 재실을 마련하여 향약의 집회와 향음주례를 행하였다고 하는데 이 재실 또한 그러한 용도의 장소였다. 철종 1년(1850)에 세운 이 건물은 一자형 평면을 갖춘 건물로 가운데에 대청마루를 두고 양 옆으로 방을 배치하였다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 세운 이후 조선 후기까지 이용하다가 이 ○○○를 제외한 나머지는 없어졌으나 이곳에서만은 선인들의 취지를 계승하고 지금까지 보존·관리해오고 있다.","a":"순천 향약재","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662096.jpg"},{"q":"세조(재위 1455∼1468)가 단종을 폐위할 때 뜻을 굽히지 않고 절의를 지켜 죽어간 사육신 이하 여러 충신들의 혼을 모셨던 곳이다. 세조가 왕위를 차지하는 과정에서 황보인, 김종서는 수양대군에게 살해당하였고, 왕위를 찬탈한 다음해인 세조 2년(1456)에는 성삼문을 비롯한 사육신이 단종의 복위를 꾀하다가 모두 참형 당했다. 같은 해 생육신인 매월당 김시습이 이곳 ○○○에 와서 제단을 마련하고 이들을 위해 초혼제를 지내어 영혼들을 위로하였다고 전해진다.","a":"계룡산초혼각지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651912.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 묘 앞에 세워두는 것으로 이 비는 조선 중기의 문신인 임당 정유길(1515∼1588)의 공적을 기리고 있다. 정유길은 중종 33년(1538) 문과에 장원급제하여 정언에 임명된 후 여러 관직을 두로 거쳐 선조 18년(1585)에는 좌의정에 이르렀다. 충효와 근신을 근본으로 삼고 넓은 도량을 가지고 있어 포섭력이 강하였으며 큰 일에는 대의를 가지고 과감하게 처리하였다. 또한 시와 글짓기에도 뛰어났고 서예에도 능하여 임당체(林塘體)라는 평을 받았다.","a":"동래 정씨 임당공파 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636209.jpg"},{"q":"조선시대 ○○○의 지방행정관청이다. 북쪽에서부터 ○○○○○ 4동의 건물이 남쪽에서 약간 동쪽을 향해 기울어진 방향으로 위치하고 있다. 가장 앞쪽에 위치한 ○○○은 관청의 정문으로, 앞면 3칸·옆면 2칸 규모의 2층 건물이다. 아래층 3칸에는 3문을 달아 동헌으로 통하도록 하였고 위층에는 마루를 설치하였다. 건물의 가운데 칸에 ‘호서계수아문(湖西界首衙門)’이라는 현판이 있다. ○○○을 지나면 동헌의 앞에 자리한 ○○○이 있다. 앞면 9칸·옆면 1칸 규모의 건물로, 가운데 칸에 출입문인 솟을대문이 있고 양 옆에 각각 3칸·5칸의 창고로 쓰이던 고방이 달려있다.","a":"직산현관아<내동헌.외동헌.내삼문.외삼문>","c":"시도유형문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639068.jpg"},{"q":"문익점(1329∼1398) 선생이 태어난 곳으로 나라에서 선생의 공적을 기리기 위해 지은 사당이다. 선생은 고려 때의 문신이며 우리나라에 목화를 처음 들여온 것으로 유명하다. 서원은 조선 세조 7년(1461)에 세웠으며, 조선 정조 11년(1787)에 ‘○○○○’이라는 현판을 받았다. 고종 8년(1871) 흥선대원군의 서원철폐령으로 철거되었다가 1975년에 사당인 삼우사를 짓고 서원으로 복원되었다. 서원 내의 ○○○○는 조선 명종 6년(1551)에 지은 것이며, 현재 건물은 조선 순조 4년(1804)에 다시 지어진 것이다.","a":"산청 도천서원 신안사재","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642016.jpg"},{"q":"집회 및 집무를 처리하던 동헌이라고 전해지는 이 건물은 명월정이라고도 한다. 조선 숙종 7년(1681)에 처음 지어졌으며, 영조 2년(1726)에 다시 옮겨 짓고 이름을 ○○○으로 바꾸었다. 광무 4년(1900)에 전체적으로 보수하였는데, 충주댐 건설로 인하여 1983년 지금의 위치로 옮겨 복원하였다. 앞면 6칸·옆면 3칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 건물의 오른쪽은 대청이고 왼쪽은 온돌방이다. 죄인을 가두어두던 부속건물이 있었으나 조선 말기에 없어졌다.","a":"제천 청풍 금병헌","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2021012016120700.jpg"},{"q":"금호강 벼랑 위에 자리잡은 조양각은 일명 명원루 또는 서세루라고 불린다. 고려 공민왕 12년(1363)에 당시 부사였던 이용이 세운 것이다. 그 뒤 임진왜란(1592) 때 불에 타 버리고, 지금의 건물은 인조 16년(1638)에 다시 세운 것이다. 앞면 5칸·옆면 3칸의 규모이며 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕이다. 누각 안에는 포은 정몽주의 「청계석벽」 등 시 70여 점이 걸려있다. 조양각은 영천지방 문화의 상징으로 영남 7대 누각 중 하나로 손꼽힌다.","a":"영천조양각","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640556.jpg"},{"q":"○○○은 1630년대에 장흥효(1564∼1633) 선생이 지은 정자로 300여 문인이 학문을 익히던 곳이다. 선생은 일찍부터 관직에 뜻을 두지 않고 고향에 은거하면서 학문 연구에 몰두하여 영남학파 발전과 후배양성에 힘썼다. 현재 정자의 모습은 헌종 4년(1838)에 이 지역의 유림들이 고쳐 지은 것이다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. ○○○은 대각선으로 대칭된 공간 배치를 하여 특이한 평면구조를 이루며, 지형적인 환경 요인 뿐 아니라 기후 요인까지 적절히 받아들인 건축물로 건축사적 의의가 크다.","a":"광풍정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663139.jpg"},{"q":"구곡리 굴티마을 앞을 흐르는 세금천에 놓여 있는 다리로, 독특한 모습이 눈에 띈다. 다리는 작은 돌을 물고기 비늘처럼 쌓아 올린 후, 지네모양을 본떠 길게 늘여 만들어 졌으며, 총 28칸의 마디모양으로 이루어져 있다. 돌을 쌓아올릴 때에는 석회 등을 바르지 않고 그대로 쌓았다 하는데, 폭이 1m도 채 되지 않는 다리임에도 장마 등에 의해 떠내려가지 않고 그대로 버티고 있어, 그 튼튼함을 여실히 보여준다. 옛날에는 어른도 서서 다리 밑을 통과할 만큼 높았다고 하나 지금은 하천바닥이 많이 높아져 원래의 모습을 확인하기 어렵다.","a":"진천 농다리","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638436.jpg"},{"q":"청림사의 절터로 전하는 곳에 이 탑이 서 있다. 석탑은 전체의 무게를 받치는 기단(基壇)을 2층으로 쌓고, 3층의 탑신(塔身)을 올렸는데, 원래는 5층이었을 것으로 추정된다. 규모는 비교적 작은 크기이며, 각 부분이 일부 깨져 있다. 기단은 아래층과 윗층의 맨윗돌이 탑신에 비해 지나치게 커보여 비례가 잘 맞지 않는다. 탑신의 각 지붕돌은 얇고 작으며 밑면에 3단의 받침을 두었다. 낙수면은 느린 경사를 이루다 네 귀퉁이에서 살짝 솟아올라 곡선미를 보여준다.","a":"공주가척리석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639167.jpg"},{"q":"우암 송시열(1607∼1689) 이 학문을 연구하며 지내던 집이다. 후에 우암의 제사를 모시는 한천서원을 세웠었는데, 고종 5년(1868)에 서원을 철거하였고 후에 후학들이 다시 지은 것이다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 중앙에 대청마루가 있고 양쪽 끝에 온돌방을 두었다. 주변에 담장을 두르고 앞면에 문을 두었는데 앞면 양측에 은행나무가 있다.","a":"영동 한천정사","c":"문화유산자료","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660767.jpg"},{"q":"○○○ 가옥은 정성을 들여 잘 지어진 사랑채로 외부재료나 형식으로 보아 근대적 성격을 띤 주거건축이다. 현재 안채는 없어지고 외부공간인 정원과 더불어 사랑채와 문간채만 남아 있다. 상량문에 의한 사랑채의 건립 연대는 1917년으로 확인되었다. 외부재료를 근대적 재료인 유리창으로 마감한 것이 흠이지만, 전통 한옥이 근대화 되어 가는 과정에서 나타나는 과도기 단계의 가옥으로서 학술적인 가치가 있고, “ㄱ”자형 사랑채 건립은 이 지역에서 매우 보기 드문 예이다. 그리고 백범 김구선생 은거(1898년경)와 관련한 장소로서의 의미도 있는 곳이다.","a":"함평이재혁가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662287.jpg"},{"q":"○○○에는 ○○ 2기가 대웅보전 안에 있다. ○○ 1은 좌대와 패신으로 나뉘어 지는데, 패신 앞면에는 ‘우순풍조 국태민안(雨順風調 國泰民安)’이라는 글자(원래 한글로)가 적혀 있으며, 액자 주위로는 황용과 운문 등 화려한 문양을 장식하였으며, 크기는 높이 71.8 × 폭 40.5cm이다. ○○ 2는 좌대는 결실(현 복원됨)되고 앙련대와 패신만 남아있는데, 중앙의 액자에는 명문을 확인할 수 없으며, 주위로 봉황, 운문과 꽃을 화려하게 장식하였으며, 크기는 높이 34 × 폭 24.2cm이다.","a":"울진 불영사 불패","c":"시도유형문화유산","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641185.jpg"},{"q":"○○○ 초기○○○○○은 ○○시의 중심부를 서쪽에서 동쪽으로 흐르는 전천(箭川)하류의 북쪽 유역에 위치하고 있다. 이 유적은 1996년 관동대학교 박물관이 유적의 남쪽 부분인 ○○항만 확장지역에서 발굴을 실시하여 주거지 4기와 민무늬토기, 두드림무늬토기, 대롱옥, 곱은옥, 유리구슬, 은제귀걸이 등을 수습하였다. 1999년과 2000년에는 강릉대학교 박물관이 ○○○ 중심도로 건설지역과 인근지역에서 초기철기시대 주거지 45기와 9기를 각각 발굴하여 ○○○ 일대가 당시 대규모의 마을이 형성되었던 곳임을 알 수 있게 되었다.","a":"동해 송정동 철기시대유적","c":"시도기념물","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648952.jpg"},{"q":"○○○ 명부전에는 ○○ 지장상을 비롯해 모두 20구의 불상이 봉안되어 있다. 지장보살좌상을 중심으로 우측에 무독귀왕상(좌측 도면존자상은 도난) 1구, 시왕상과 동자상, 귀왕상, 판관상, 사자상, 역사상이 좌우로 각가 1구씩 배치되어 있다. 명부전 내 제상(諸像)은 모두 복장공이 마련되어 있음을 확인하였으며, 현재 제4대왕 오관대왕과 지장보살상에서 복장발원문을 비롯해 후령통, 경전의 일부가 확인되었다.","a":"통영 안정사 목조 지장시왕상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643146.jpg"},{"q":"할미성이라고도 불리는 충청북도 진천군 진천읍의 ○○○○은 『삼국사기』 전투기사에 보이는 ○○○으로 추정되고 있다. 남쪽으로 넓은 평야를 끼고 낮은 구릉지 위에 쌓은 포곡식 산성으로 내·외성과 자성(子城)을 갖춘 특이한 형식이다. 성의 총길이는 1,260m에 이르고 있으며 남쪽과 북쪽에 문터로 짐작되는 자리가 있다. 내성의 벽은 자연지형을 충분히 이용하여 흙을 층층이 다져서 쌓았고, 외성의 벽은 아래 기초부분에 자갈돌을 넣고 점토가 많이 섞인 흙을 채웠다. 성의 외부는 경사가 급한 지형을 이루고 있으나 안쪽은 비교적 경사가 완만하다.","a":"진천대모산성","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650127.jpg"},{"q":"조선 인조 때의 문신인 충숙공 이상길(1556∼1637) 선생의 초상화이다. 이상길 선생은 30세에 문과에 급제한 후 대사간, 대사헌 등을 역임하였다. 인조 15년(1637) 병자호란 때에 청나라 군대의 침략에 대항하여 강화도에서 종묘를 지키다 순절하였으며, 효종 8년(1657)에 충숙공에 봉해졌다. 비단에 채색하여 그린 초상화는 실물과 같은 규모인 가로 93㎝, 세로 186.5㎝의 크기이다. 의자에 앉아 있는 전신상으로, 사모를 쓰고 엷은 홍색의 단령을 입고 있으며, 두 손은 앞으로 모아 소매자락 안에 넣었다.","a":"충숙이공 영정","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636224.jpg"},{"q":"1786년에 중건하여 현재에 이르기까지 거창지역의 대표적인 문인들과 깊은 관계를 맺어 향토문화의 뿌리를 내리는데 기여하였고, 특히 임진왜란 때 의병을 일으켜 공을 세운 분들의 정신이 살아 숨쉬는 역사적인 장소임. 평면형식이나 장식없이 소박하면서도 간결한 가구기법등에서 중건 당시의 모습을 볼 수 있는 정면 4칸, 측면 1칸 규모의 조선 후기 건물임.","a":"거창만월당","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642347.jpg"},{"q":"조선 태종(재위 1400∼1418)의 5대 후손인 이서(1482∼?)를 추모하기 위하여 순조 3년(1803) ○○부사 이동야와 창평현령 이훈휘가 지은 것이다. 이서는 모반을 꾀한다는 이유로 중종 2년(1507)에 창평으로 유배되었다가 15년 만에 풀려난 뒤 한양으로 돌아가지 않고 ○○ 골짜기에서 서적을 편찬하며 자손과 제자를 가르치는데 전념하였다. ○○○은 제사를 지내기 위한 건물로, 앞면 5칸·옆면 2칸 규모이다. 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"담양 몽한각","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639890.jpg"},{"q":"원래는 상주 인평동에 있던 탑으로, 우암산 정상 부근에 흩어져 있었던 것을 용흥사로 옮겨 관리하였다가, 1998년 현재의 자리인 ○○○ 경내로 옮겨 ○○○○○으로 이름을 바꾸어 새로이 복원하여 세웠다. 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 형태로 원래 기단 일부와 탑신의 3층 몸돌 1개, 지붕돌 3개만 남아 있었다. 아래·위층 기단과 탑신의 몸돌에는 기둥 모양을 새겨 놓았다. 지붕돌은 낙수면이 완만한 경사를 이루고 네 귀퉁이가 살짝 치켜 올라갔으며, 밑면에 5단의 받침을 두었다.","a":"북장사 삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662917.jpg"},{"q":"○○면 진입로의 금호강변에 우뚝 서있는 2층 누각이다. 조선 태종 12년(1412)에 처음 짓고 선화루라 이름 지었던 것을 세종 7년(1425)에 지금의 자리에 옮겨지었다. 그 후 성종 25년(1494)에 정여창이 다시 짓고 ○○○라고 이름을 바꾸었다. 정유재란(1597)으로 불탄 것을 선조 34년(1601)에 복원하였고, 숙종 9년(1683)에 다시 지었다. 오랜 세월동안 많이 퇴락한 것을 1980년에 정비하였다. 앞면 5칸·옆면 2칸의 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. ○○○는 조선시대의 대표적인 양식을 간직하고 있는 우람한 건물이다.","a":"함양 안의 광풍루","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641556.jpg"},{"q":"전라남도 곡성군 석곡면에 있는 이 ○○○○은 무릎 이하가 매몰되었지만 거대한 석불상의 예로 주목을 끌고 있다. 머리광배와 불신을 하나의 돌로 만들었으며, 평평한 돌에 돋을새김으로 조각하였다. 마멸이 심해 세부 수법은 잘 알 수 없으나 민머리 위에 있는 팽이 같은 머리묶음, 목에 있는 3줄의 삼도(三道) 등은 비교적 뚜렷하다. 체구는 건장하며 옷은 양 어깨를 감싸고 있다. 굵은 옷주름이 양쪽 팔로 흘러내렸는데 역시 세부표현은 뚜렷하지 않다. 원형의 머리광배에는 아무런 무늬도 새겨지지 않았다.","a":"석곡리석불입상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661949.jpg"},{"q":"조선 선조(재위 1567∼1608) 때 울산판관과 영천군수를 지낸 오한 손기양(1559∼1617) 선생을 기리기 위해 지은 사당이다. 손기양 선생은 ○○ 석동산에서 의병을 일으켜 충의를 떨치기도 하였다. ○○○○는 선생의 후손이 조선 영조 29년(1753)에 짓고 1956년에 고쳐 지은 후 오늘에 이르고 있다. 앞면 7칸·옆면 3칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자인 팔작지붕이며, 치엄문, 삼문, 정열사 등이 함께 배치되어 있다.","a":"밀양 죽원재사","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664649.jpg"},{"q":"우리나라 지도상 호랑이 꼬리부분에 해당하는 곳에 자리하고 있는 ○○이다. 이곳을 ‘○○○’ 혹은 ‘동외곶’이라고 하는데, 서쪽으로는 영일만, 동쪽으로는 동해와 만나고 있어 일명 ‘대보(大甫)○○’라고도 한다. 높이 26.4m, 둘레는 밑부분이 24m, 윗부분이 17m로 전국 최대 규모이다. 겉모습은 8각형의 탑 형식으로 근대식 건축 양식을 사용하여 지었는데, 철근을 사용하지 않고 벽돌로만 쌓아올려, 오늘날의 건축관계자들도 감탄을 금치 못한다고 한다. 내부는 6층으로 되어 있으며, 각층의 천장마다 조선 왕실의 상징무늬인 배꽃모양의 문장(紋章)이 조각되어 있다.","a":"호미곶 등대","c":"시도기념물","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654450.jpg"},{"q":"용봉사 내에 자리하고 있는 사리탑으로, 모셔둔 사리의 주인공은 밝혀지지 않고 있다. 원래는 이 절 근처의 다른 곳에 있었던 것을, 1910년 경에 이곳으로 옮겨 세웠다. 바닥돌이 없어진 채, 기단(基壇)과 탑신(塔身)만이 남아 있는데, 기단은 심하게 닳아 조각의 형태가 뚜렷하지 않고, 둥근 공을 살짝 누른 듯한 모양인 탑신의 몸돌은 특별한 꾸밈을 두지 않았다. 지붕돌은 6각으로 이루어진 듯하나 각 부분이 심하게 닳아있다. 꼭대기에 있었을 머리장식은 모두 남아있지 않다. 원래의 모습을 많이 잃어가고 있으며, 제작된 시기도 알 수가 없다.","a":"용봉사부도","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661165.jpg"},{"q":"○○○는 지리산 남쪽 기슭에 있는 절로 통일신라 성덕왕 23년(723)에 삼법이 지었다. 지었을 당시의 이름은 옥천사였으나 통일신라 정강왕(재위 886∼887) 때 이름을 바꾸었다. 임진왜란 때 불타 없어진 것을 벽암이 조선 인조 10년(1632)에 새로 지어 오늘에 이르고 있다. ○○○의 ○○○○○은 ○○○ 내에 있는 전각으로 중국 불교 선종의 6대조인 혜능대사의 정상, 즉 두개골을 모시고 있는 건물이다. 통일신라 경애왕(재위 924∼927) 때 진감선사가 건물을 세워 육조영당이라 하였으며, 후에 금당이라 불렀다고 한다.","a":"하동 쌍계사 육조정상탑전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641648.jpg"},{"q":"계룡산의 북으로 뻗은 중턱에 절터가 있으며 이 지역을 법당골, 부도골 등으로 부른다. 마을에는 많은 석조물 조각들이 흩어져 있는데, 주변에서‘○○○’ 라고 찍힌 기와조각이 발견되어 ○○○터라고 부르고 있다. 절의 입구에는 당간지주가 서 있으며, 주춧돌과 장대석, 부도의 받침돌이 남아 있었는데, 현재 국립공주박물관으로 옮겨 놓았다. 당시 규모가 큰 절이었음을 추정할 수 있으며, 백제와 통일신라시대의 유물들로 보아 백제 후기나 통일신라시대 전기에 만든 것으로 보여진다.","a":"공주구룡사지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652727.jpg"},{"q":"임진왜란 때 승병으로서 나라를 구하는데 큰 공을 세운 서산대사·사명대사·기허당 3대사의 충열을 기리기 위해 세운 서원이다. 원래는 사당이었던 것을 조선 헌종 5년(1839) 지금의 위치인 영정사 안으로 옮겨 ○○○○이라 이름짓고 절의 이름 또한 표충사로 고쳤다. 고종 8년(1871) 대원군의 서원철폐령으로 없어졌다가, 1927년 절을 다시 지을 때 ○○○○ 건물도 함께 복원하였다. 그러나 일부 승려들이 절 안에는 서원이 있을 수 없으며 부처님과 3대사의 영정이 함께 있는 것은 더욱 안되는 일이라며 반대하였다.","a":"밀양 표충서원","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641457.jpg"},{"q":"조선 성종 때의 문신이자 태종의 둘째아들인 효령대군의 증손자인 ○○○의 충절을 기리고 있는 정려문에 내린 현판이다. ○○○은 김종직의 문인으로, 성질이 엄정하고 학문과 의술에 정통하였다. 성종 9년(1478) 주계부정에 제수된 후 성종 18년(1487) 과거에 장원으로 급제하여 정의대부에 임명되었다. 고모부인 임사홍 부자의 간사한 사실을 알고 성종임금에게 임사홍을 중요한 자리에 쓰지 말 것을 다섯차례나 상소로 올리기도 하였다. 하지만 이로 인해 연산군 10년(1504) 갑자사화 때 임사홍의 모함으로 두 아들과 함께 죽임을 당하였다.","a":"이심원충신정려현판","c":"문화유산자료","nc":"","r":"충청남도","s":"계룡시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661488.jpg"},{"q":"1책 17장으로 이루어진 필사본(筆寫本 - 34×20cm)으로 조선시대 순조(純祖) 24년(1834 甲午年) 정월에 김영락(金英樂)이 방어사(防禦使)인 한응호(漢應浩)의 명을 받아 6권을 만들어 향교(鄕校), 귤림서원(橘林書院), 향청(鄕廳), 영청(營廳), 대정학당(大靜學堂), 정의학당(義學堂)에 각 1권 씩을 배부하였다. 이 책은 영청에 있었던 것으로 제주인의 효자(孝子) 26인, 효부(孝婦) 5인, 열녀(烈女) 27인, 의사(義士) 3인 순으로 61인의 행적이 수록 되어 있다.","a":"효열록","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643348.jpg"},{"q":"조선 초기에 세워진 관청건물로 여러 번 고쳐진 것으로 추정된다. 일제강점기 시대 이후 관청건물로 쓰이면서 고쳐져 그 원형을 잃었다. 최근까지도 괴산엽연초생산조합의 관사로 쓰였으나 1996년 보수할 때 동헌건물로 복원되었다. 규모는 앞면 4칸·옆면 2칸이고, 지붕은 옆면이 여덟 팔(八)자와 비슷한 팔작지붕의 목조건물이다.","a":"괴산동헌","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638650.jpg"},{"q":"부산대학교박물관 소장 ○○○○은 탑신에 사천왕상이 부조된 고려시대 석탑이다. 원래 울산광역시 울주군 청량면 삼정리 대곡사지(大谷寺址)에 있었던 것인데, 1966년 11월 부산대학교박물관에서 이전 · 복원하였다. 무너져 있는 탑을 수습해 왔기 때문에 옥개석의 모서리 부분은 파손된 것이 있었으며, 기단부와 상륜부가 없어져 이전할 때 박물관에서 보충하였다. 탑의 높이는 3.2m로 약간 고상한 느낌을 준다.","a":"오층석탑","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636634.jpg"},{"q":"전라남도 진도군 ○○○에 있는 석굴의 벽면에 새겨진 이 불상은 엄지와 네번째 손가락을 맞대고 있는 손모양으로 보아 아미타여래를 표현한 것으로 보인다. 둥근 얼굴에 신체 또한 둥글게 팽창시켰지만 입체감이 없이 평면화되어 보인다. 옷은 양 어깨를 감싸고 있으며, 옷자락은 무릎까지 내려와 도식적인 물결무늬 옷주름을 이루고 있다. 가슴에는 사각형의 홈이 파여 있는데, 아마도 불상에 관련된 서적 등의 복장품(腹藏品)을 넣어두었던 곳으로 보인다.","a":"금골산마애여래좌상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662047.jpg"},{"q":"호암사는 백제 때 지어진 절이라 하나 언제, 누구에 의해 지어졌는지는 알 수가 없고 절 옆의 바위에 호랑이 발자국이 남아있어 호암사라 불리운다. 절터는 민가가 들어서 정확한 옛 모습을 알 수 없고, 현재 존재하는 호암사는 최근에 지은 사찰로 법당을 비롯하여 요사채, 산신각 등이 있다. 호암사터는 백제의 많은 절터 중에서 그 이름과 유래를 알 수 있는 중요한 유적이다.","a":"호암사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652683.jpg"},{"q":"일제시대 일본이 우리나라에 경제적인 수탈을 하기 위해 만든 ○○○○○ 건물로서 부산지역의 경제수탈에 앞장섰던 본거지였다. ○○○○○는 선진 농법을 전해주고 국토의 효율적으로 이용하여 더욱 잘 살게 해주겠다는 허울좋은 명분 아래 설립된 회사였으나 사실은 조선의 토지를 비롯한 노동력을 착취하기 위한 것이었다. ○○○○○으로 사용되었던 이 건물은 해방 이후에는 부산에 진주한 미군들의 숙소로 이용되다가 1949년 미문화원으로 개원하였고 1999년에야 비로소 반환되었다.","a":"구 동양척식주식회사 부산지점","c":"시도기념물","nc":"","r":"부산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645210.jpg"},{"q":"향교는 성현의 위패를 모시고 제사를 지내며, 지방 백성의 교육을 담당하기 위해서 국가에서 세운 교육기관이다. 조선시대에는 군마다 하나의 향교를 두었는데, ○○○○는 예안군에 설치하였던 향교로 태종 15년(1415)에 지었다. 선조 34년(1601)에 고쳤고, 영조 21년(1745)에 크게 수리하였으며 그 후에도 여러 차례의 수리가 있었다. 현재 교육공간인 명륜당과 동재·서재, 제사공간을 형성하는 대성전과 내삼문, 이외에도 여러 부속건물이 남아있다. 대부분의 향교는 명륜당과 대성전이 일직선상에 놓여 있는데, ○○○○는 명륜당이 왼쪽에 비켜서 있는 점이 특이하다.","a":"예안향교","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640278.jpg"},{"q":"추월산은 담양읍에서 7㎞ 떨어진 용면 월계리에 있으며, 해발 729m의 그리 높지 않은 산이다. 산의 정상에 오르기 전 암벽 위로 보리암(문화유산자료)이라는 암자가 있는데, 임진왜란(1592) 때 의병장 김덕령 장군의 부인이 순절한 곳으로도 알려있다. 보리암에 얽힌 전설을 보면, 고려 때 보조국사가 나무로 3마리의 매를 만들어 날려보낸 뒤 그 매가 앉은 자리에 절을 지었다고 하는데, 그 절이 바로 순천 송광사, 장성 백양사, 그리고 추월산의 보리암이라 한다. 추월산은 금성산성과 함께 임진왜란 때 치열한 격전지였으며, 동학 농민군이 마지막으로 항거했던 곳이기도 하다.","a":"담양추월산","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653940.jpg"},{"q":"경상북도 안동시 미질동에서 발견된 것으로 ○○○에 있었던 것인데, 안동댐 건설로 인해 ○○○가 없어지면서 인근의 봉정사로 옮겨 보관하고 있다. 금가루가 칠해져 있어 자칫 금동불상으로 오해를 받기도 하지만 석불이다. 머리에는 상투 모양의 머리묶음이 있고 얼굴은 둥근 편이다. 옷은 양 어깨에 걸쳐 입고 있으며, 가슴부분에 표현된 나비 리본 모양의 매듭이 인상적이다. 손은 오른손을 무릎 위에 올리고 손가락이 아래로 향한 모습으로 땅속의 악귀를 물리친다는 의미를 지닌다. 불상이 앉아있는 대좌(臺座)는 반원형으로 연꽃무늬가 새겨져 있다.","a":"안정사석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640305.jpg"},{"q":"문수산성은 문수산(해발 599m)의 8부 능선을 따라 테를 두르듯이 돌로 쌓은 테뫼식 산성이다. 성내에서 수습된 토기편과 기와편 등으로 볼 때 삼국시대에서 조선시대까지 울산·언양 일대를 방비할 목적으로 축조된 산성으로 추정된다. 성벽의 평면은 타원형으로 길이 850m정도이다. 남서쪽과 북쪽 일대는 성벽이 비교적 양호하게 남아 있지만 동쪽과 북서쪽 일부는 많이 훼손된 상태이다. 성벽은 내벽과 외벽을 쌓는 협축(夾築)이며 단면은 사다리꼴을 이루는데 가공된 듯한 자연석과 막돌을 이용하여 성돌이 서로 물리도록 쌓았다.","a":"문수산성지","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645907.jpg"},{"q":"넓은 대지에 연못과 정원을 갖춘 한옥으로 1910년대에 지은 것이다. 건축부재의 사용과 기단 처리에 있어서 이 시기 개량 한옥의 모습을 잘 보여주고 있으며, 사랑채가 분리되어 있지 않은 점도 특징적이다. 원형이 잘 보존되어 있는 일제시대의 전통 한옥으로, 고유의 멋을 잘 간직하고 있는 건축이다.","a":"체부동 홍종문 가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658078.jpg"},{"q":"당산이란 신(神)이 있다고 믿고 섬기는 민간신앙의 대상물이다. 제작년대를 정확히 알 수 없는 이 당산은 조선 철종 9년(1858)과 고종 15년(1878)에 부분적인 보수를 거쳤으며, 1991년 대대적인 보수를 하여 지금에 이르고 있다. 삼국시대 때부터 전해 내려오는 이 고장의 유서깊은 곳이다.","a":"거창당동당집","c":"시도민속문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659070.jpg"},{"q":"조선시대 ○○읍성의 남문으로 이름은 멀리 지리산이 보인다는 뜻으로 망악루라 했으나 1932년 지금의 자리로 옮기면서 ○○○로 고쳤다. 앞면 3칸·옆면 2칸의 2층 건물이며 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있다. 2층 내부는 단청으로 칠했으며 난간을 둘렀고 나무로 된 계단을 설치해 1층으로 통하게 만들었다. 1층에는 기둥에 남아있는 흔적으로 보아 기둥 사이에 벽과 문짝이 있었음을 알 수 있다. 이것은 읍성의 남문으로 사용했을 때 있던 것으로 보인다.","a":"함양 함화루","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642077.jpg"},{"q":"○○○는 운차산 기슭에 있는 절로 지은 시기는 정확히 알 수 없고, 다만 통일신라 진성여왕(재위 887∼896)대에 최치원이 지었다고 전하고 있다. 임진왜란으로 대부분의 건물이 불탔으나 ○○○만은 칡뿌리 등이 건물을 감싸고 있어 화를 면하였다고 하여 당시에는 갈천사로 불렀다고 한다. 현재는 ○○○과 요사채만 남아 있다. ○○○은 고종 7년(1870)에 고쳐 세웠는데 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다.","a":"서동사대웅전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662164.jpg"},{"q":"이 성책은 사찰의 토지대장으로, ○○○ 소유토지대장 중 일부분이지만 여기에서 250년전의 조계종사찰 재정을 알 수 있을 뿐만 아니라 ○○○의 토지재산을 알 수 있다. 크기는 세로 66㎝, 가로 46㎝이며, 전후 표지를 합해 19매이다. 내용을 보면 ○○○의 본사(本寺)와 여러 소속암자의 토지 및 불양답(佛養畓:사찰에 기증한 토지)을 구분하고, 전답의 소재지·명칭·위치·형태·등급·경작인·조세 등을 표시하고 있다. 그리고 각 전답에는 이 절의 소유토지의 기장번호가 있다.","a":"실상사위토개량성책","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639492.jpg"},{"q":"○○은 왕실에 왕자나 공주 등이 태어났을 때 그 태를 넣어두던 곳으로, 이곳에는 ○○의 태가 안치되어 있었다. 항아리에 태를 넣어두었던 것을, ○○가 왕위에 오른 후에 왕의 ○○로서 여러 석물을 갖추고 ○○비를 세웠다. ○○의 형태는 8각을 기본으로 한 부도(승려의 사리탑) 모양을 하고 있으며, 주변에는 8각의 돌난간이 둘러 놓았다. 앞에는 거북모양의 받침돌과 용을 새긴 머릿돌을 갖춘 ○○비가 있는데, 앞면에 ‘주상전하○○’이라고 새겨 놓았다. 조선 정조 11년(1787)에 만든 것으로, 이 때부터 ○○이 있는 산을 태봉산이라 하고 ○○현을 군으로 승격시켰다 한다.","a":"보은 순조 태실","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020032315112000.png"},{"q":"1927년 초대 천주교대교구장인 Demange 주교가 ○○○○○ 코미넷관 우측면의 아케이드(arcade)에서 북쪽으로 이어 증축한 성당건물이다. 남북으로 긴 장방형의 평면을 가진 소규모 성당건물로 건축 당시 북쪽으로 5각형의 제단과 남쪽 아케이드에 있는 주 출입구 안쪽 2층에 성가대석이 있었다. 전체 외벽은 화강석 기초 위에 붉은 벽돌을 사용하였고 외벽의 붙임기둥에는 회색 벽돌을 쌓아 외관을 구성하였다. 내부 천장은 아치형 천장이며, 외벽의 창호는 첨두아치창을 설치하였다. 지붕은 함석판 거멸접기로 마감한 박공지붕의 형태로 되어 있다.","a":"샬트르성바오로수녀원성당","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636925.jpg"},{"q":"삼악산성은 삼악산의 능선 계곡 왼쪽 정상을 따라 쌓은 성이다. 삼악산은 춘천-서울간 역로(驛路)였던 곳으로, 석파령을 내려다보는 곳에 천연의 험준한 산세를 이용하여 마주보고 있는 두 정상의 능선을 따라 산성을 쌓았다. 태봉국을 세운 궁예가 철원에서 왕건에게 패하고 샘밭 삼한골을 거쳐 이곳에 성을 쌓아 피신처로 이용했다는 전설이 전해 온다. 또 삼국시대 이전에 춘천지역에 있던 부족국가인 맥국(貊國) 사람들이 쌓은 성이라는 설도 있다. 산성의 길이는 약 5㎞로, 성벽은 동쪽에서 남서쪽으로 길게 뻗어 자연석을 이용하여 자연 지형에 따라 높이 1∼3m로 쌓았다.","a":"삼악산성지","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660425.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 3년(1403)에 처음 지었는데, 임진왜란 때 불타 없어져, 그 뒤 지방 유림들이 다시 지었다. ○○○의 규모는 앞면 3칸 반으로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 옆면에는 바람막이 방풍판을 달았다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"여산향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661697.jpg"},{"q":"경상북도 경주시 배반동 동쪽을 향한 높이 2m의 바위벽에 새긴 마애불이다. 바위벽을 얕게 파 높이 1.5m의 공간을 만들고 그 안에 약 0.9m 정도의 작은 부처를 도드라지게 새겼다. 양쪽 뺨 가득히 자비 넘치는 미소를 간직하고 앉아 있는 불상은 전체적으로 조각수법이 거친 편이다. 특히 위에서 아래로 내려갈수록 선을 그은 것처럼 얕게 새겨 매우 독특한 조각수법을 나타낸다. ○○○의 석불좌상보다 후대에 만든 것으로 여겨지는데, 통일신라 후기에 만들어진 불상으로 추정된다.","a":"보리사마애석불","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640677.jpg"},{"q":"장정이산에서 남쪽으로 흘러내린 서쪽의 완만한 구릉에 분포한 17기의 무덤으로 ‘말무덤’·‘몰무덤’·‘마분’이라고 불리는 곳이다. 영산강 하류 지역은 다른 지역에서는 찾아볼 수 없는 독특한 무덤인 대형독무덤(대형옹관고분)이 분포하고 있는데, 이 지역도 그중 한 곳이다. 무덤의 형태는 원형, 타원형, 방대형을 이루며 주변에서 대형 항아리관 조각이 보여 독무덤임을 증명해 주지만 널무덤(토광묘)일 가능성도 배제할 수 없다. 유물은 거의 도굴되었으나 주민들에 의하면 밭을 경작하다 칼, 토기들이 나왔다고 한다.","a":"영암금계리고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654305.jpg"},{"q":"조선 중기의 문신인 ○○○ 선생의 비이다. ○○○은 광해군 5년(1613) 생원이 되었으며, 이이첨의 사주를 받은 정조, 윤인, 이위경 등이 인목대비를 해치려고 할 때 이들의 목을 벨 것을 상소하다 길주에 유배당하고 뒤에 진도로 옮겨 유배생활을 하였다. 인조반정으로 관직을 되찾아 의금부도사를 지냈으며 청안현감이 되었고, 이후 남원, 죽산의 부사와 공주, 청주의 목사 등을 두루 지냈다. 오랜 외직생활동안 백성들에게 선정을 베풀었으며, 청렴하고 강직한 목민관으로 이름을 떨쳤다.","a":"목사김효성의비","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660999.jpg"},{"q":"문경현의 남쪽 40리 정도에 위치하고 있는 ○○○에 관련된 문서이다. ○○○은 조선시대 아홉 개의 간선도로 가운데 제4로와 5로가 경유하는 곳으로, 영남지역에서 서울을 잇는 주요 교통의 요충지였다. ○○○에 딸린 속역은 18개였고, 이곳에는 종6품 찰방이 설치되어 있었다. 문서와 관련된 인물인 임종수(1841∼1893)는 역 출신으로 구한말 관료에 입신하였던 것으로 짐작된다.","a":"유곡역고문서","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640983.jpg"},{"q":"○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑으로, 부정과 악의 출입을 막아 마을을 편안하게 하고자 하는 신앙 대상물이다. ○○○ 주거지역 서쪽에는 4기의 ○○○이 남북으로 놓여 있는데, ‘앞논’이라 부르는 이곳의 허한 기운을 보강하여 부정과 액운을 막기 위해 쌓아놓은 것으로, 전체적으로 음양을 고려하여 배치한 듯하다. 이 탑은 그 중 하나로, 탑의 훼손이 심하여 원래의 모습을 할 수 없다.","a":"무릉리방사탑2호","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659274.jpg"},{"q":"강원특별자치도 양양군에 위치한 ○○○○는 나라에서 ○○○에게 풍농풍어(豊農豊魚)와 마을의 안녕을 기원하기 위하여 제사를 지내던 곳이다. 우리나라는 일찍부터 산천과 바다에 제사를 지냄으로써 풍요와 안녕을 기원하였다. 세운 시기는 정확히 알 수 없으나『고려사』를 통해 고려시대에 이미 나타나 조선 초기에 국가 제사 장소로 정비되었던 것으로 보인다. 북서쪽으로 대나무와 솔밭이 있고, 서쪽은 민가와 접해있다. 남쪽과 동쪽은 밭으로 이용되고 있으며 높은 대지 위에 새로 지은 정전이 1동 있는데 일제시대에 철폐되었다가 1993년에 다시 세운 것이다.","a":"양양동해신묘지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648427.jpg"},{"q":"미륵산 정상 부근에 있는 사자사터이다. 사자사는 미륵사보다 앞서 창건된 사찰로서 백제의 무왕과 선화비가 이 사자사로 행차하던 중 용화산 아래 연못에서 미륵삼존불이 나타나자 이를 계기로 ‘미륵사’를 창건하였다고 한다. 미륵사 창건의 계기를 마련해준 점에서 백제 불교사상 중요한 이 절은 위치에 있어서 논란이 있어왔지만 1993년 발굴조사에서 기와조각들이 발견됨으로써 사자사터임이 확인되었다. 옛 모습은 찾을 수가 없고 현재는 석가모니를 모신 대웅전과 스님들이 기거하는 요사채 그리고 창고 등이 있으며 대웅전 앞에 석탑 1기가 남아있다.","a":"사자사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653697.jpg"},{"q":"○○○○○에 모셔져 있는 나무로 만든 석가여래좌상이다. 석가여래상은 얼굴을 약간 숙이고 등을 곧게 편 채 결가좌하고 있다. 머리 부분의 크기에 비해 둥글게 쳐진 어깨 부분이 왜소하며 상반신이 비교적 가늘고 긴 편이다. 얼굴은 네모꼴에 가까우며, 작은 소라 모양의 머리칼이 묘사된 머리에는 정상계주와 중앙계주가 표현되어 있다. 머리 부분은 흑칠을 하였고, 발제선·눈썹·수염은 녹청으로 처리하였다. 안와선·콧볼·입술·턱주름선은 양감있게 표현되어 있고, 귓불은 두터운 편이나 밋밋하게 처리되어 있다.","a":"마하사 응진전 목조석가여래좌상","c":"문화유산자료","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659365.jpg"},{"q":"조선시대 조성된 ○○로 정확한 조성연대는 미상이나 ○○○이 1280년(충렬왕 6) 문하시중에 올랐으며, ○○에 장지(장지)를 정한 이래 후손들의 세거지(세거지)가 되었다. 묘표는 1919년에 세워진 것으로 추정된다. ○○은 ○○○의 차자로 ○○○○○ 뒤편에 있는데 조성시기는 조선시대이며 묘표와 문관석은 조성 당시의 것이고 묘비는 1980년에 세웠다. ○○○○○는 약160㎡정도의 방형분으로 4～5단 쌓아 호석을 두르고 있으며호석의 높이는 90㎝이다.","a":"충주 우천석·우팽 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651437.jpg"},{"q":"종이에 그린 ‘○○○○○’는 얼핏 보아도 모사본으로 판단될 정도로 선묘와 색상이 특이하다. 이 ○○○의 얼굴 부분은 다른 그림에 있는 것을 오려서 붙인 것이다. 관모의 양각 좌우의 끝부분부터 시작하여 얼굴의 윤곽을 따라 흉배 윗부분으로 이어지는 경계선에서 붙인 흔적을 발견할 수 있다. 그 나머지 부분인 관복과 의자, 족좌 등은 연결하여 그린 뒤에 결합한 상태이다. 이 영정의 얼굴은 ○○○의 공신도상과 자세 및 이목구비의 형태가 정확히 일치하고 있어, ○○○의 호성공신도상을 모사했을 가능성이 크다. 이 영정의 뒤편에는 화기가 붙어 있다.","a":"광명 이원익 초상화","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637796.jpg"},{"q":"바위의 윗부분을 평평히 다듬고 네모난 받침돌을 놓아 3층의 탑신(塔身)을 올린 석탑이다. 탑신의 1·3층 몸돌은 각각 한 돌로 되어있고, 2층 몸돌은 1층 지붕돌과 한 돌로 조성되었다. 지붕돌은 밑면에 3단씩의 받침을 높게 새긴 점이 특징적인데, 네 귀퉁이의 치켜올림과 잘 어울려 안정감을 준다. 꼭대기에는 머리장식을 받치던 네모난 받침돌만 남아 있다. 각부의 양식수법으로 보아 고려시대의 것으로 추정된다.","a":"증평 남하리사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638611.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모시는 곳이다. 이 부도는 봉서사내에 자리하고 있는 것으로, 조선시대의 승려인 ○○○○의 사리를 모시고 있다. ○○○○는 이 절을 새단장한 후 이곳에 머물며 수행하다 일생을 마쳤다. 탑은 기단(基壇) 위로 둥근 탑신(塔身)을 올린 형태로 대부분의 부재가 8각을 이루고 있다. 2단으로 이루어진 기단은 대칭되는 구조를 하고 있으며, 서로 맞닿는 곳에 각각 연꽃을 굵게 새겼다. 탑신의 몸돌은 아래·윗면이 약간 눌린 둥근 모습으로, 그 위로 뭉뚝한 지붕돌을 올리고 있다.","a":"진묵대사부도","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639534.jpg"},{"q":"신도비란 왕이나 고관 등의 평생업적을 기록하여 후세에 전하고자 그의 묘 남동쪽에 세워두는 비로, 이비는 조선시대 중기의 문신이자 시조 작가인 농암 이현보(1467∼1555) 선생을 기리고 있다. 농암은 연산군 4년(1498) 32세의 나이로 과거에 급제하여 벼슬길에 올랐다. 38세 때 사간원정언이 되었으나 서연관의 잘못됨을 지적하다 안동에 유배되어, 중종반정 이후 다시 복직되었다. 56세 때에는 성주목사가 되어 민심을 잘 다스려 표창을 받기도 하였다. 76세 때에는 지중추부사에 임명되었으나 병을 핑계로 관직을 그만두고 고향에 돌아와 시를 지으며 남은 생을 보내었다.","a":"농암신도비","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662473.jpg"},{"q":"○○○의 절 한켠에 자리하고 있는 비로, 벽암대사의 행적을 적고 있다. 벽암대사는 조선 중기의 승려로, 법명은 각성이며, 벽암은 그의 호이다. 임진왜란 때에는 해전에 참여하였고, 인조 때 남한산성을 쌓을 때에는 8도도총섭으로 임명되어 승려들을 이끌고 3년만에 공사를 완성시키었다. 인조 14년(1636) 병자호란이 일어나 왕이 남한산성으로 천도하자 승려 수천 명을 모집하여, 호남의 군사들과 함께 적들을 섬멸하였다. 남한산성으로 향하던 중 전쟁이 끝나버리므로 승려들을 돌려보내고 지리산으로 들어갔다.","a":"보은 법주사 벽암대사비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638498.jpg"},{"q":"이 ○○○○○는 중앙에 원형의 두광과 신광을 두르고 있는 지장보살이 위치하고, 그 아래 동자 2구, 좌우로는 도명(道明)과 무독귀왕(無毒鬼王) 등 협시를 비롯하여 시왕, 판관, 사자, 천녀, 옥졸(仰髮,牛頭,馬頭) 등이 둘러싸고 있는 군도형식을 보여 주고 있다. 지장보살은 화면 하단에서 솟아 오른 연꽃 위에 결가부좌하였는데, 원형의 두광과 신광의 이중륜광(二重輪光)을 갖추고 있다.","a":"개운사 지장시왕도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593277.jpg"},{"q":"남원 ○○○○은 해발 518m의 ○○○의 천연적인 지형지세를 이용하여 돌로 쌓은 산성으로, 둘레는 3120m이다. 현재 무지개 모양으로 입구가 표현된 동문과 성문을 보호하기 위하여 만든 작은 성인 옹성, 그리고 군데군데 성벽이 남아 있다. 온전하게 남은 동문터와 수문에 보이는 성벽의 구조는 우리나라 성곽 연구에 중요한 자료가 된다. 성안에는 우물 99개와 계곡이 있어서 산성 주변의 주민들이 유사시에 대피나 전투의 목적으로 사용하기 좋았을 것으로 짐작된다. 조선 전기에는 군대의 식량을 저정하는 창고가 있었다.","a":"남원교룡산성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653324.jpg"},{"q":"정문(旌門)이란 충신·효자·열녀들을 표창하기 위해 마을 입구나 집 문앞에 세우던 붉은 문을 말한다. 이 정문은 조선 선조(재위 1576∼1608)대부터 영조(재위 1724∼1776)대까지 ○○○○ 가문의 6인의 효자와 2인의 효부에 대한 효행을 기리기 위해 영조 40년(1764)에 세운 정문이다. 이곳에서 받들고 있는 6인 효자는 이학수, 이탱, 이만춘, 이채, 이복초, 이종철이고 2인의 효부는 복초의 처인 장씨와 종철의 처인 김씨이다. 정문의 규모는 정면 5칸·측면 1칸으로, 지붕선이 옆에서 볼 때 사람 인(人)자 모양의 단순한 맞배지붕이다.","a":"영동 덕수이씨 육세팔효정문","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650558.jpg"},{"q":"1892년 후불탱화 및 삼장보살도와 함께 조성, 봉안되었던 것으로, 민두호 및 상궁의 시주에 의해 금어(金魚) 한봉창엽(漢峰瑲曄)과 혜산축연(蕙山竺衍), 홍범(弘範), 허곡긍(虛谷亘㥧), 慧寬(혜관), 戒雄(계웅) 등이 그린 것이다. 크기는 세로 200cm, 가로 316.5cm로 비교적 큰 편에 속한다. 가로로 긴 화면의 상단에는 칠여래가 합장을 한 채 나란히 서 있으며, 좌측에는 아미타삼존(阿彌陀三尊)과 왕후장상(王侯將相), 선왕선후(先王先后), 북채를 든 뇌신(雷神), 우측에는 지장보살과 관음보살 등이 구름 위에 서 있다.","a":"봉은사 감로도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636424.jpg"},{"q":"○○○은 원래 신라 왕실에서 사용하던 집기 등을 보관하던 곳이다． 고려와 조선시대에는 외국 손님이나 중앙 관리들이 경주지방을 방문하였을 때 머물거나 대기하던 객사로 이용되었다. 지금 있는 건물은 조선 정조 10년(1786)경에 다시 지은 것으로 일부만 남아 있다. 3동(정청·동헌·서헌) 건물이었던 것을 일제시대에 국민학교로 사용하다가 해방 후 철거하고 서헌만 지금 있는 자리로 옮겼다. 건물을 옮기기 전에는 정청에 조선 태조의 위패를 모셨다．동서쪽 건물은 6관의 관방(官房)이라 하였으며, 신라 옥피리를 비롯하여 청동제 화로 등이 발견되었다고 한다.","a":"동경관","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662349.jpg"},{"q":"∙ 기헌구려는 기헌(起軒) 강두환(姜斗煥, 1781~1854)이 창건하여 거주하던 주택으로 정조 5년(1781)에 출생하여 순조 7년(1807)에 식년문과에 급제하여 시강원(侍講院) 필선(弼善)으로 세자인 헌종을 가르쳤다. 이후 봉화 법전리로 낙향하여 더 이상 벼슬길에 나가지 않았다. 그 이듬해 헌종 11년(1845)에 현재의 자리에 거주할 주택을 창건하였다고 한다. ∙ 본체는 전면부분 6칸과 측면 2칸 모두를 사랑공간으로 구성하였다. 좌측에 온돌방과 감실을 전후에 두고 우측편으로 툇간과 온돌방 2칸을 도리방향으로 배치하고 뒤편에 벽장을 두었다.","a":"봉화기헌고택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663367.jpg"},{"q":"합덕 평야에 농업용수를 조달하던 저수지로, 연꽃이 만발해 연지(蓮池)라고도 불리웠다. 지금은 저수지가 논으로 변하여, 제방만이 남아 있다. 제방은 평지로부터 높이 7∼8m, 전체길이 1,771m에 이르는 큰 방죽으로, 흙을 쌓아 만들었으나 후에 돌을 이용하여 보수한 부분도 보인다. 제방의 서쪽 끝에는 보수할 때의 기록을 적어둔 중수비가 5기 남아있다. 제방이 만들어진 정확한 연대는 알 수 없으나, 통일신라 후기 후백제를 세운 견훤이 축조한 것으로 전하고 있다. 김제 벽골제의 제방이 일직선인데 비해, 이곳의 제방은 곡선으로 이루어져 있어 특이하다.","a":"당진 합덕제","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652801.jpg"},{"q":"공신녹권이란 나라에서 공이 있는 신하를 공신으로 임명하여 발급하는 임명서로, 이 공신녹권은 ○○○에게 ○○○○ 2등에 봉한다는 내용이다. ○○○○이란 임진왜란 때 선조가 의주까지 피난을 할 때 시종하는데 특히 공이 컸던 사람에게 내린 녹권인데, 이항복 등 모두 86명으로 1등 2명, 2등 31명, 3등 53명이다. ○○○은 임진왜란이 일어나자 선조를 모시고 의주의 행재소에 호종하다가 병으로 사망하였다. 이 때의 공로가 인정되어 선조 37년(1604)에 비록 사후이기는 하나 ○○○○ 2등에 책록되었다. 이 녹권은 필사된 뒤에 ｀시명지보(施明之寶)´의 도장이 찍혀있다.","a":"박숭원 호성공신교서","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638653.jpg"},{"q":"한 채의 비각 안에 나란히 서 있는 3기의 비이다. 왼쪽에 있는 것은 ○○○○로, 대구판관을 지낸 이서 선생의 치적을 기리기 위해 대구 주민들이 세운 것이다. 당시 대구는 하천이 중심부로 흘러 홍수 때마다 큰 피해를 당하였었다. 조선 정조 즉위년(1776) 대구판관으로 부임해온 이서 선생은 주민들의 어려움을 알고 1778년 자신의 재산을 털어 제방을 쌓아 물길을 돌리게 하였다. 홍수의 피해에서 벗어난 주민들은 물길을 돌려 새로 만든 냇물을 ‘신천 ’이라 부르고, 제방의 명칭도 ‘○○○ ’라 한 후 정조 21년(1797)에 이 비를 세워 그를 기리고자 하였다.","a":"이공제비및군수이후범선영세불망비","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636881.jpg"},{"q":"낮은 구릉의 정상부에 있는 5기의 무덤들이다. 봉분은 높이가 1m 정도이며 길이는 13m 내외의 네모꼴인데, 발굴조사에 의하면 분구와 주구내에서 독무덤(옹관묘) 12기, 돌널무덤(석관묘) 6기, 널무덤(토광묘) 2기가 확인되었다. 이 무덤은 마한의 지배계급층 무덤으로 역사적으로 매우 중요하며, 무덤 주변에 구덩이를 돌려 판 주구무덤 형식은 고대 일본과의 밀접한 관련성을 보여준다.","a":"율촌리고분군","c":"시도기념물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653703.jpg"},{"q":"밀양 박씨 문중에서 조선 현종 7년(1666)에 눌재 박증영(1464∼1493)과 그의 아들 강수 박훈(1484∼1540)의 시문집을 만들기 위하여 판각한 것으로, 송시열이 지은 서문과『눌재·○○○○』문필을 모아 1책으로 엮었다. 박증영은 조선 전기의 학자로, 1483년 문과에 급제하여 홍문관교리 등의 벼슬을 했다. 문장에 뛰어나 이름을 떨쳤고, 매우 청렴하여 사람들이 늘 존경하였다. 그의 아들 박훈은 1519년 문과에 급제하여 동부승지까지 올랐고, 나라의 그릇 즉 ‘국기(國器)’라는 명성을 들었다.","a":"눌재강수유고 목판","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638670.jpg"},{"q":"이 불상은 경주의 서쪽에 위치한 ○○○에서 동쪽으로 뻗어 내린 능선에 있다. ○○○은 경주의 서쪽에 위치하는 선도산(仙桃山)과 더불어 서방을 이루는 중요한 산 가운데 하나이다. 불상의 광배(光背)는 배 모양으로 바위를 다듬었고 별다른 조각으로 장식하지는 않았다. 불상은 돋을새김을 하였는데 전체가 마모되어 세부 표현은 정확하게 알아보기 어렵다. 머리에는 상투 모양의 머리묶음을 큼직하게 조각하였고, 굵고 긴 목에 세 줄의 삼도(三道)를 나타내었다. 옷은 양쪽 어깨에 걸치고 있으며 가슴에서 무릎까지 반원형의 층단을 이루며 흘러내리고, 바지자락이 발목을 덮은 듯하다.","a":"경주벽도산석불입상","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662352.jpg"},{"q":"무안 ○○○○○는 ○○○과 같이 있다. ○○○은 원래 고려 충열왕 때 인물인 면남(綿南) 박문오(朴文晤)가 낙향하여 지은 정자로 알려져 온다. 후에 박문오의 증손 풍정 박의룡(楓亭 朴義龍)이 조선 개국기에 활동하면서 이조, 호조 등의 판서를 지내다가 퇴관한 뒤 이곳에 내려와 지냈다고 한다. 세조 때 무안으로 낙향한 애한정 박익경(愛閑亭 朴益卿)은 박문오의 7대손으로 ○○○을 중수한다. 그 뒤의 중수에 관한 기록은 자세하지 않으나 지역의 교류 공간으로, 후손들의 공동체 공간으로 활용되었다고 보아진다.","a":"무안유산정유적비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662293.jpg"},{"q":"○○○는 판서 송월당(松月堂) 박호원(朴好元)의 재실이다. 입암(立庵) 박헌수(朴憲修)의 기문과 송주(松州) 하도(河圖)의 현액이 있다. 네 모서리에는 활주가 세워져 있으며 외진주는 원기둥이고 내진주는 네모난 기둥이다. 중앙 마루 전면에는 계자난간을 비워 출입하는 곳으로 이용하고 있고, 양측면의 방 출입구는 세 짝 분합문으로 구성하였는데 세살문 형식을 보인다. 재실 서측에는 암반 밑에 얕은 우물이 있고 장방형의 연못이 연결되어 있다.","a":"산청 이사재","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664981.jpg"},{"q":"○○○는 대문채, 재실, 사당, 비각, 장판각, 관리사, 화장실 각 1동씩과 협문 2동으로 구성되어 있다. 전체 배치는 북향하고 있는 언덕 기슭에 전면에 좁은 집입로를 두고 방형의 담장으로 둘러쳐진 영역을 이루었다. ○○○의 공간구성은 전면 5칸, 측면 2칸의 팔작집 구성이다. 서쪽에 2칸 폭에 1.5칸의 깊이를 가진 큰 방을 두었는데, 전면은 퇴를 두었고 두 방은 미서기문으로 구획하였다. 동쪽 끝 한 칸의 전면은 누마루를, 후면에는 온돌방을 두었다. 중앙의 대청마루는 4칸의 넓은 공간으로 구성하였고, 후면에 바라지문을 두고 퇴를 달았다.","a":"합천 저존재","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666640.jpg"},{"q":"높은 터 위에 행랑대문채가 있고 그 안에 사랑채와 안채가 있는 집이다. 대문채는 一자형으로 오른쪽 둘째 칸은 사랑채와 연결되어 있고, 사랑채는 방과 방으로 연결되어 있으며 서쪽에는 툇마루를 달았다. 안채는 행랑대문채의 동북쪽에 자리하고 있고, 대청을 중심으로 좌우에 건넌방과 안방이 배치되어 있다. 안방의 남쪽에 부엌과 방이 있으며, 사랑채와 안채의 옆면 뒷쪽에는 정원으로 출입할 수 있도록 내칸을 두었다. 그리 오래된 것은 아니지만 안채와 정원이 잘 꾸며져 있으며, 전통 한옥건물에서 조금씩 현대화해가는 초기 과정의 특색을 보이고 있는 집이다.","a":"반계 윤웅렬 별장","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658049.jpg"},{"q":"승려이며 시인인 ○○○ 선생이 태어난 곳이다. 선생은 충청남도 홍성 출신으로 독립운동가로도 활동했으며 호는 만해(萬海)이다. 1919년 3·1운동 당시 민족대표 33인 중의 한 분으로 독립선언서를 낭독한 후 체포되어 3년형을 받았다. 일제에 대항하는 단체였던 신간회를 주도적으로 결성하였는데, 이 신간회는 후에 학생 의거와 전국적인 민족 운동으로 전개되고 추진되었다. 저서로 『님의침묵』, 『불교대전』 등을 남겼으며 그의 사후인 1962년 대한민국 건국공로훈장이 수여되었다. 낮은 야산을 등진 양지 쪽에 자리잡고 있으며, 생가가 쓰러져 없어진 것을 1992년에 복원하였다.","a":"한용운선생생가지","c":"시도기념물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652810.jpg"},{"q":"龍淵寺는 대한불교 조계종 제4교구 월정사의 말사로, 1650년 인조(仁祖) 때 도승(道僧) 옥잠(玉岑)이 창건하였다고 전하며, 일설에는 왕침대사(王葴大師)가 응봉산 동쪽 용연동 만월산(萬月山)에 창건하였다고 전한다. 1950년 한국전쟁때 全燒되었다가 한 女僧의 盡力으로 중건되었다. 『東國與地勝覽』과 『輿地圖書』등 朝鮮時代 문헌에는 기록이전혀 없어 정확한 창건연대와 내력에 대해서는 알 수 없다. 그러나 江陵邑誌인『增修臨瀛誌』寺刹條에 <龍淵寺在府北三十里二十間…有僧玉岑經始此寺云>이라고 하여 順治年間(1644년 경)에 승려 옥잠이 처음으로 이절을 세웠다고 전한다.","a":"강릉용연사 석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660640.jpg"},{"q":"민족 금융기관이었던 ○○○○의 본점 건물이다. 충청남도 서북지역의 교통 및 상업 중심지에 자리한 ○○○○은 조선총독부가 들어선 후 더욱 더 심해진 일본의 금융압박 속에서도 민간자본을 형성하는데 큰 역할을 하였던 민족계 지방은행이다. 2층의 서양식 건물로, 중후한 멋과 비례감이 잘 조화를 이루고 있다. 1, 2층의 창문을 하나로 연결하여 근대적인 감각을 살렸으며, 출입구 부분을 돌출시켜 그 위의 지붕을 곡선으로 처리하는 등 앞면을 강조하였다. 1913년 지역의 민간유지들에 의해 건립된 이 건물은 작은 규모이면서도 당당한 외관을 갖추고 있다.","a":"예산호서은행본점","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652793.jpg"},{"q":"조선 후기의 문신인 조영복(1672∼1728)이 북경을 다녀올 때 쓴 친필일기와 동료 대신들과 주고 받은 송별시 및 편지 등을 모아 만든 것이다. 조영복은 1714년 예천군수로 있으면서 문과에 급제하여 정언, 헌납 등의 벼슬을 지내고 동래부사를 거쳐 도승지를 지냈다. 이인좌의 난이 일어나자 한성부우윤이 되었고 난이 평정된 뒷 벼슬길에서 물러났다. 서예에도 뛰어난 인물이었다. 『○○○○』은 숙종 45년(1719) 11월부터 숙종 46년(1720) 3월까지 북경을 다녀올 때 그가 직접 쓴 일기로, 1책 64장으로 되어 있다.","a":"연행일록부연행별장외명현간찰","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637612.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○○ 고인돌은 전형적인 바둑판식으로 계곡 평지에 10여 기가 분포하고 있으며, 덮개돌의 길이가 3∼4m 내외인 고인돌이 무리를 이루고 있다.","a":"여수 오림동 지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654310.jpg"},{"q":"○○○○○은 고려 말 성리학자인 목은 이색牧隱 李穡의 영정을 모셔 놓은 목은영당牧隱影堂의 부속 건물이다. ○○○○은 학문을 닦던 장소로서 언제 처음 지었는지 정확히 알 수 없으나 이곳을 통해 많은 유학자들이 배출되었다고 전한다. 창건 이후 여러 차례 보수하였고, 1966년 옛 모습에 가깝게 복원하였다. 강당은 정면 5칸, 측면 2칸의 목조기와집이다. 평면은 중앙에 대청마루를 두고 좌우로 온돌방을 설치했다. 가구 형식은 무고주5량가로서 판대공을 설치했고, 홑치마 지붕은 홑처마 팔작지붕이다.","a":"청주 주성강당","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660740.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○○○는 동부면과 남부면 경계지점에 있는 ○○○ 정상에 있으며, 서쪽으로는 한배곶 ○○○, 북쪽으로 계룡산 ○○○와 서로 연결되었다고 한다. ○○○가 있던 자리는 전체적으로 사각형을 이루며 현재는 주위의 석축이 양호하게 남아있다. ○○○ 아래에는 계단이 있던 흔적이 있고 그 아래에는 ○○○에 딸린 건물터가 있다.","a":"거제 가라산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655848.jpg"},{"q":"조선 효종·현종 때 실학의 선구자인 반계 유형원(1622∼1673) 선생의 유적이다. 선생은 1648년 2차례에 과거에 응시하였으나 낙방하고 효종 4년(1653)에 이곳으로 이사한 후 일생을 숨어지냈다. 선생은 뛰어난 학문으로 거듭 벼슬자리를 받았으나 모두 사퇴하고, 평생을 학문에만 힘을 쓰다가 세상을 떠났다. 이곳에서 그는 『반계수록』26권을 펴냈다. 선생의 학문은 광범위하게 영향을 미쳤는데, 선생의 주된 저서인 『반계수록』에서 농촌을 부유하게 하고 민생을 넉넉하게 하는 여러 가지 주장을 펴 정약용 등의 후기 실학자에게 큰 영향을 끼쳤다.","a":"반계선생유적지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653372.jpg"},{"q":"외딴 민가 옆에 우뚝 솟아있는 석탑으로, 현재는 절이 있었던 흔적을 찾아 볼 수 없으나, 그 옆에 석불입상이 1구 있어 상당한 규모의 절이 있었을 것으로 여겨진다. 탑은 2층 기단(基壇)위로 5층 탑신(塔身)을 올리고 머리장식을 얹은 모습이다. 기단은 각 면의 네 모서리와 가운데에 기둥모양을 새겼다. 탑신부의 몸돌은 2층에서 갑자기 높이가 낮아져 5층까지 알맞게 줄어들었으며, 지붕돌은 밑면의 받침이 1∼3층은 4단씩이다가, 4∼5층은 3단으로 줄었다. 꼭대기에는 돌의 재질이 다른 장식들이 놓여 있는데, 나중에 보충해 놓은 것으로 보인다.","a":"신룡동오층석탑","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637148.jpg"},{"q":"이 고택(古宅)은 대한제국(大韓帝國 : 1897년~1910년) 시기의 관료로서 광업·금융업·창고업 등에 종사하며 부를 축적해 재력가로도 널리 알려진 ○○○이 1906년 ○○에 건립한 집의 안채로 추정되는 건물이다. 이 건물의 건립자인 ○○○은 동 ○○ 건립 이전부터 삼개(○○동 236번지)에 거주하면서 지역 유지(有志) 또는 신사(紳士)로서 1920년대 후반까지 생존, 활동하였다.","a":"마포 최사영 가옥","c":"문화유산자료","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659312.jpg"},{"q":"서울 돈암동에 위치한 ○○○는 조선 태조 4년(1395)에 신덕왕후 강씨가 죽자 능을 정릉으로 정한 후 세운 사찰이다. 당시 이 절은 관세음보살상을 모시고 국가와 국민의 안녕을 기원하던 170여 칸 규모의 큰 사찰이었다. ○○○○○은 10겁(十劫) 이전에 성불하고 서방 극락세계에서 대중을 위하여 설법하고 있는 아미타불을 모시는 법당으로, 철종 4년(1853) 계장스님에 의해 다시 지어졌다. 앞면 3칸·옆면 3칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 지붕 처마를 받치면서 장식을 겸하는 공포가 기둥 위와 기둥 사이에도 놓인 다포양식 건물이다.","a":"흥천사 극락보전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636216.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 전라남도 지방은 전국에서 가장 많은 고인돌이 분포하고 있는 곳으로 지금까지 2만기 이상이 알려져 있다. 전라남도 장흥군에서도 210여 군데 2250여 기가 확인되었는데, 이 중에서도 가장 대표적인 것이 ○○○ 고인돌이다.","a":"장흥방촌리지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654296.jpg"},{"q":"남평초등학교 내에 놓여 있는 8각 석등으로, 등불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 3단의 받침을 두고 위로는 지붕돌과 머리장식을 얹어 마무리하였다. 받침부분은 아래받침돌에 연꽃을 둘러 새긴 후 그 위로 8각의 가운데기둥을 세우고, 역시 연꽃무늬를 둔 윗받침돌을 올렸는데 많이 닳아서인지 꽃잎의 형태가 거의 드러나지 않는다. 화사석은 4개의 작은 기둥을 네 모서리에 세워서 그 안에 불을 밝히도록 하였다. 지붕돌은 윗면이 거의 수평을 이루는데, 여덟 모서리의 선이 뚜렷하고 처마도 가벼운 곡선을 그리고 있다.","a":"동사리석등","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662032.jpg"},{"q":"조선 광해군 8년(1616)에 세운 ○○○의 정문이다. 그러나 일제가 경성중학교를 건립하고자 궁내의 많은 전각을 헐면서 그 기능을 상실했다. 그 후 일제는 1932년 남산 자락에 이등박문(伊藤博文)을 위한 사당인 박문사(博文寺)를 건립할 때 정문으로 사용하였다. 해방후 박문사는 폐사되고 ○○○은 영빈관(迎賓館) 및 신라 호텔의 정문으로 사용되기도 했다. 1988년 서울시는 ○○○ 복원 계획의 일환으로 ○○○을 지금의 자리로 이전(移轉) 복원하였다. 그러나 원 자리는 동향을 보고 배치했다고 하나, 그 위치는 현재 찾기 힘들다.","a":"경희궁 흥화문","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636097.jpg"},{"q":"○○○○은 현재 3종이 알려져 있는데 모두 ○○○○의 원본은 아니다. ○○○○은 1617년에 작성된 이후 1712년까지 주기적으로 새로운 인물들이 향안에 들어오면서 향안이 새로 작성되었으며 그것은 별도로 책자로 만들어져 보관되었다. 이 ○○○○은 조선 인조 12년(1634)에 작성된 것으로, 앞서 소개된 향안에는 포함되어 있지 않은 것이다. 소장자인 강태중씨의 조상인 강지특(姜智特)의 이름이 가장 앞에 있고, 10개조의 규약과 강지특의 발문이 실려 있다. 가로 31㎝·세로 43.3㎝ 크기의 한지로 되어 있으며, 모두 8장인데 한 책으로 되어 있다.","a":"진주향안","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664793.jpg"},{"q":"전북특별자치도 익산시 금마면 서고도리의 해발 87m의 굿대숲 위에 흙으로 쌓은 성으로, 이 봉우리는 북쪽으로 미륵산, 서쪽으로 오금산, 동쪽으로 금마산이 둘러 있다. 성벽은 내부에 토루를 쌓고 바깥 둘레에 도랑을 설치하였다. 성의 주위는 330m로서 원형에 가까운 평면인데 남쪽 성벽 중앙부는 돌출되어 있어 이 자리에는 남문이 있었을 것으로 추정되나, 지금은 이곳에 무덤이 있어 원형을 알아 볼 수 없다. 성을 쌓은 시기는 정확히 알 수 없으나 성 안에서 ‘금마저(金馬渚)’라 쓰인 기와와 백제의 기와, 토기류가 출토되어 백제 때 쌓은 성으로 추정된다.","a":"금마도토성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653562.jpg"},{"q":"마을 입구에 있는 ○○○○는 조선 중종(재위 1506∼1544) 때부터 선조(재위 1567∼1608) 때까지 이 마을에서 태어난 8인의 선비들이 학문을 닦고 후진 양성에 힘쓴 곳이다. 규모는 앞면 5칸·옆면 2칸으로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○○ 북쪽에 있는 보산사는 8인의 문관들을 모시는 사당이다. 앞면 3칸·옆면 1칸이며 지붕은 옆에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 정조 22년(1789)에 지었다고 하는데 지금 있는 건물은 1900년대에 다시 지은 것이다.","a":"보산정사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662080.jpg"},{"q":"추만 이영기(秋巒 李榮基, 1583 ~ 1661)의 學德을 길이 追慕하기 위하여 後孫인 호산 이장(毫山 李獎, 1696 ~ 1737, 禮曹郞, 兵曹佐郞, 全光道都事, 湖南試士)이 建立하였으며, 高宗 23년(1886)에 重修한 바 있다.","a":"영모당","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663476.jpg"},{"q":"○○○ 진촌마을 앞산인 고려산 서쪽 능선 상에 북방식 고인돌무덤 9기가 일렬로 분포되어 있다. 어떤 고인돌무덤은 덮개돌 위에 작은 구멍이 여러 개 패여 있는데 이러한 모양을 남한에서는 성혈이라고 하고 북한에서는 별자리와 연관 짓고 있다. 작은 구멍이 고인돌무덤의 크기는 굄돌을 높이 2.80m, 너비 0.90m, 두께 0.38m이다. 고인돌무덤 가까이에는 돌을 떼낸 흔적이 남아 있는 채석장이 있다.","a":"강화 삼거리 고인돌군","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645662.jpg"},{"q":"사찰의 창건에 대한 문헌자료는 전혀 알 수 없으나 ○○○ 창건 주지의 생모인 청송심씨 묘연화가 3대 독자인 아들의 무병장수를 기원하는 산신기도 중 산신의 현몽으로 삼존불상(三尊佛像)을 발견하였고 이를 계기로 불당을 짓고 절을 세웠다고 전한다. 백제시대에 제작된 것으로 보이는 이 석불은 부채꼴의 거대한 한 장의 광배(光背)에 부조기법으로 새긴 삼존불상(三尊佛像)으로, 태봉산 동쪽 기슭에 파손된 채 방치되던 것을, 이곳에 ○○○를 건립하여 보존하고 있다.","a":"태봉사삼존석불","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639376.jpg"},{"q":"조선 중기의 문신이며 효자로 이름이 높았던 갈천 임훈 선생의 집이다. 중종 2년(1507)에 지었으며, 안채, 사랑채, 사당, 장판각, 대문채로 이루어져 있다. 안채 정면에 사랑채가 있고 안채 오른쪽 뒷편에 사당이 자리잡고 있다. 안채는 방·대청·방·부엌으로 되어 있으며, 사랑채는 대청과 방 2칸으로 이루어졌다. 대문채는 방·대문·헛간으로 구성되었는데 사랑채의 앞면에 자리잡고 있다.","a":"거창갈계리임씨고가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659046.jpg"},{"q":"이 동종은 옛부터 ○○○에서 조석으로 타종해온 것으로 전하며, 고봉절정 암자에서 들려오는 이 종소리에 옛 어느 고승께서 「운암모종(雲庵暮鐘)」이라는 시를 읊었다고 한다. 총 높이 49cm 정도의 동제범종으로 천판과 종신 표면이 일부 매끄럽지 못하고 다듬은 흔적이 역력하나, 파손된 부분은 잘 보수되어 있어 그 본래의 형태를 잘 유지하고 있다.","a":"남해망운암건륭을사명동종","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665026.jpg"},{"q":"○○○ 지장시왕도의 금어(金魚)로 참여한 의민(義旻)이 약 35년 후에 그린 작품으로 서울･경기 지역의 일반적인 ○○○에 비하여 작품의 구성이 자유롭고 변화가 있으며, 특히 여백을 많이 살린 점이 주목된다. 인물묘사에 사실감이 엿보이고 입체감이 잘 표현되어 있는 등 19세기 후반기 서울･경기 지역 불화의 특징을 잘 보여주고 있다.","a":"사자암 현왕도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2595136.jpg"},{"q":"鐵製의 칼로 검신[劍身]과 슴베[莖]가 여러 차례의 담금질로 鍛造되었고 칼집[鞘]과 손잡이[把柄]은 오동나무이다. 劍身의 단면은 이등변삼각형으로 한 면은 평면이고 반대쪽 면은 山形이다. 칼날 끝[鋒]에서 손잡이 쪽으로 7.7cm 지점의 山형면에 V자형 갈고리가 부착되었다고 하나 현재 부식과 연마 시 부주의로 멸실되었다. 다만 그 잔흔은 있어 융기된 부분이 남아 있다. 수장자의 전언에 따르면 6.25 한국전쟁 시 땅속에 묻어두어 물에 잠기어 劒身과 슴베에 부식이 있었다는데 대체로 일치된다.","a":"합천 마씨종택 철검","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666412.jpg"},{"q":"조선 중기 문신 농암 이현보(1467∼1555)의 종가 별당이다. 영천 이씨 소윤 이헌공이 지었는데, 훗날 이현보의 아들 이문량이 낡은 건물을 다시 고쳐 지었다. ‘○○○’은 서경(書經)에서 따 온 귀절로, 조상의 업적을 길이 이어 받으라는 뜻이며 현판은 영천자 신잠(1491∼1554)이 썼다. 지금 있는 건물은 안동댐 건설로 1975년 옮긴 것이다. 앞면 3칸·옆면 2칸반 규모의 ㄴ자형 건물이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. ○○○은 작은 규모로 건물 꾸밈새가 소박하나 앞면에 넓은 마루가 있어 여유와 운치가 느껴지는 조선 중기 이후 건물이다.","a":"긍구당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640287.jpg"},{"q":"현재 무량수전에 걸려 있는 이 청동○○는 직경 85.5～85.8cm 크기의 대형이다. 측면에 반원형의 고리 두 개가 붙어 있어 원래는 양쪽 고리로 고정시켰음을 알 수 있다. 전면 중앙에는 돋을새김의 태극원문 당좌가 있다. 당좌의 좌우에는 다섯 개의 도드라진 방형틀이 있으며, 그 안에 양각으로 願文을 새겼다.","a":"양산 통도사 극락암 반자","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665667.jpg"},{"q":"○○○는 영광 불갑사, 영암 도갑사와 함께 남도의 3갑사라 불린다. 통일신라 때 의상대사가 세웠다고 전하지만 지은 시기를 확실하게 알 수 없다. 다만 1908년 새로 고쳐 세워 오늘에 이른다. 절의 자리도 세 차례 옮겼는데 그에 따라 이름도 강산사 , 당산사 , ○○○로 바뀌었다. 절 경내에는 법당인 무량전과 요사채가 있다. 무량전은 앞면 3칸·옆면 1칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 보관하고 있는 문화유산으로 고종 16년(1897)에 만든 탱화 1점이 있다.","a":"원갑사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662021.jpg"},{"q":"○○○란 왕이나 고관 등의 평생업적을 기록하여 그의 묘 남동쪽에 세우는 비로, 이 비는 조선 전기의 문신인 이증 선생의 행적을 기리고 있다. 이증은 본관이 고성으로, 조선 성종 때에는 영산현감을 맡았으며, 이후 벼슬이 이조참판에까지 이르렀다. 비는 아래에 받침돌을 두고 비몸을 세운 뒤 그 위로 머릿돌을 얹어 놓은 모습이다. 순조 18년(1818)에 세운 것으로, 한치응 선생이 비문을 짓고, 이가순 선생이 글씨를 썼다. 원래 다른 곳에 세웠던 것을, 안동댐 건설로 수몰될 위기에 처하게 되어 수다재(水多齋) 입구인 이곳에 옮겨 놓은 것이다.","a":"고성이씨신도비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640264.jpg"},{"q":"표면에 목리가 뚜렷하고, 일부 균열이 있으나 보존상태는 양호한 편이다. 통나무 가운데를 파서 만든 구유형태의 紙槽로 양끝에는 각각 37cm, 47cm의 턱받이가 마련되어 있으며, 그 중 한곳은 턱받이 밑에 부착된 세로부재에 직경 7.5cm의 원공이 관통되어 있다. 용기 내부의 중앙 바닥에는 배수를 위한 직경 5.5cm의 원공이 뚫려 있다.","a":"남해용문사목조","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642582.jpg"},{"q":"○○읍 ○○○ 냇가에 방치된 것을 이곳으로 옮겨 놓았는데, 불상 주위 약 300m 지점에 망가사라는 절이 있었다는 것으로 미루어 보아 이 절의 유물로 추정된다. 광배(光背)와 대좌(臺座)를 모두 갖춘 이 불상은 현재 두 손이 떨어져 나갔고, 가슴 아래는 시멘트로 보수하였다. 민머리 위에는 상투 모양의 머리묶음이 낮게 나타나 있으며, 원만한 얼굴에서는 다소 토속적인 표정이 엿보인다. 두 귀는 길고 굵은 목에는 3개의 주름이 뚜렷하며, 두 어깨는 얼굴에 비하여 빈약한 편이다.","a":"함양 이은리 석불","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641396.jpg"},{"q":"일월산 기슭에 자리잡은 이 집은 조선 중기의 문신 회곡 권춘란(1539∼1617)이 노년에 살던 곳이다. 권춘란은 아들이 없어 동생 춘계의 맏아들을 양자로 삼았는데, 이 집은 권춘계가 임진왜란 이전에 지은 것으로 추정되고 있다. 정침과 사당이 남아 있으며, 사당은 원래 정침의 오른쪽 뒤에 있던 것을 영조 14년(1738)에 지금의 위치로 옮겨 지었다. 정침은 앞면 5칸·옆면 5칸의 ㅁ자형이며, 처음 지을 당시의 흔적이 부분적으로 남아있다. 사당 안에는『회곡선생문집』과 교지·호패·공신록·행장기 등이 보관되어 있다.","a":"회곡고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658770.jpg"},{"q":"안흥사에 소속된 암자에서 건립한 탑으로 추정된다. 무너진 채로 방치되어 있던 것을 1972년 8월 6일에 현재의 자리로 옮겨 복원했다. 이 석탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 하층기단은 4매의 석재로 구성되었는데, 갑석만 지면에 노출되어 있고 나머지 부재는 훼손됐다. 하층기단 갑석 상면에는 2단의 괴임을 두었다. 상층기단 면석은 4매의 판석을 이용해 구성하고, 모서리에 우주를 모각했다. 탑신부는 1층을 제외한 2·3층 부재는 탑을 옮길 때 새로이 보강한 것으로, 모서리에 기둥 모양의 우주를 모각했다.","a":"이천중리삼층석탑","c":"시도유형문화유산","nc":"","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637536.jpg"},{"q":"노사 기정진을 중심으로 이최선·기우만·조의곤·김록휴·조성가·정재규 등의 위패를 모신 서원이다. 기정진(1798∼1879)은 조선 후기 성리학의 대가이다. 순조 31년(1831) 과거에 급제한 후 많은 관직에 임명되었으나 모두 사퇴하고 이곳에서 학문 연구와 후학양성에 힘썼다. 이 서원은 기정진이 조선 고종 15년(1878)에 담대헌이라고 이름짓고 학문을 가르치던 곳이다. 1924년에 후손들이 다시 지었으며, 1927년 ‘○○○○’ 이라고 쓴 현판을 걸어 오늘에 이르고 있다.","a":"장성 고산서원","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2022101411032700.JPG"},{"q":"9세기 중엽에 철감선사가 창건한 ○○○에 범자7층석탑과 나란히 서 있는 이 석상은 본래 담양군 남면 정곡리 서봉사터에 있던 것을 고(故) 현준호씨가 사재를 들여 이곳으로 옮겨온 것으로 기록되어 있다. 전체 높이 2.05m의 이 석불입상은 머리에 높은 원통형의 보관을 쓰고 있으며, 얼굴은 타원형으로 갸름하여 우아한 기품을 나타내고 있다. 목에 목걸이를 새겨 장식했으며, 옷은 왼쪽 어깨를 감싸 자연스럽게 흘러내리고 있다. 손은 왼손을 굽혀서 왼쪽 가슴에 올려놓았고, 오른손은 편 채로 내려뜨려 오른쪽 대퇴부 바깥쪽으로 붙이고 있다.","a":"증심사석조보살입상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637151.jpg"},{"q":"경남 ○○시 수곡면 원계리에 있는 진뱀이유지는 선조 25년(1592) 임진왜란 때 충무공 이순신 장군이 군사를 훈련시키던 곳이다. 장군이 두번째로 삼도수군통제사 임명장을 받은 후 군사들을 훈련시켰다고 전하며, 마을 사람들은 이곳을 ‘진뱀이’라고 부르고 있다. 1975년 장군의 호국정신과 얼을 되살리기 위해 높이 4m, 너비 1.1m의 유적비를 세워 보존하고 있다.","a":"진주 이충무공 진배미유적지","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654777.jpg"},{"q":"이 범종은 실상사 ○○○에 봉안되어 있으며 1743년에 조성되었다. 전체높이는 64cm, 직경 42cm 로 그리 크지 않은 규모로서 전체적으로 보존상태는 매우 양호한 편이다. 종 윗부분에는 천판이 둥글게 솟아있으며, 천판에는 1마리의 용이 네 발을 천판 위에 굳게 디디고 S자형으로 몸을 휜 채 고개를 쳐들고 꼬리로는 힘차게 음통을 휘감고 정면을 향해 응시하는 모습이 조각되어 있다. 음통은 표면에 아무런 문양도 없는 단순한 형태이다. 종신(鐘身)의 형태는 천판이 불룩하게 솟아있고 종신의 중간 부분 이하가 거의 직선으로 처리되어 아담하면서도 균형있는 모습을 보여준다.","a":"백장암소장범종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639798.jpg"},{"q":"탑의 기단부(基壇部)는 일부만 남아있어 원래의 구조를 알 수 없고, 현재의 기단은 새로운 돌을 끼워 만들어 놓은 것이다. 탑신부(塔身部)는 몸돌과 지붕돌을 각각 다른 돌로 만들었는데, 지붕돌은 낙수면이 밑면의 받침부분보다 훨씬 두껍고, 급한 경사가 흐른다. 1층 지붕돌은 밑면에 4단의 받침을 두었고 네 귀퉁이에 방울을 달았던 구멍이 보이는데, 2·3층 지붕돌은 많이 닳아서 인지 원래의 모습을 찾아보기 어렵다. 꼭대기에는 노반(露盤:머리장식 받침), 복발(覆鉢:엎어놓은 그릇모양의 장식)이 있고, 보륜은 한 개가 남아 머리장식을 하고 있다.","a":"강릉산계리석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660407.jpg"},{"q":"조선 중기 문신인 ○○○ 김정원(1655∼1735) 선생을 기리기 위해 지은 건물이다. 선생은 효성이 지극하고 학문과 덕행이 뛰어났던 분으로 그의 후손인 김탁연이 그를 추모하며 세웠고 후손들의 학문을 지도하는 공간으로도 사용되었다. 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다.","a":"청간당","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662692.jpg"},{"q":"신재 주세붕의 방손(직계에서 갈라져 나온 계통의 자손)인 ○○○의 글을 모아 1908년 그 후손이 간행한 책인 『○○○○』을 새긴 ○○이다. ○○○은 조선 중기의 학자이자 의병장이다. 어려서부터 학문에 뛰어난 재능을 보였으며, 1728년 이인좌, 정희량의 난이 터지자 의병을 일으켜 공을 세우기도 했다. 그 후 고향에 돌아와 학문연구와 후진을 기르는데 노력하였다. 그가 죽은 후 1788년 기양서원에 그의 위패가 모셔졌다. 이 책판의 내용은 원집의 시서(詩書), 논문 등을 새겼고, 부록의 창의사적에 관한 문헌과 가문의 의례지침인 『거가요범』 등이 있다.","a":"주재성 국담문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642029.jpg"},{"q":"이 정자는 조선시대에 한량들이 활쏘기 연습을 위해 활터에 세운 것이다. ○○○은 숙종 38년(1712)에 다가천 서쪽 냇가에 세웠으나 얼마 후 홍수로 떠내려 가버렸다. 그 뒤 경종 2년(1722)에 다가산 밑에 다가정(多佳亭)이란 정자를 짓고 활터로 사용했다. 순조 30년(1830)에는 이곳에 또 다른 정자를 세우고 옛 이름을 따서 ○○○이라 했다. 이후 북향인 다가정은 젊은 한량들 전용으로, 아늑한 골짜기에 남향으로 자리잡은 ○○○은 주로 노인층이 사용하게 되었다. 다가정․○○○의 활쏘기 모임은 군자정의 모임과 함께, 일제식민지 때 강압에 의해 하나로 통폐합되었다.","a":"천양정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661612.jpg"},{"q":"신라 문무왕 16년(676)에 낙산사를 지은 ○○○사를 기념하기 위해 1925년에 만든 정자이다. 원래 이곳은 의상이 낙산사를 지을 당시 머무르면서 참선하였던 곳으로 옛부터 ○○○라 불렸다고 한다. 6각으로 만들어진 아담한 크기의 ○○○는 낙산사에서 홍련암의 관음굴로 가는 길 해안 언덕에 있어 좋은 전망대 역할을 하고 있다. 난간을 비스듬하게 세운 것은 하나의 특징이라 할 수 있겠다.","a":"의상대","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637977.jpg"},{"q":"목판본으로 된 5침 선장본이다. 표지 서명은 『법어(法語)』로 되어 있으나, 원책명은『몽산화상법어약록』이다. 이 책은 부처님의 말씀이나 가르침을 적어놓은 것으로, 승려들의 수행서이다. 원(元)의 고승(高僧) 몽산(蒙山) 덕이(德異)의 법어를 고려때 보제존자(普齊尊者)가 초록(抄錄)하고 혜각존자(慧覺尊者)가 12결(訣)로 한역하였다.","a":"불설수생경·불설예수십왕생칠경(합부)","c":"시도유형문화유산","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643209.JPG"},{"q":"○○○에 놓여 있는 ○○으로, 보광사의 옛 터에 있던 것을 일본인이 소장하고 있다가 1928년 5월 이곳으로 옮겨놓았다. 아래에서부터 작은 규모의 아래받침돌·길쭉한 8각의 가운데기둥·윗받침돌을 차례로 올린 후 불을 밝혀두는 사각의 화사석(火舍石)과 지붕돌을 얹었다. 화사석에는 불빛이 퍼져 나오도록 네 개의 창을 두었고, 지붕돌은 윗면의 네모서리와 그 사이마다 돌출된 조각을 새겨 아름답게 장식하였다. 지붕돌 꼭대기에는 둥근 머리장식이 큼직하게 솟아 있는데, 그 표면에 구름무늬와 같은 조각을 도드라지게 새겼다.","a":"창녕 관음사 석등","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663828.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 7년(1407)에 정해현(貞海縣)과 여미현(如美縣)이 해미현(海美縣)으로 합쳐지면서 세웠다. 그 뒤 조선 헌종 10년(1844)에 고쳐 지었고, 1924년에 보수를 하였다. 제사를 지내는 공간인 대성전 안쪽에는 공자를 비롯한 중국 유학자 9명과 우리나라 성현 18명 등 27명의 위패를 모시고 있다.","a":"해미향교","c":"시도기념물","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652910.jpg"},{"q":"○○○는 매향의식(향나무를 묻는 의식으로, 이를 매개로 소원을 비는 이와 후에 태어날 미륵이 연결되기를 바라는 미륵신앙의 한 형태)을 하면서 행사의 동기와 장소, 시기 및 관련집단 등을 기록한 것이다. 이 비는 만대산 북서쪽에 있는 일명 ‘장군바위’를 이용하였는데, 바위틈 사이의 경사진 공간에 글을 새겨 글씨의 상태는 좋은 편이다. 비문 중에 향도(香徒) 58명과 마을 주민 백명이 함께 모여 매향을 행하였다는 내용이 담겨 있어 눈길을 끈다. 비문 내용으로 보아 조선 태종 6년(1406)에 매향의식을 치른 후 비문을 새긴 것으로 보인다.","a":"해남맹진리암각매향비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654298.jpg"},{"q":"이동표 선생의 둘째 아들 이제겸(1683∼1742)의 묘를 보호하기 위해서 조선 순조 25년(1825)에 증손자인 이한정을 중심으로 친척들이 세운 재실이다. 이곳에서 제사와 집안일을 논의하였으며, 지방 사림들이 모여서 시를 짓거나 시에 대해 토론도 했다고 한다. 건물은 앞면 6칸·옆면 3칸 규모로, 지붕은 옆면이 여덟 팔(八)자로 화려한 팔작지붕이다. 부엌과 방, 누각이 ㄱ자형을 이루고 있으며, 앞쪽에 툭 튀어나온 누각의 기둥 사이 간격이 서로 다른 기발함을 보이고 있다.","a":"구가암","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640880.jpg"},{"q":"이 문은 조선후기 ○○○의 군사적 중요성을 가장 잘 보여주는 유적이다. 조선후기에 ○○○는 일본과 가까운 거리에 있었기 때문에 국방과 외교상 중요한 곳이었다. 때문에 다른 고을에 비해 관아의 수도 많았고, 규모도 컸다. 이 문의 첫 건립은 1636년(인조 14) ○○○사 정양필(鄭良弼)이 ○○○○○을 건립할 때 함께 건립하였을 것으로 추정된다. 그 후 여러 차례 중건을 거쳤으며, 현재의 건물은 1870년(고종 7) ○○○사 정현덕(鄭顯德)이 중건한 것이다.","a":"동래부 동헌 외대문","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2666142.jpg"},{"q":"○○○는 대곡리 망운산 기슭에 자리잡고 있는 절로 신라 신문왕 때 원효대사가 세워 연죽사라 부른 절이다. 이후, 인조 14년(1636) 지금 있는 자리로 옮겨 넓혀 짓고 ○○○라 불렀다. ○○○는 일주문을 통해 경내로 들어서기 전 대웅전과 마주보고 있는 건물로서, 인조 16년(1638) 계원대사가 지었다. 임진왜란 때 왜군의 침략으로 절이 불타 버리자 신도들의 정성으로 곧 다시 지어 오늘에 이르고 있다. 규모는 앞면 5칸·옆면 2칸으로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다.","a":"남해 화방사 채진루","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664196.jpg"},{"q":"○○○○○ 이초(李岧, 1530~1559)는 중종(中宗)의 왕자이다. 1567년에 명종(明宗)이 후사 없이 사망하였는데, 이초의 셋째 아들 하성군(河城君) 이균(李均)이 즉위하여 선조가 되면서, 1570년에 ○○○○○에 추숭되었다. ○○○○○ 묘는 수락산(水落山) 남쪽에 위치하고 있으며, ○○○○○과 하동부대부인(河東府大夫人) 하동정씨와 쌍분(雙墳)으로 조성되었다. 봉분은 장대석(長大石)을 이용해 8각형 호석(護石)을 둘렀으며, 두 봉분 사이에 묘표(墓表)가 건립되어 있다.","a":"덕흥대원군묘","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646108.jpg"},{"q":"조선 철종대 왕족인 이하전의 살림집이었던 건물로 ○○○으로 유명하다. 원래는 많은 부속건물이 있었을 것으로 추정되나 현재 사랑채에 해당하는 건물만 남아 있다. 지금 있는 건물은 사직동에서 1979년 건국대학교로 옮긴 것이다. 사랑채 건물이긴 하지만 기능과 합리를 고려하여 안채, 사랑채 구실을 연결시키고 있으며 공간을 적절히 나누고 있는 것이 특징이다. 또한 모든 방의 앞 툇마루를 통하게 하여 합리적인 구성을 강조하고 있다. 창호 장식들은 다소 외래문화의 영향을 받고 있지만 조선 후기 한옥 발전의 바람직한 측면이 보인다는 점에서 주목받고 있는 건축물이다.","a":"도정궁경원당","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"광진구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658044.jpg"},{"q":"고려의 문신이자 문장가인 백운거사(白雲居士) ○○○선생의 묘소이다. 고려의 무신정권 하에서 태어나 무신정권에 적극 협력했던 문인의 한 사람으로, 1189년 진사시에 합격한 후 여러 관직을 거쳐 문하시랑 평장사에 올랐다. 시문에 능하였던 선생은 중국의 모방이 많았던 당시에 고구려의 시조 동명성왕 이야기를 서사시로 엮는 등 민족정신에 바탕을 두고 글을 썼다. 또한 몽고군의 침입으로 강화도로 천도해서 대장경을 만들 때 민족수호의 충정이 담긴 『대장경각판군신기고문(大藏經刻板君臣祈告文)』을 지었다.","a":"이규보 묘","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645569.jpg"},{"q":"여말선초에 조성된 것으로 추정되는 ○○○○○상으로 복장유물이 없고 개금이 두껍게 되어 원래 모습을 알아보기 어려울 뿐만 아니라 왼쪽 팔이 부자연스럽고 손가락 굵기가 서로 다른 점 등 부분적으로 보수가 이루어 졌으나, 강원특별자치도에서는 매우 휘귀한 조선전기의 윤왕좌 목조보살상이라는 점에서 지정 보존 가치가 있다.","a":"강릉관음사소장목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638300.jpg"},{"q":"우암 ○○○의 ○○으로 현재 선산곽씨 종중에서 보관하고 있다. 숙종 정축년(1697)에 영당을 세우고 서당을 齋舍로 하였다는 崇禎五癸未年(1943)에 宋近洙가 쓴 <龍門書堂禊座目>의 기록과 庚申年(1920?)에 龍門書堂을 중수하고 쓴 郭守煥의 <龍門書堂重修記>에 원래의 서당 동쪽에 祠宇를 건립하여 眞像을 봉안하고 서당을 齋室로 하였다는 기록으로 보아 1697년경에 제작된 ○○이 있었음이 분명하나 원래의 ○○인지는 알 수 없다.","a":"송시열 초상","c":"문화유산자료","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660829.jpg"},{"q":"○○○은 소계 최강(蘇溪 崔堈)의 공적을 기리기 위해 후손들이 세운 정자이다. 정자를 세운 터는 최강이 어릴 때 무술을 연마한 곳이다. 최강은 1585년(선조 18) 무과에 급제한 뒤 1592년 임진왜란이 일어나자, 형 소호 최균(蘇湖 崔均)과 함께 의병을 일으켜 ○○, 진해 사이에서 많은 공을 세웠으며 임진왜란 후에는 경상도좌수사, 충청도수군절도사를 역임했다. 그 공으로 의숙이라는 시호를 받았다. ○○○은 구릉의 서북쪽 비탈면에 남족을 향해 있다. ○○○은 정면 4칸, 측면 1.5칸의 규모이다.","a":"고성 소천정","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664213.jpg"},{"q":"조선 중종(재위 1506∼1544) 때 기묘사화로 희생된 안처순을 중심으로 정환·정황·이대병 등의 위패를 모신 서원이다. 안처순은 조선 중기 문신으로 지방학교를 발전시키고자 노력한 사람이다. ○○○○은 광해군 11년(1619)에 세웠으며, 숙종 12년(1686)에 나라에서 현판을 내려 사액서원이 되었다. 고종 5년(1868)에 철거되었다가 광복 후에 후손들이 다시 세워 오늘에 이르고 있다. 사당은 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"영천서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661635.jpg"},{"q":"이 건물은 영양 남씨 청송 입향조 운강공 남계조雲岡公 南繼曺 선생의 현손玄孫 5형제인 자훈自熏, 응훈應熏, 유훈有熏, 필훈必熏, 시훈是熏의 뛰어난 효행과 우애를 추모하기 위하여 자훈의 손자 남도성南道聖이 여러 종인宗人들과 의논하여 1774년 무렵에 건립한 정자로 알려져 있다. 오체정의 ‘오체五棣’는 시경詩經 체화시棣華詩에 나오는 말인데 여기서는 5형제인 자훈, 응훈, 유훈, 필훈, 시훈을 뜻한다. 이 건물은 정자 1동과 관리사 1동으로 구성되어 있으며, 전체적으로 □자 형태이다","a":"청송오체정","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663424.jpg"},{"q":"○○○○○은 면천면 ○○○와 삼웅리의 경계지점인 해발 119m의 산정상부를 중심으로 하여 성내부의 경사면을 삭토한 흙으로 성벽을 축조한 산정식(山頂式)의 테뫼식 산성이다. 규모는 성주위 약 400m이며 성벽높이 외벽 약 4~5m, 내벽 약 1~1.5m이고 성벽 기저부는 1~2m이다. 축조년대는 정확히 알 수 없으나 면천관내에서는 가장 고식의 산성이며 마한 또는 백제시대의 치소(治所)였을 가능성이 매우 크고 당진군 행정·군사적 중심지였던 면천지역의 역사성을 밝힐 수 있는 자료이므로 가치가 크다.","a":"당진성상리산성","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653155.jpg"},{"q":"○○○○는 석가여래부처 당시에 부처의 이모였던 마가파도파제 부인이 부처께 금색의(金色衣) 또는 ○○○○를 한 벌 지어 올린데서 유래한 것이다. 이 때부터 ○○○○ 또는 금색의는 국가적인 차원에서 열리는 큰 행사에서 당대 최고의 고승인 증명법사(證明法師) 한 사람만 입는 법의였다. ○○○ 창건주인 고 철우선사(鐵牛禪師)의 ○○○○는 철우선사의 스승인 혜월선사(慧月禪師)에게서, 또 혜월선사의 스승이며 당대 고승인 경허선사(鏡虛禪師)에게서 전수된 것으로 여겨진다.","a":"구미금강사금란가사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658896.jpg"},{"q":"○○○는 신라 문무왕 16년(676)에 의상대사가 세운 절이다. 이후 여러 차례 재난을 당하여 무너진 것을 고려 명종 14년(1184) 보조국사 지눌이 ○○○을 비롯하여 7동의 건물을 복원하였으나, 임진왜란 때 화재로 소실되고 ○○○과 반학루, 삼층석탑만 남아 있다. ○○○은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포의 앞쪽 기둥은 기둥 위에만 있는 주심포 양식으로 되어 있고, 뒤쪽 기둥은 새 날개 모양으로 장식한 익공 양식을 섞어 놓았다.","a":"보문사극락전","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662825.jpg"},{"q":"지리산 남쪽 기슭에 위치한 ○○○는 통일신라 경덕왕(재위 742∼765) 때 승려 연기가 처음 지은 절이다. 그 후 신라말 도선에 의해 크게 확장되었으나, 임진왜란(1592) 때 불타 없어졌다. 조선 인조 8년(1630)에 승려 각성이 다시 짓기 시작하여 7년 만인 인조 14년(1636)에 대웅전을 비롯한 약간의 건물을 완성하였고, 그 다음해 선종대가람으로 승격되었다. 현재의 건물들은 각성이 다시 지은 17세기 이후의 것이다. ○○○○○는 법요식 때 승려나 불교신도들의 집회를 목적으로 지어진 강당건물이다.","a":"화엄사보제루","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639884.jpg"},{"q":"덕유산 남쪽 기슭에 있는 원통사의 옛 터이다. 원통사중창비문에 의하면 원통사는 신라 때 지어진 사찰로, 절이 지어졌을 당시의 규모에 대하여 정확히는 알 수 없으나, 법당, 종각, 누각 등의 건물이 있었던 것으로 기록되어 있다. 조선 숙종 24년(1698) 탄언, 도영, 혜옥선사들이 당과 종각을 고쳐 짓고, 동종을 만들었으며, 불상을 보수하였으나, 1949년 여순사건으로 모두 불타버렸다.","a":"원통사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653550.jpg"},{"q":"○○○의 명부전에 모셔져 있는 본존인 지장보살을 중심으로 하여 왼쪽에 도명존자와 오른쪽에 무독귀왕, 그리고 그 좌우에 시왕상 등 모두 12구의 불상들이다. 지장보살상은 등을 세우고 얼굴을 약간 내민 상태의 가부좌 모습으로, 양손은 따로 만들어 끼웠으며 제1지와 제3지를 구부려 맞대고 있다. 얼굴은 네모 반듯한 모양으로 가늘고 긴 눈, 우뚝 솟은 콧등이 특징적이다. 짧은 목에는 세 개의 주름인 삼도(三道)를 얇게 나타내었다. 법의는 가장 바깥에 대의를 걸쳤는데 오른쪽 어깨를 가린 반단형식이며, 다시 대의 아래에 편삼을 입었다.","a":"함양 용추사 지장시왕상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642364.jpg"},{"q":"1691년(숙종 17) 숙종은 70세 이상의 노모를 모신 신하들에게 쌀과 비단을 내려주고, 이를 기념하는 연회를 열었다. 이 연회에는 노모를 모신 신하들 가운데 일곱 명이 참여하였다. 따라서 그 일곱 집의 대부인(大夫人)과 며느리, 손자며느리 및 사대부들이 초청되었다. 그 연회의 장면을 그림으로 재구성하여 그린 것이 이 ‘○○○○○’이다. 이 그림이 경기도유형문화유산으로 지정될 때 소장처가 여주시 강천면으로 되어 있어서 명칭을 ‘○○○○○’라고 했다.","a":"여주군경수연도","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637638.jpg"},{"q":"○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑으로, 부정과 악의 출입을 막아 마을을 편안하게 하고자 하는 신앙 대상물이다. ○○○ 주거지역 서쪽에는 4기의 ○○○이 남북으로 놓여 있는데, ‘앞논’이라 부르는 이곳의 허한 기운을 보강하여 부정과 액운을 막기 위해 쌓아놓은 것이라 한다. 이 탑은 남쪽 맨 왼측에 있는 것으로, 비교적 원상태로 유지되어 있다. 꼭대기에는 사람의 형상을 한 돌을 세워 놓았는데, 얼굴·몸·모자로 구분된 남자의 모습이라 한다.","a":"무릉리방사탑1호","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659273.jpg"},{"q":"초동면 범평리 ○○○○○에서 소장하고 있는 ○○○는 고종년간에 효행을 천거하는 상서(上書) 2점과, 산송(山訟)관련 문서 9점, 그리고 호구단자(戶口單子) 46점 등 모두 57점이다. 1.효행(孝行)을 천거(薦擧)하는 상서(上書:2점) 이 상서는 진주(晉州)에 거주하는 사족(士族)들이 해당 고을에 사는 사족인 허성(許珹)이라는 사람이 자기의 모친에 대한 지극한 효성이 있기로 이를 천거(薦擧)하여 정려(旌閭)를 내려줄 것을 청하는 상서이다. 2점의 상서 중에 한 점은 고을 수령에게 올린 것이고, 다른 한 점은 암행어사(暗行御史)에게 올린 것이다.","a":"밀양 미리벌민속박물관 창녕성씨 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666597.jpg"},{"q":"조선시대 무신인 박세중(1595∼)의 영정을 모신 사당이다. 박세중은 광해군 11년(1618) 무과에 급제하고 인조반정 때 공을 세워 1등공신이 되었다. 이듬해 이괄의 난이 일어나 왕이 공주로 피신할 때 옥쇄를 안전하게 보관하여 2등공신에 녹훈되고 충주부사가 되었다. 병자호란이 일어나자 의병을 일으켜 대항했으나 임금이 강화에서 중국 청나라에 무릎을 꿇었다는 소식을 듣고 고향으로 돌아갔다. 이 건물은 숙종 12년(1685) 세우고, 고종 43년(1905) 고쳐 지었다.","a":"풍양사","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661815.jpg"},{"q":"전체 높이 2.4m, 불상 높이 1.7m에 대좌와 광배를 모두 갖추고 있고 크기가 큰 고려 시대의 석조불좌상이다. 약 20년 전의 산사태로 광배와 대좌에 손상을 입어 이를 보수하였다. 불상은 민머리에 사각형 갓/보개(寶蓋; 인도에서 귀인의 외출시에 사용하던 양산을 불상의 머리 위에 갓처럼 씌운 것)를 쓰고 있다. 이러한 보개는 통일신라시대에는 없었던 것으로, 충청도와 경기 남부의 불상에서 주로 나타나는 고려 시대의 특징이다.","a":"포초골미륵좌불","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637381.jpg"},{"q":"말 그림이 새겨져 있는 이 굽항아리는 구형 동체에 7개의 장방형 투창(透窓)이 등간격으로 배치되어 있는 대각과 돌대에 의해 3단으 로 구획된 구경으로 이루어졌다. 토기 표면 색상은 회청색이고, 동 체의 어깨 부분에 모두 5마리의 말그림(馬文)이 그려져 있다. 동체 어깨 부분의 말 그림은 머리가 오른쪽으로 향한 5마리를 등 간격으로 표현 했는데, 두 마리는 몸통에 종으로 선을 그어 표현하 였고, 나머지 3마리는 외곽 윤곽만 표현하였다. 말 그림은 소략하 나 움직임을 표현하였으며, 말의 다리는 4개가 아닌 2개로 표현하 였다.","a":"마문장경호","c":"문화유산자료","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659416.jpg"},{"q":"이 책판은 조선 후기의 문신인 단계 ○○○의 문집을 널리 알리고자 1908년에 새긴 것이다. ○○○은 17세에 진사에 합격하고, 20세에 문과에 급제하여 사간원 정언이 되었다. 32세에 벼슬을 버리고 고향으로 돌아왔다. 36세 때인 1862년에 부친이 민중봉기에 연루되어 임자도로 귀향가게 되자 같이 따라 갔다. 41세 때에는 백성을 괴롭힌다는 어사의 거짓 상소로 인해 강원도 간성으로 1년간 귀향살이를 했다. 이 책판은 그가 세상을 떠난 지 6년 후에 그의 문인들에 의해 14권 7책으로 만들어 졌다.","a":"김인섭 단계문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641851.jpg"},{"q":"이 가옥은 일제강점말기인 1941년 현 소유주 ○○○의 증조부인 변봉규(卞鳳圭)가 건립한 “ㄷ”자형의 전통목조가옥으로서 자재와가구수법이 뛰어난 살림집이다. 전통 목구조수법에 따르면서 일부에 유리 창문과 좁은 통로, 볼트 너트 접합 등과 같은 근대 건축의 세부 양식을 접목하고 있다. 특히 문경 지역의 토착 주거문화에 근대양식 일부가 수용된 주택으로 지역의 역사ㆍ문화의 변동을 살펴 볼 수 있는 흔치 않은 사례이다.","a":"문경변동식가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051421271200.jpg"},{"q":"○○○○○은 신리 문무왕 9년(669)에 원효대사 제자 봉진비구에 의해 처음 건립되고, 임진왜란으로 소실된 이후 여러 차례의 중건·중수됨. 인조(仁祖)때 벽봉(碧峰)화상이 중건하였다고 전한다. 벽봉화상은 인조19년(1641년) 강원도 영은사 팔상전을 창건하였다고 전하는데, 인법당 용마루 막새기와의 명문은 순치 4년 (인조 25년, 1647)으로 비슷한 연대로 ○○○의 중건 연대를 1647년으로 추정할 수 있다. 여러 차례의 중수에 걸쳐 현재에 이른 것으로 판단.","a":"통영 안정사 가섭암","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643084.jpg"},{"q":"○○○ 봉명산 기슭에 있는 서봉사의 옛 절터로 주춧돌과 축대가 여기저기 흩어져 있으며, 현재는 차밭으로 개간되었다. 『영봉산용암사』, 『서봉사 사적』 등의 기록에 따르면, 신라 눌지왕(417∼457)때 세웠다고 전하며 그 당시에는 봉암사라 했으나 조선시대 때 서봉사로 바뀐 듯하다. 조선 광해군 6년(1614)에 의현 스님이 다시 지었으며, 절의 규모가 대단히 컸다고 한다. 서봉사에서 인쇄된 불경을 서울대 도서관에서 소장하고 있다.","a":"사천용산리사지","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656215.jpg"},{"q":"설암 김필(1426∼1470)이 제자들을 가르치던 정자이다. 단종(재위 1452∼1455) 때 홍문관 부제학, 이조참판을 지낸 설암은 계유정란(1453) 후 벼슬을 버리고 장흥에 내려와 숨어살다가 정자를 짓고 후학들을 교육시켰다. 선생이 이곳에서 여생을 마치자 후손들은 그를 추모하기 위하여 ‘사인(舍人)’이란 벼슬이름을 따서 사인정이라 불렀다. 앞면 3칸·옆면 2칸 규모의 건물로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 가운데에 온돌방을 두고 주위를 모두 마루로 둘렀다.","a":"장흥사인정","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639895.jpg"},{"q":"현 보은산 자락에 남아 있는 ○○○○터는 성벽은 물론 성문지, 옹성, 치, 해자, 외환도, 건물지, 우물, 연못 등 다양한 시설이 대체적으로 원형상태가 잘 유지되어 있고, 수습유물 또한 삼국(백제)시대부터 조선시대에 이르기까지 고르게 분포되어 있음. ○○○○터는 삼국시대부터 있었던 성을 조선시대에 이르기까지 재축, 보축하여 치소로서의 명맥을 유지해 온 흔적으로 볼 수 있으며, 천년이상의 역사와 전통을 가진 유적으로 우리나라 성곽사의 중요한 자료가 될 것으로 판단됨.","a":"강진읍성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654389.jpg"},{"q":"○○○ 입구에 있는 3층 석탑이다. 이 암자에는 원효대사가 창건하여 머물면서 왜병을 물리쳤다는 설화가 전하고 있으며, 서쪽으로 ○○○○이 하나 더 서 있다. 원래 2층 기단(基壇) 위에 3층의 탑신(塔身)을 세우고 그 위에 머리장식을 올렸을 것으로 추정되나, 지금은 바닥돌 위에 3층의 탑신만을 올리고 있다. 탑신의 몸돌에는 기둥모양을 조각하였는데, 2층과 3층 몸돌은 돌의 재질이나 비례로 보아 후에 복원된 것으로 보인다. 두툼한 지붕돌은 네 귀퉁이가 살짝 들려 있어 곡선미가 느껴지고, 밑면에는 4단의 받침을 두었다.","a":"원효암 동편 삼층석탑","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636636.jpg"},{"q":"단성 ○○○은 제단의 위치, 제단의 축조 방식이나 제도적 규식 등을 보아 조선왕조 초기에 건립된 지방 ○○○의 형태를 나타내고 있다. 동, 서, 남 세방향은 제단의 형태가 완연히 남아있고 각각의 방향으로는 중간에 3층으로 이루어진 섬돌의 모습이 남아 있다. 조선왕조 초기에 조성될 당시의 원형을 잘 유지하고 있을 뿐만 아니라, 도내에서 거의 유일하게 남아있는 ○○○이며 봉안하고 있는 사직 신위패 2점 또한 그 유래가 오래되었다.","a":"산청단성사직단","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657277.jpg"},{"q":"○○○는 신라 지증왕 때 연기조사가 ‘영악사’라는 이름으로 세웠고, 후에 도선국사가 ‘○○○’로 바꾸어 불렀다고 한다. ○○○은 신라 선덕여왕 때 자장율사가 지은 것으로 임진왜란 때 소실된 것을 숙종 6년(1680)에 새로 지었다. 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위에만 있는 주심포 양식으로 꾸몄다. 건물 안쪽에는 아미타불을 모시고 있으며, 건물 앞면 좌우 칸의 창호와 벽체 그리고 난간 형태의 머름 등의 설치가 특이하다.","a":"사천 다솔사 극락전","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664182.jpg"},{"q":"이 불상은 소조(塑造)의 석가○○○○으로 현재 ○○○ 나한전(羅漢殿)의 본존상(本尊像)으로 봉안되어 있다. 중앙의 석가여래좌상(釋迦如來坐像)을 중심으로 두 보살상(菩薩像)이 시립(侍立)하고 있는데, 현재 복장(腹藏)이 개봉되지 않았고 개금(改金) 또한 두터워 정확한 연대를 알기어려우나 삼존불(三尊佛)의 머리표현과 얼굴 형태, 법의(法衣)의 주름 등 전체적인 양식적 특징으로 볼 때 16세기 후반～17세기 전반 경의 양식을 보여주는 작품이다. 세 불상은 모두 소조불(塑造佛)로 조성되었는데, 손 부분은 후에 나무로 만들어 새로 끼웠다.","a":"진관사 소 삼존불상(석가불,미륵보살,제화갈라보살)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636342.jpg"},{"q":"조선 중기 명장 양무공 김완(1577∼1635) 장군의 묘소이다. 광해군 7년(1615)에 과거급제하여 고산진절제사 등을 거쳐 황해도 병마절도사에 올랐고, 여러 공이 인정되어 죽은 후 병조판서로 벼슬이 높여졌다. 임진왜란 때 전라도 병마절도사 이복남 장군 아래에서 용맹을 떨쳤고, 인조 12년(1624)에는 이괄의 난을 평정하는데 큰 공을 세웠다. 묘는 원래 해남면 동북선산에 있던 것을 숙종 44년(1718)에 지금의 위치로 옮겼다.","a":"김완장군묘소및신도비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654076.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 경상남도 ○○군 영산면에 있는 성으로, 원래 흙으로 쌓은 것을 조선시대에 돌로 다시 쌓은 것으로 추정된다. 성을 쌓은 시기는 정확히 알 수 없다. 『○○읍지』에는 읍성이 둘레가 3,810척(약 1154m), 높이 12척 5촌(약 4m)으로 조선 선조(재위 1573∼1618) 때 쌓았으나 그 후 무너졌다고 기록하고 있다. 지금 남아 있는 성벽은 길이 106m, 높이 2.5m, 폭 1.5m 정도이다. 성은 거대한 돌을 이용하여 기초를 마련하고 그 위에 돌을 정교하게 쌓아올렸다.","a":"창녕 영산읍성지","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655036.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 북제주군 애월읍 광령리의 평평한 밭 한쪽에 있는 이 고인돌은 바둑판식이다. 남·북·서쪽의 세 귀퉁이에 작은 막돌을 받침돌로 세운 뒤 그 위에 덮개돌을 올려 놓았는데, 길이 2.3m, 너비 2.19m로 다소 작은 편이다.","a":"광령지석묘 6호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657679.jpg"},{"q":"조선 중기 때 명신인 동계 ○○의 문집을 새긴 ○○이다. ○○은 광해군 2년(1610) 문과에 급제하여 시강원경설서, 사간원정언 등의 벼슬을 지냈다. 영창대군이 죽임을 당하자 격렬한 반대상소를 올렸다가 광해군의 노여움을 사 제주도로 유배되었고, 그뒤 10년동안 유배지에서 학문을 닦았다. 그후 다시 벼슬길에 올라서는 대사간, 대제학, 이조참판 등 중요한 벼슬을 했으며, 병자호란 때 끝내 항복하게 되자 스스로 목숨을 끊으려 하였으나 실패하고 덕유산에 들어가 살다가 죽었다.","a":"정온 동계문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642243.jpg"},{"q":"○○○○은 조선시대 연산현(連山縣)의 관아를 출입하던 정문이다. 앞면 3칸·옆면 2칸의 2층 누각건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 아래층은 각 칸마다 문을 달아 통행로로 이용하였고, 위층은 누마루로 4면에 난간을 둘렀다. 주춧돌(礎石)이 없는 대신 돌기둥(石柱)으로 아래층 중간 부분까지 오도록 하였고 그 위에 나무기둥(木柱)을 이어댔다. 후면에는 객사터(客舍址)가 있었던 것으로 전한다. ○○○○은 지금 남아있는 조선 후기 관아건물 중 대표적인 양식의 문루이다.","a":"연산아문","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639008.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 이곳에 당이라는 깃발을 걸어둔다. 이 깃발을 꽂는 길쭉한 장대를 당간이라 하며, 당간을 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 일컫는다. 드물게 당간이 있으나 대부분 두 기둥만 남아있다. ○○○의 옛 터에 자리한 이 ○○○○는 직사각형의 돌기둥 2개가 서로 마주 보고 있다. 전체적으로 우아하고 간결하며 단아한 모습으로, ○○○○의 계보 연구에 귀중한 자료가 된다.","a":"법수사지당간지주","c":"시도유형문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640410.jpg"},{"q":"○○○ 절마당에 놓여 있는 석등으로, 이 절에서 200m 가량 떨어진 ○○○이라는 암자터에 쓰러져 있던 것을, 이 곳으로 옮겨 복원해 놓은 것이다. 등불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 4각의 바닥돌과 3단의 받침을 쌓고, 위로는 지붕돌과 머리장식을 얹었는데, 바닥돌을 제외한 각부분이 8각을 이루고 있다. 아래받침돌과 한돌로 이루어진 바닥돌은 옆면에 안상(眼象)을 2개씩 옅게 새기고, 아래받침돌은 윗면에 연꽃무늬를 둘러 새겼다. 그 위로 가운데기둥을 세워 윗받침돌을 받치도록 하였으며, 윗받침돌은 아래와 대칭되는 연꽃을 조각하여 장식하였다.","a":"부인사일명암지석등","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659479.jpg"},{"q":"서울역사박물관이 소장하고 있는 이 ○○○는 시간과 천체력(天體曆)을 살피는데 활용되는 과학유물로 알려져 있는데 우리나라에서는 처음으로 발견된 것이다. ○○○는 1680년(康熙 19년) 중국에 들어온 서양선교사들에 의해 처음 만들어졌다고 알려진다. 우리나라의 경우는 영조 때의 실학자 담헌 홍대용(湛軒 洪大容, 1731 ~1783)이 중국에 다녀온 후 1752년～1762년간에 일종의 사설(私設) 천문대로 만든 농수각(籠水閣) 내에 측관(測管)이란 의기(儀器)를 제작해 놓았다고 하는데 이것이 바로 현재 실물은 전해지지 않지만 우리나라 최초의 ○○○라고 전해진다.","a":"간평의","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590288.jpg"},{"q":"전라남도 장흥군과 강진군의 경계를 이루고 있는 해발 561m의 ○○○ 산마루를 이어 돌로 쌓아 만든 산성이다. 성벽은 직사각형으로 다듬은 돌을 이용하여 이물려쌓기(돌의 단을 조금씩 들여 넣으면서 쌓는 일)를 하였는데, 총 연장 길이 6㎞, 높이 약 5m, 너비 4m로 남문, 북문, 동문이 있다. 성의 동쪽부분은 2중으로 성벽을 쌓았는데, 이러한 방식은 백제 때 나타나는 수법으로 미루어 백제의 성으로 추정된다.","a":"장흥수인산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654154.jpg"},{"q":"○○○에 보존되어 있는 ○○○○○인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 채색하여 그린 이 탱화는, 상하로 2폭을 연결하여 조성하였다. 화면 중앙의 아미타좌상을 비롯하여 그 왼쪽에 관음보살상, 오른쪽에 대세지보살상이 앉아 있으며 위쪽으로는 보살상 2구와 아난·가섭상이 배치되어 있다. 화면의 아래쪽 부분 좌우측에 있는 기록에 의하면 이 불화는 ‘성상즉위22년병신’, 즉 1896년에 조성된 것임을 알 수 있다. 조선시대 불교회화사 연구에 중요한 학술적 자료이다.","a":"양산 통도사 성상22년명 아미타후불탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664820.jpg"},{"q":"○○○○은 기장군 기장읍 서부리, 대라리와 철마면 안평리 일원에 걸쳐 있는 수령산의 해발 약 350m 고지에 위치한다. 성벽은 산 능선을 따라 쌓았는데, 평면 부정형의 포곡식산성(抱谷式山城)으로 북쪽이 가장 높으며 서쪽으로 가면서 지형상 가장 낮은 남문지를 지나 동쪽으로 진행되다가 북쪽 정상 아래로 이어진다. 성벽은 상부가 대부분 허물어져 경사면을 따라 성벽석이 흩어져 있으며, 서북쪽과 서남쪽, 남동쪽에서 문지(門址)로 추정되는 개구부(開口部)가 확인된다.","a":"기장산성","c":"시도기념물","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645275.jpg"},{"q":"고려의 조신 선생을 제사 지내는 곳으로 고려 후기에 지은 것으로 전하고 있다. 원래는 덕림사가 있던 터였고, 사당 왼쪽에 있는 선생의 묘소는 조선 태종(재위 1400∼1418)이 무학선사에게 부탁해 잡은 터라고 전한다.","a":"덕림병사","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661386.jpg"},{"q":"이곳은 박문효(1568∼1593)의 사당이 있던 장소이다. 박문효는 중종반정의 공신인 박원종의 후손으로서, 종묘서직장이라는 관직에 있었다. 임진왜란이 일어나 선조가 의주로 피신하자 임금을 따랐으며, 다음해 서울로 돌아오다 개성 싸움에서 26세의 젊은 나이로 순절하였다. 후에 호남 유림들의 상소에 의해 순조 17년(1817)에 이조참의로 증직되었다. 조선 순조 19년(1819)에 처음 지어졌으나 고종 5년(1868) 철거되었다. 현재 서현사터에는 부인 송씨를 위해 세운 정려와 유허비가 남아있다.","a":"서현사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653487.jpg"},{"q":"이 건물은 임란 때 의병장으로 활약하였던 ○○○ 권우(權祐, 1520 ~ 1593)가 1580년경에 건립한 살림집이다. 현재의 종택(宗宅)은 1780년을 전후하여 중수(重修)한 것인데, 안 대청의 좌우에 둔 도장방이나, 사랑방 공간이 발달되지 못한 점, 도장방 상부에 있는 더그매와 대청 뒷벽의 구성 등은 건립 당시의 모습을 보여 주고 있어 주거사 연구의 좋은 자료가 되어지고 있다.","a":"예천권씨영사당종택","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663494.jpg"},{"q":"전라남도 순창의 ○○○ 대웅전에 모셔진 높이 1.04m의 불상이다. 원래는 남원의 한 사찰에 모셔져 있었는데, 담양으로 옮겨져 개인이 보관하다가 다시 ○○○로 옮겨 왔다. 얼굴과 가슴에 부분적으로 금칠이 벗겨져 있으나 전체적으로 보존 상태는 양호한 편이다. 얼굴 표정은 근엄한 편이며 귓볼이 목 중간까지 길게 늘어져 있다. 양 어깨에 걸친 두꺼운 옷에는 탄력이 줄어든 u자형 옷주름이 표현되었고, 속옷의 띠매듭은 X자를 이루고 있다. 양 손 모두 엄지와 가운데 손가락을 맞잡은 모습이다.","a":"순평사금동여래좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639644.jpg"},{"q":"조선후기 건립된 살림집으로 ‘ㄱ’자 형의 안채와 ‘-’자형의 문간채로 구성되어 있다. 안채는 7칸×2칸 규모로 홑처마 팔작지붕으로 가운데 대청마루를 두고 좌우에 방을 배치하였으며 ‘ㄱ’자로 꺾여진 끝에 부엌과 고방을 배치한 홑집구조로 충청지방의 전형적인 배치와 평면구조를 보여주고 있다","a":"아산 김효직가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658280.jpg"},{"q":"장수현감으로 재직한 ○○○ 권만두(1674∼1753)선생이 지은 건물이다. 선생은 조선 후기 문신으로 병과에 급제한 뒤 공조정랑이 되고 사관으로서 경연관을 겸했다. ○○○의 구조는 앞면 7칸·옆면 5칸의 ㅁ자형 평면을 갖춘 집이다. 현판, 교지, 장수공문집 등은 원손 태훈이 보관하고 있다.","a":"지족당","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663019.jpg"},{"q":"돌기둥 모양의 이 석불은 가슴 아래의 몸체를 먼저 만든 뒤, 그 위로 가슴부터 머리까지는 다른 돌을 얹어 조각하였으며 얼굴·손·옷주름 등을 간략히 표현하였다. 머리에는 8각의 넓은 보관(寶冠)을 쓰고 있으며, 큼직한 사각형의 얼굴은 커다란 눈, 뭉툭한 코, 두터운 입술 등의 표현으로 자비스러운 부처의 모습보다는 석장승과 같은 토속적인 수호신의 표정을 짓고 있다. 입체감 없는 신체는 왼손은 가슴에 대고 오른손은 내린 모습으로 얼어붙은 듯 경직되었다. 양 어깨를 감싸고 있는 옷은 앞면에만 주름이 표현되었는데, 가슴 아래부터는 반복적인 선으로 돋을새김했다.","a":"장성 원덕리 미륵석불","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023010915012500.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 사화랑 봉수는 경상도 동래에서 서울 목멱산(지금의 남산) 중앙봉수에 이르는 봉화선로의 중간노선을 연결하는 간봉(間烽)이다. 여기서는 동쪽 가덕도 천성 연대에서 봉수를 받아 장복산 봉수와 ○○의 여음포 봉수에 알렸다. 『웅천읍지』를 비롯한 지리지에 따르면 사화랑봉수에는 임무를 수행하는 요원으로 100명이 있었다고 한다. 전국의 봉수제도를 폐지하던 고종 31년(1894)에 없어졌다.","a":"창원 사화랑산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656350.jpg"},{"q":"이 전적은 중국 송나라 사마광이 지은 편년체통사인 ○○○○에서 송나라 주희가 춘추의 체례에 따라 주요 사실을 강(綱)으로 하고 그에 대한 주자학적인 안목의 해설을 목(目)으로 엮어 ○○○○○으로 제명한 것이다. 세종은 이 ○○○○○의 인출을 위해 필요한 방대한 용지를 중앙과 지방관서에 만들게 하는 한편, 강(綱)의 본문은 진양대군에게 큰 글자를 쓰게 하여 1436년 연(鉛)으로 주조하고 병진자(丙辰字)로 명명하였다. 그리고 목의 중간 글자와 작은 글자는 1434년에 주조한 갑인자(甲寅字)를 사용하여 1438년에 찍어 낸 것이 바로 이 책이다.","a":"자치통감강목 권23상","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637131.jpg"},{"q":"◦ ○○○은 충청남도 홍성군 갈산면 행산리 출신이며, 호는 백야로 1920년 10월 일본군 대부대가 독립군 토벌을 목적으로 만주로 출병하자 소속 독립군인 북로군정서군을 백두산으로 이동시키던 중 청산리에서 일본군과 만나 전투를 전개하여 일본군 3천여 명을 살상하는 커다란 승리를 올렸음. ◦ 이 청산리 대첩은 우리나라 무장 독립운동사에서 가장 빛나는 업적임.","a":"김좌진장군묘","c":"시도기념물","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652806.jpg"},{"q":"○○ 가경4지구 택지개발지구와 우회도로 공사구간에서 발견되어 1995년 충북대학교박물관이 발굴조사한 유적이다. 이 유적에서는 청동기시대의 생활유적과 삼국~조선시대에 이르는 광범위한 시기의 유구가 대량 확인 되었다. 특히 ○○○ 홍골~감나무실 사이의 구릉지역 일부 구간에서는 처음 나타나는 형식의 백제 목곽묘와 목관묘가 조사되었으며, 생활유구인 주거지와 매장유구인 무덤이 일정하게 구역을 정하여 가까운 간격을 두고 있었음을 확인하였다. 특히 백제시대 주거지 3기, 저장구덩 7기, 토광묘 13기와 완전한 형태의 백제토기 가마 등 다양한 백제시기 유구가 확인되었다.","a":"청주 가경동 유적","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650801.jpg"},{"q":"○○○는 우리나라 3대 사찰 중 하나로 신라 선덕여왕 15년(646)에 자장율사가 석가모니의 사리와 의복 1벌을 당나라에서 가져와 모시고 세운 절이다. 현재는 대웅전을 비롯하여 극락전, 약사전, 관음전, 응진전, ○○○ 등 총 65동의 건물이 있다. ○○○는 상노전·중노전·하노전 등 세 부분으로 구분하는데, ○○○은 중노전에 속하는 건물로 세운 시기는 알 수가 없다. 해장보각 뒤편에 있는 ○○○은 앞면 3칸 ·옆면 1칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"양산 통도사 장경각","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664173.jpg"},{"q":"밀성박씨 어변당좌 종중에서 소장중인 박기우 장군 영정외 유품과 선무원종 공신녹권(박몽룡)을 비롯한 ○○○로서 내용은 다음과 같다. 박기우장군영정(朴起羽將軍影幀) 1위(位), 장도(長刀) 1점(点), 호패(號牌)(박기우(朴起羽)·박희한(朴希漢)) 2점(点), 비녀(용잠(龍潛)) 1쌍(雙), 시(矢)잡이 2점(点), 백동연초대(白銅煙草臺) 1점(点), 교지(敎旨)(박기우(朴起羽) 무과(武科) ·병과외(兵科外)) 13매(枚), 과거답안지(科擧答案紙) 5매(枚), 상소문(上疏文) 1매(枚), 선무원종공신녹권(宣武原從功臣錄卷) 1매(枚)(1605년, 박몽룡(朴夢龍)), 사마방…","a":"밀양 박씨종중유품 및 고문서","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642293.jpg"},{"q":"이곳은 백제의 유물이 출토되는 건물터로, 왕포리와 ○○○의 경계인 구릉의 능선상에 있다. 정확한 유래는 알 수 없으나 도성 남쪽의 언덕이므로 외곽의 방어를 위한 관청이거나 절터가 있었던 자리로 추정된다. 직사각형의 평탄한 대지를 이루고 있으며, 8엽 단판연화문 와당과 서까래끝기와, 주춧돌이 발견된 바 있고 지금도 백제 기와조각과 토기조각이 많이 출토되고 있다.","a":"부여중정리백제건물지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652775.jpg"},{"q":"조선 초기의 문신인 소간(昭簡) ○○의 묘소이다. 태종의 넷째 딸 ○○○○와 결혼하여 의산군에 봉해졌으며, 세종 즉위년(1418)에 동지총제가 되고, 이듬해 판한성부사가 되었다. 1425년 평양선위사가 되어 명나라에 다녀온 후 3차례의 선위사를 역임하였다. 현재 ○○은 그와 공주의 묘가 쌍분으로 되어 있으며, 봉분 아랫부분에 둘레석이 둘러져 있다. 주위에는 묘비와 망주석 등 기타 석물들이 배치되어 있다.","a":"창녕 남휘, 정선공주 묘역","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664437.jpg"},{"q":"이 향완은 신부와 대부는 별도로 떨어지게 되어 있으며, 높이와 입지름의 길이가 비슷한 균형있고 아름다운 고려시대의 향완으로서, 뛰어난 입사기법을 사용하여 회화성도 훌륭한 편이며 구경에는 명문이 있어 향완 주조 사찰인 ○○○와 현문이라는 시주자명 등을 정확히 알 수 있다. 주된 문양인 보상화문이나 앙련과 복련문 등의 아름다운 문양과 균형잡힌 몸매 등 뛰어난 불교미술작품으로서 종교적·미술사적인 측면에서 가치가 크다.","a":"개심사명청동은입사향완","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020061014020600.JPG"},{"q":"목재의 수장이나 가구의 치목들이 적절하면서도 공간이 규모를 과장되지 않게 형성하였고 또한 중문 앞의 조그마한 화단 설치는 깊숙한 시선의 지루함을 달래주는 구성미를 느끼게 하는 등 축조 당시의 근대적 사고가 반영되어 적절하게 공간구성이 이루어져 있다. 지리적 특성과 영호남의 문화도 중첩되어 나타나 있어 건축사 연구에 중요한 자료가 되는 건축물 이다","a":"하동 동매리 김씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666511.jpg"},{"q":"노은정은 노은 김상기가 학문 연마와 후배양성을 위해 숙종 15년(1689)에 지은 정자이다. 건물 이름은 선생의 호에서 유래하였으며, 철종 4년(1853)에 처음 고친 후 여러 차례 보수하였다. 건물은 화강암 위에 앞면·옆면 2칸 규모로 세웠고 마루는 우물마루를 깔았다. 정자의 각 기둥에는 수침을 막는 돌기 등을 사용해 안전을 도모했다. 노은정은 천안시에서 가장 오래된 정자이며, 300년 전 우리나라의 전통 건축 양식을 보여주는 건물로서 주위경관 또한 아름다워 ‘도원 8경’의 하나로 전하고 있다.","a":"천안노은정","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661513.jpg"},{"q":"삼성각 불단 좌측에 봉안되어 있으며, 칠성탱화와 마찬가지로 화계사에서 조성된 것이다. 비단바탕에 진채색(眞彩色)을 사용하여 그렸으며, 가로 139.5㎝, 세로 117.5㎝인 거의 정사각형에 가까운 두루마리 형태로 되어 있다. 독성은 스스로 스승 없이 독수선정(獨修禪定)하여 도를 깨우친 나반존자(那般尊者 또는 빈두루존자)를 그린 것으로, 화면 중앙에 녹색 원형두광을 두른 독성이 천태산(天台山)을 배경으로 소나무 밑에서 지팡이를 잡고, 왼쪽다리를 세워 팔을 기대어 편하게 앉아있는 자세를 취하고 있다.","a":"가평현등사독성도","c":"문화유산자료","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660253.jpg"},{"q":"민간신앙의 대상물인 신을 모셔 놓은 신당이다. 주민들은 ‘○○○’이라 부르는데, ○○○은 서울을 중심으로 한 경기지역에서만 불리던 당의 명칭이다. 기와를 올린 작은 집으로, 조선 인조 13년(1635) 당을 고칠 때 걸어둔 현판을 비롯한 5개의 현판과 무신도가 보존되어 있다. 특히 무신도는 조선 태조 내외분, 출산과 목숨, 농사의 신이라는 삼불제석의 그림이라고 전하는데, 마을사람들에 의해 마을을 보호해주는 수호신의 대상이 되고 있다. 조선 후기 신당의 건축양식을 보여줄 뿐 아니라, 서울지역의 동제 신앙을 보여주는 소중한 자료이다.","a":"서빙고동부군당","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658037.jpg"},{"q":"하윤(河潤, 1452-1500)은 자는 수부(晬夫), 호는 운수당(雲水堂)입니다. 1414년 생원에 입격하여 산음(山陰) 현감을 역임한 하순(河淳)의 손자며, 거제 현령을 역임한 하계지(河繼支)의 아들입니다. 1477년 생원·진사에 합격하고 1483년 문과에 급제하여 예조·호조·형조의 좌랑을 역임하고 순천(順川) 군수로 재직하다가 그곳에서 일생을 마쳤습니다. 1719년 ○○의 정강서원에 향사되었습니다. 묘비의 최초 수비 연도는 1502년이나 건립 당시의 돌은 그대로 둔 채 비문만 갈아내고 1851년에 다시 새긴 것이다.","a":"진주 검암리 하윤묘비 및 석인상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023022109271200.jpg"},{"q":"은렬공 ○○○은 고려시대의 명장으로 목종 때 문과에 급제한 후 현종3년(1012)에는 안찰사로 동여진을 격퇴, 1018년애는 거란이 10만대군으로 쳐들어오자 강감찬 장군의 부장으로 출전 대패시켰다. 그 공으로 지중추사병부상서(知中樞事兵部尙書)까지 올랐던 인물이다. 단령에 홀을 쥐고 있는 고려시대 백관의 공복차림의 ○○ 은렬사 소장 ○○○ 영정은 보물 제588호 은열공 영정과 매우 유사하며 표현기법이 우수한 수작에 속한 작품이다.","a":"진주 은열사 강민첨 초상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643053.jpg"},{"q":"조선 현종 때 성리학자인 곡운 김수증이 지은 정자이다. 김수증은 남인이 서인을 몰아내고 재집권하게 된 숙종15년(1689)의 기사환국으로 송시열과 동생 김수항이 죽자 낙향하여 이 정자를 짓고 은둔하였다. 창건 당시에는 송풍정, 삼일정, 부지암, 유지당 등 몇 채의 건물이 계곡을 사이에 두고 흩어져있었으나 지금은 없어지고, \"삼일정\", \"월굴암\", \"천근석\"이라 새긴 조경용 바위만 남아있다. 그리고 현재 송풍정과 삼일정은 복원된 것이다.","a":"화천화음동정사지","c":"시도기념물","nc":"","r":"강원특별자치도","s":"화천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648259.jpg"},{"q":"이 산성은 남해군 창선면 당항리 소재 ○○○의 정상을 둘러싸고 있는 테뫼식의 석축성이다. 산성으로 오르기까지의 경사가 매우 급해 접근이 용이하지 않으며, 성에서는 창선의 동쪽 해안과 삼천포 일대가 훤히 내려다보인다. 체성은 비교적 얄팍한 할석을 무질서하게 쌓아 축조한 것으로, 여장도 부분적으로 남아 있다. 성벽에서는 치가 확인되는 곳이 있으며, 2개의 문지가 있는 것으로 판단된다. 이 가운데 서문지는 폭 4m 가량으로, 비교적 뚜렷하게 확인되나 남문지는 조금 애매하다.","a":"남해금오산성","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657167.jpg"},{"q":"\"○○○○은 조선조 선조 초년의 명신인 미암 유희춘(1513～1577)의 사당이다. 유희춘은 조선 중기의 문신으로 자는 안중, 호는 미암 또는 인재(寅齋)하고 한다. 본관은 선산이며 순천에서 해남으로 이거한 유계린(柳桂麟)의 차남으로 출생하였다. 금남 최부(錦南 崔溥, 1454～1504)의 외손이다. 1537년(중종 6)에 생원시에 합격하고 다음해에 문과에 급제하여 성균관 학유, 예문관 검열, 홍문관 수찬, 무장현감 등을 지내다가 을사사화때 파직되었다.","a":"담양미암사당","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658405.jpg"},{"q":"○○○란 왕이나 고관 등의 평생업적을 기록하여 그의 무덤 가까이에 세워두는 것으로, 이 비는 조선 중기의 무신인 ○○○ 장군을 기리고 있다. ○○○은 35세 되던 선조 27년(1594)에 무과에 급제하였다. 정유재란이 일어났을 때에는 흥양현감으로서 이순신 장군의 지휘 아래 큰공을 세웠으며, 적의 포로로 있던 신덕희 외 700여 명이 살아서 돌아올 수 있게 하였다. 노량해전에서 이순신이 전사하자 벼슬을 버리고 고향으로 내려가 조용히 지내다 효종 2년(1651)에 생애를 마쳤다. 비는 네모난 받침돌 위에 비몸을 세우고 그 위에 지붕돌을 올렸다.","a":"최희량장군신도비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654130.jpg"},{"q":"퇴계 이황의 학통을 이어온 숙종(재위 1674∼1720) 때 성리학자 갈암 이현일(1627∼1704)의 정자이다. 이현일이 벼슬길을 포기하고 학문에 전념하기 위하여 숙종 2년(1676) 2칸짜리 초가집으로 지은 것인데, 순조 22년(1822) 후손들이 기와집으로 고쳐 지었다. 건물은 앞면 4칸·옆면 1칸의 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 출입문에는 ‘홍도문(弘道門)’이란 현판이 걸려 있는데, 숙종의 글씨라고 한다.","a":"남악정","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662520.jpg"},{"q":"용문서원의 자리에 남아 있는 일두 ○○○의 ○○○이다. ○○○은 일찍이 아버지를 여의고 혼자서 공부하다가 김종직의 문하로 들어갔다. 성조 11년(1480)에 성조가 경학에 밝은 사람을 구하자 성균관에서 그를 천거하였다. 연산군 1년(1495)에는 안음현감이 되어 백성을 어질게 다스렸으며, 「편의수십조」라는 법을 지어 시행하자 정치가 맑아져, 백성들로부터 칭송을 들었다. 무오사화(1498)로 경성으로 유배되었고, 갑자사화(1504) 때 죽음을 당했다. 비는 거북받침돌 위에 비몸을 세우고 용을 조각한 머릿돌을 얹은 모습으로, 조각이 매우 정교하고 뚜렷하다.","a":"함양 정여창 사당비","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664445.jpg"},{"q":"고려 후기의 문신인 송안군 이자수의 덕을 기리기 위하여 조선 성종 11년(1480)에 그의 후손 퇴계 이황의 할아버지 3형제가 지은 것이다. 숙종 41년(1715)에 지금의 위치로 옮겨 지었다. 정사는 앞쪽에 강당을 두고, 뒤쪽에는 이자수의 위패를 모신 사당을 세웠다. 재사는 이정의 묘제사를 위하여 동쪽에 별도로 마련한 건물이다. ㅁ자형으로 앞면에 6칸 규모의 누마루를 두고, 그 뒤로 재실을 마련한 전형적인 이 지방 재사 건축의 면모를 갖추고 있다.","a":"작산정사및가창재사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658495.jpg"},{"q":"춘천 ○○○가옥은 나지막한 산 아래에 세운 집으로 ㄱ자형 안채에 사랑채가 딸려 있어 전체적으로 ㄷ자형 평면을 이루고 있다. 안채는 대청마루를 중심으로 왼쪽에는 건넌방을 두고 오른쪽으로는 웃방·안방·부엌을 배치하였는데 부엌 천장에는 다락을 만들었다. 대청 뒤쪽 벽에는 2짝 문을 달고, 웃방과 안방 사이에도 문을 달아 공간을 구분하였다. 안채 대청 앞쪽으로는 햇빛을 막고 비가 들지 않게 높은 기둥을 세워 지붕을 덧댄 차양시설을 두었다. 사랑채는 대문을 중심으로 왼쪽에는 부엌과 사랑방을 두었고 오른쪽에는 광과 그 뒤편으로 방을 놓았다.","a":"춘천김정은가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660458.jpg"},{"q":"옛 나주군청에 서 있는 비로, 원래는 과원동 사매기 (‘사마교’의 음이 잘못 전하여 생긴 말인듯함)의 한 민가 담 옆에 있던 것을 1968년 이곳으로 옮겨 놓았다. 고려 현종 2년(1011) 거란이 쳐들어오자 왕은 수도 개경을 떠나 남쪽으로 피신하게 되었고, 이곳 나주에서도 10여일 동안 머무르는 일이 있었다. 왕이 네 마리의 말이 이끄는 수레를 타고 다리를 지나갔는데, 그 때부터 이 다리를 ‘사마교’라 불렀으며, 조선시대에 와서 고을 현감이 이 다리를 수리한 후 그 기념으로 비를 세워 놓았다. 비는 낮은 사각 받침돌 위로 비몸을 세우고 머릿돌을 올린 모습이다.","a":"사마비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662025.jpg"},{"q":"○○○○은 조선시대 학자인 윤증 선생의 영정을 봉안하고 있는 영당이다. 윤증 선생이 돌아가신 후 가르치던 유생들이 영조 20년(1744)에 영당과 경승재를 세우고 영정을 봉안하였다. 이후 여러 차례 중수가 거듭되었는데, 최근에는 후손들이 경승재와 영당을 중수한 후 3차례에 걸친 주변정리가 이루어졌다. 경승재는 정면 3칸, 측면 2칸의 팔작지붕에 익공양식으로 가구하고, 누마루식으로 만들었다. 영당은 경승재의 북동쪽에 자리하는데, 정면 3칸, 측면 2칸의 팔작지붕 건물이다. 영정을 중앙의 어각에 봉안하고 있다. 매년 음력 3월 15일과 9월 15일에 제향을 지내고 있다.","a":"유봉영당","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661330.jpg"},{"q":"노산성은 평창강이 굴곡하는 곳에 우뚝 솟은 노성산(해발 419m)에 쌓았는데, 삼면이 강으로 둘러싸여 있을 뿐만 아니라 북쪽은 절벽이거나 매우 가파른 곳이어서 천험의 지대라고 할 수 있다. 『신증동국여지승람』에는 노산성으로 기록되어 있으며, ‘돌로 쌓았으며 둘레 1,364척, 높이 4척이다. 안에 한 우물이 있다. 지금은 반은 퇴락되었다’라고 되어 있다. 이 성은 조선 선조 초에 군수 김광복(金光福)이 쌓은 것으로 전해지며, 임진왜란 때 권두문(權斗文) 군수가 지사함·우응민·이인노 등과 함께 백성을 거느리고 왜군과 싸웠던 곳으로 알려져 있다.","a":"평창노산성","c":"시도기념물","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648747.jpg"},{"q":"단성면 ○○○에 있는 신석기시대~가야시대의 생활·매장유적으로 남강변에 형성된 포인트 바(Point bar)에 자리잡고 있다. 남감댐 보강공사 계획에 따라 1985년부터 1999년까지 신라대학교 가야문화재연구소에 의해 3차례에 걸쳐 발굴조사되어 수많은 유구와 유물이 발견되었다. 현장설명회 자료와 여러 보고문에 따르면 이 곳에서는 신석기시대의 움집터와 적석유구, 청동기시대의 움집터와 돌널무덤, 원삼국시대의 움집터와 수혈유구, 널무덤, 띠모양유구, 가야시대의 집터, 방형 돌방무덤 등 오랜 시간에 걸쳐서 여러 종류의 유구가 형성된 것으로 파악된다.","a":"산청소남리선사유적","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656740.jpg"},{"q":"조선 중기 문신인 강항(1567∼1618)을 추모하기 위해 세운 서원이다. 강항은 공조좌랑과 형조좌랑에 있던 중 정유재란이 일어나자 의병을 모아 활동하다가 왜적의 포로가 되어 일본으로 압송되었다. 일본에 있으면서 그 나라의 역사, 지리 등을 알아내어 고국으로 보내기도 하면서 일본에는 성리학을 전하였다. 선조 33년(1600) 귀국한 후 벼슬을 사양하고 독서와 후진양성에만 전념하였다. 이 서원은 인조 13년(1635)에 나라에서 ‘용계사’라는 이름을 내려주었고 숙종 28년(1702)에 고쳐 세웠다.","a":"영광내산서원","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654040.jpg"},{"q":"부도란 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 이 부도는 군산의 보천사에 있던 것을 이 곳 혜봉원으로 옮겨놓은 것으로, ‘연화당부도’라 부르기도 한다. 전체적인 모습은 낮은 사각바닥돌 위로, 3단을 이루는 8각 기단(基壇)을 쌓고, 공모양의 탑몸돌을 올린 후 8각 지붕돌을 얹은 구조이다. 기단 중에서 아래받침돌은 두 겹의 연꽃잎을 둘러 새겼으며, 그 위로는 가운데받침돌을 괴기 위한 높직한 받침을 하나 더 두었다.","a":"모현동부도","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661627.jpg"},{"q":"○○○ 입구에 서 있는 한 쌍의 돌장승으로, 절의 영역을 표시함과 동시에 수문장으로서, 절을 지키고 경내의 살생과 나무채취를 막는 구실을 한다. 남장승의 높이는 170cm, 너비 48cm이며, 여장승은 높이 166cm, 너비 41cm이다. 투박한 돌을 거칠게 깎아 만든 두 장승은 커다란 황소눈에 주먹코이다. 입은 다물고 있지만 미소를 짓고있는 모습에서 시골의 노인을 떠올리게 한다. 아들을 낳기 원하는 사람들이 장승에 고사를 지내거나 장승코를 갈아서 깨끗한 물에 타 마시기도 하였다는 이야기가 전한다.","a":"법천사석장승","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658385.jpg"},{"q":"봉복사 절입구의 산기슭 밭 가운데에 자리하고 있는 탑이다. 이웃 주민들에 의하면 원래 이 터가 봉복사의 자리였다고 전해들었다 하는데, 이로 보아 이 밭 일대가 고려시대의 옛 절터였던 것으로 보인다. 탑은 전체의 무게를 받치는 기단(基壇)을 2층으로 쌓고, 그 위로 3층의 탑신(塔身)을 올려놓은 구조이다. 아래층 기단의 네 면에는 가운데와 모서리에 기둥모양을 새기고, 위층 기단은 모서리에만 기둥모양을 조각해 놓았는데, 탑신부의 각층 몸돌 역시 그러하다.","a":"횡성신대리삼층석탑","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638005.jpg"},{"q":"안동권씨로서 처음으로 저곡(渚谷)에 들어와 산 시조인 권의(權? 1475-1558)와 아들 권심언(權審言 1502-1574), 손자 권시(權時 1552-1612), 권욱(權旭 1556-1612), 권담(權曇 1556-1631) 등 4대의 묘지를 지키기 위해 지은 집","a":"함포재사","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663495.jpg"},{"q":"조선시대 정조(재위 1776∼1800)가 아버지인 사도세자의 능에 참배하러 가는 도중에 잠시 들러 휴식하던 곳으로 욕은지(浴恩池)와 함께 자리 잡고 있다. 원래 욕은지는 다른 곳에 있었는데, 고종 24년(1887)에 수리하면서 이곳으로 옮겨 왔다고 한다. 정조는 활쏘기를 즐겨 신하들에게도 활을 쏘게 하였다는데, ○○○에서 활을 쏘고 욕은지에서 손을 씻었다는 이야기가 전한다.","a":"어사대","c":"문화유산자료","nc":"","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659524.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 충청남도 태안군에서 서북쪽으로 13.6㎞ 떨어진 해안가에 있는 조선시대 읍성으로, 조선 중종 9년(1514)에 쌓은 것이다. 이 곳에 성을 쌓게 된 동기는 왜구의 침입을 막기 위해서였는데, 특히 고려 말부터 이 지역에 나타난 왜구의 침입으로 인해 지역 주민들의 피해가 심각했다고 한다. 이 성은 서쪽으로는 서해에 접하고 있으며, 동·남·북벽은 자연지형을 이용하여 성벽을 구축하였다. 성의 둘레는 650m 정도인데 대부분이 무너지고 현재는 동문터 부근만이 남아 있다.","a":"태안소근진성","c":"시도기념물","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652844.jpg"},{"q":"○○○ 법보전 목조 ○○○○ 좌상(觀音寺法寶殿木造觀音菩薩坐像)은 원래 충청남도 금산군 남이면 석동리 보석사(寶石寺)에 있던 것을 옮겨왔다고 전한다. 연화문(蓮花文)과 화염보주(火炎寶珠)로 장식된 화려한 보관을 착용하고 있으며 얼굴은 살집이 있고, 이목구비는 부드럽지만 뚜렷하다. ○○○이지만 불상이 입는 대의를 통견식으로 착용하고 있으며, 옷 주름은 직선적으로 표현되어 있다. 가슴에는 화려한 영락(瓔珞) 장식을 착용하고 있다. 무릎은 높고, 넓어 안정감을 준다. 오른손은 내려 중지와 엄지를 맞대고 있고, 왼손은 가슴까지 들어 올려 정병(淨甁)을 잡고 있다.","a":"관음사 목조관음보살상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639803.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 5년(1405)에 처음 지었다고 전한다. 건물 배치는 앞쪽에 교육 공간으로 명륜당이 있고, 뒤쪽에 제사 공간인 대성전이 있어 전학후묘의 형태를 따르고 있다. 대성전은 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짠 익공 양식으로 꾸몄다. 안쪽에는 공자를 비롯하여 중국과 우리나라 성현들의 위패를 모시고 있다.","a":"대흥향교","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653010.jpg"},{"q":"무등산 장원봉의 동남쪽으로 비탈진 곳에 위치한 무덤들이다. 모두 6개의 무덤이 있으나 널(관)을 넣었던 돌방(석실)이 완전히 드러난 것은 2기 뿐이다. 1호와 2호 무덤은 유사한 구조를 가지고 있는데, 바닥은 얇은 판돌들을 물이 잘 빠지도록 이중으로 깔고, 가장 밑바닥은 회갈색의 단단한 진흙을 냇돌과 섞어 기초를 다졌다. 올라가면서 무덤방의 너비를 줄인 후 정상부에 2매의 뚜껑돌을 올려 그 무게로 동서벽을 유지하게 한 맞조림식 돌방무덤이다.","a":"운림동석실고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659602.jpg"},{"q":"현 소유자의 고조부가 150년 전에 세웠다고 전하며 현재 3대손이 살고 있다. ㄱ자형 평면을 갖추고 있으며 앞면 4칸·옆면 2칸 규모에 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면 2칸은 마루로 되어 있고 옆면에 사랑방과 골방이 있다. 부엌 앞에는 지형을 이용하여 본채보다 한단 낮추어 덧댄 외양간이 있다. 본채는 앞면에 대청을 중심으로 좌우에 부엌과 사랑방을 두고 마루 뒤로는 안방과 도장방을 두었으며, 뒷편에 헛간과 고방을 별채로 배치하였다. 세운 시기를 자세하게 알 수 없지만 원래 구성리에 있던 것을 75년 전에 지금 있는 자리로 옮긴 것이다.","a":"고성이덕균가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660473.jpg"},{"q":"○○○로 들어가는 길가의 양쪽에 마주보고 서 있는 한 쌍의 ○○○이다. 잡귀의 출입을 금하는 기능과 함께 불법을 지키는 신장상(神將像)으로서의 구실을 하였던 것으로 추측되는데, 2기 모두 몸통이 절반 가량 땅 속에 묻혀 있어, 드러난 높이가 2m 내외이고, 그나마 한쪽 장승은 윗부분이 불에 타 파손이 심하다. 대체로 잘 남아 있는 오른쪽 장승은 대머리에 크고 둥근 눈이 돌출되었다. 코 주위에 깊은 선을 둘러 뭉툭한 코가 더 두드러져 보이며, 꽉 다문 입 주위와 턱 아래에는 톱니 모양의 수염을 묘사해 놓았다.","a":"함양 벽송사 목장승","c":"시도민속문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659021.jpg"},{"q":"○○○는 충무공 최필달의 위패를 모신 사당으로 1900년대 초에 문중과 유림이 논의하여 짓게 되었다. 고려 개국공신 중 한 사람으로 강릉 최씨의 시조인 충무공은, 그 당시의 학문을 바로 세우고 예를 가르친 문무를 겸한 학자로서 ‘해동부자(海東父子)’라고 불렸다. ○○○는 앞면 3칸·옆면 2칸 규모이며，지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 또한 사당의 경내에는 문정공 최수성의 위패가 모셔진 사당 문정묘가 있다. 후손인 최명수와 진사 정채화 등이 1936년 남문동에 건립하였는데, 주변에 주택 등의 건물이 들어섬에 따라 1982년 지금의 위치로 옮겨졌다.","a":"황산사","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638000.jpg"},{"q":"상평초등학교 현서분교 운동장 반대편 건물 뒷쪽에 서 있는 탑으로, 원래는 이곳에서 동쪽으로 약 200m 떨어진 논에 있던 것을 1965년 옆에 있는 ○○○○석조비로자나불좌상(강원특별자치도 문화유산자료)과 함께 이곳으로 옮겨 보존하고 있다. 탑은 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단과 탑신의 1·2층 몸돌 모서리에는 기둥 모양을 새겨 놓았다. 급한 경사가 흐르는 지붕돌은 둔하고 무거워 보이는데, 네 귀퉁이가 경쾌하게 들려있어 무거운 맛을 덜어주고 있으며, 밑면에는 1·2층은 4단, 3층은 3단의 받침을 두었다.","a":"양양서림사지삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660558.jpg"},{"q":"○○군 남면 ○○○ 및 상남면 상남리에 흩어져 있는 석탑 및 탑의 일부분으로, 모두 3기에 이른다. 첫번째는 ○○○ 5층 석탑으로, 2층 기단(基壇) 위에 5층의 탑신(塔身)을 올리고 있는데, 탑신의 1·2·3층 몸돌과 5층 지붕돌은 탑을 복원할 때 새로 만들어 끼워 넣은 것이다. 아래층 기단에는 안상(眼象)을 조각하고 위층 기단에는 기둥모양과 글을 새겨 놓았다. 탑신의 각 층 지붕돌은 네 귀퉁이가 살짝 치켜 올라 갔으며 밑면에 3단의 받침을 두었다. 위층 기단에 고려 정종 2년(1036)이란 기록이 있어 고려시대 석탑 및 불교사 연구에 중요한 자료가 되고 있다.","a":"인제 갑둔리 오층석탑 및 주변탑재 일식","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"인제군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660553.jpg"},{"q":"해촌 남극만 선생이 조선 영조 31년(1755) 세운 집으로, 고종 15년(1878) 고쳐 지어 오늘에 이르고 있다. 왼쪽 3칸에 중간문과 아랫방을 배치하였고, 오른쪽에는 1칸 규모의 작은 사랑방을 두었으며 그 뒤쪽으로는 큰 사랑방을 놓았다. 작은 사랑방의 앞면과 오른쪽면으로는 각 1칸 반 규모의 사랑마루를 꾸며 놓았다.","a":"영덕 괴시동 해촌고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658969.jpg"},{"q":"○○○는 ○○○을 비롯한 4곳의 암자를 포함한 사찰이다. ○○○ 안의 ○○○은 험준한 바위 위에 세운 법당으로 상○○○이라고 부른다. 조선 중종 6년(1511)과 숙종 20년(1694), 순조 17년(1817)에 다시 지었다. 이 건물은 거대한 바위 위에 세웠기 때문에 기단없이 편편한 곳에 자리잡아 원형 주춧돌만 두었다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 기둥은 둥근기둥을 사용하였고, 벽선에 亞자형 2짝 여닫이문을 달았는데, 가운데 칸과 양 옆칸은 그 간격을 다르게 하여 예불 공간을 크게 하였다.","a":"선운사도솔암내원궁","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661752.jpg"},{"q":"이 자료는 석곡(石谷) 이규준(李奎晙, 1855~1923)이 편찬․저술한『곡례유이』,『경수삼편』,『의례주소절요』,『의감중마』의 ○○이다.『곡례유이』는 초학자가 곡례를 쉽게 읽을 수 있도록 풀이한 책이며,『경수삼편』은 중국 역대 경학자들의 경전연구를 정리한 것이다.『의례주소절요』에서는 예기를 주석하여 조목조목 설명하였고,『의감중마』는 1908년에 편찬한 의서이다. 이규준은 정주학을 비롯한 유학자들의 육경주소에 의혹을 갖고 유학의 근본이념으로의 회귀를 주장했으며 의학 분야에서 탁월한 업적을 남기기도 하였다.","a":"포항 경주이씨 익재공파 석동문중 소장 판목","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017122210475500.jpg"},{"q":"○○○○○은 익안대군 방의의 손자인 백파 도정공 이상의 영정을 모시고 제향하는 곳이다. 이상의 아들인 이현동은 세조가 즉위하자 논산시 벌곡면 조령리에 낙향하였고, 그 후손들이 영당을 건립하였다고 전하지만, 정확한 건립연대는 알 수 없다. 이현동은 김숙자의 문인으로 점필재 김종직과 교분이 두터웠고, 세조가 왕위를 찬탈하자 연산면 조령에 은거하여 평생 북쪽을 향해 않지 않고, 자손들에게 벼슬을 하지 말도록 경계하였다. 부적면 충곡리의 충곡서원에 배향되었고, 조형리에는 신도비가 있다. 영당의 기둥은 원주를 사용하였고 2익공계의 건축이다.","a":"백파이상영당","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661579.jpg"},{"q":"7권말(卷末)에 붙은 순충좌명개국공신정대부수문학사남재(純忠佐命開國功臣政大夫修文學士 南在)의 발문(跋文)에 의하면 해린(海隣)이 중정대부사재령[(中正大夫司宰令)을 지낸 정천익(鄭天益)과 전중훈대부군기감 이양(前中訓大夫軍器監 李穰) 등의 시주금(施主金)으로 정종 원년(定宗;1399)에 간행한 것으로 국립중앙박물관 소장의 보물 1081호『○○○○○권 1~3, 4~7(妙法蓮華經卷一~三, 四~七)』과 동일 판본으로 보인다. 권 1의 첫 장과 둘째 장 일부가 유실(流失)되어 보충을 하였지만 대체로 보존 상태는 양호하다.","a":"묘법연화경","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101216463100.jpg"},{"q":"『○○경』은 우리나라에서 가장 많이 읽혀졌던 불교신앙의 기본경전이며, 관세음보살의 광대한 자비심을 찬양하는 다라니경이다. 중국 송나라의 사명존자(四明尊者)에 의하여 널리 유포되었고, 우리나라에서는 고려 중기부터 유통되기 시작하여 조선시대에는 가장 많은 판본을 남기면서 크게 신봉되었다. 전체 7판으로 된 『○○경』은 크기가 가로 21.4㎝, 세로 54.4㎝이며, 안쪽 테두리 크기는 가로 21.1㎝, 세로 34.8㎝이다. 간행기록에 의하면 숙종 2년(1676)에 감로사에서 간행한 것을 다시 ○○○로 옮겨 간행하였다는 내용이 있다.","a":"범어사 천수 책판","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636659.jpg"},{"q":"조선 광해군 5년(1613) 애송당 문익현이 지어 14대째 내려오고 있다. 현 소유자인 ○○○의 5대조 문병호가 고쳐 지었으며, 1968년에는 문간채를 새로 지었다. 건물은 안채, 사랑채, 문간채 등으로 구성되어 있다. 안채와 사랑채는 앞면 5칸 규모에 앞뒤로 툇마루를 두었다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 문간채는 앞면 3칸 규모이며 문은 솟을대문 형식으로 꾸몄다. 350년 이상된 건물로 일부 수리가 있었지만, 대체로 원형을 잘 보존한 이 지방 전통 가옥이다.","a":"영암문창집가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662119.jpg"},{"q":"1919년 3·1 운동이 전국적으로 전개되자 유림측에서도 프랑스의 파리에서 개최되는 강회회의에 한국독립을 호소하는 장문의 서한을 작성하여 보낸 일이 있다. 일명 파리장서 사건이라 하는데, 이곳 ○○○○와 ○○○은 유림들이 모여 서한을 작성하고 총의를 모아 준비한 결집장소로 사용되었다. ○○○○는 앞면 4칸·옆면 1칸 반의 규모이며, 지붕은 옆에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 독특한 조형미를 살리고 있다. ○○○은 앞면 3칸·옆면 2칸의 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"산청 용강정사,임리정","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664442.jpg"},{"q":"○○○○은 대구광역시 남구 대명동에 있는 대덕산 정상에서 북쪽의 안지랭이 계곡을 감싸며 쌓은 포곡식 산성으로 ‘앞산산성 ’이라고도 부른다. 포곡식 산성은 성곽이 하나 또는 여러 개의 계곡을 감싸고 축성된 것으로, 장기간 전투에 사용하기 위해 쌓은 성을 말한다. 옛 기록에 의하면 성불산의 옛 성이 수성현에 있었으나, 지금은 산의 능선과 비탈부근에 깬 돌로 성을 쌓은 흔적만이 남아 있다. 성의 둘레는 3,051척이라고 기록되어 있는데, 그 범위는 약 3㎞에 달한다.","a":"대덕산성","c":"시도기념물","nc":"","r":"대구광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645349.jpg"},{"q":"조선 전기의 무신인 ○○○ 선생의 초상화 1폭과 매가 조각된 목판 1점이다. ○○○는 조선 태조 이성계의 형인 이원계의 아들로, 1차 왕자의 난(1398)과 2차 왕자의 난(1400)을 평정하여 공신이 되었고, 그후 병조판서 등을 지내었다. 초상화는 머리에 사모를 쓰고 관복을 입고 두 손을 소매 안으로 마주잡은 채 의자에 앉은 전신상이다. 약간 왼쪽을 바라보고, 관복에 좌우 옆트임을 두고 있어 조선 전기의 전형적인 화풍을 보여주고 있다.","a":"이천우영정및이응도목판·공신회맹축목판","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662108.jpg"},{"q":"선운사의 산내암자인 도솔암에 있는 법당이다. 정면3칸 측면1칸에 맞배지붕으로 되어 있으며, 현존하는 건물은 건축수법으로 보아 조선 말기에 세워진 것으로 보인다. ○○○ 내부에는 흙으로 빚은 석가모니불을 중심으로 가섭과 아난이 협시하였고, 1910년 용문암에서 옮겨온 16나한상을 모시고 있다. 도솔암은 선운사의 산내암자로서 대웅전 서쪽 150m정도 떨어진 곳에 있으며, 원래는 여섯 도솔암이 있었으나 현재는 상하 2개의 도솔암만 남아 있다.","a":"나한전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661737.jpg"},{"q":"○○○와 안채는 근대기 유학자가 건축한 주택형 장수지소(藏修之所)라는 점과 전통 한옥과 외래 건축의 요소가 혼합된 근대한옥의 특성을 잘 보여준다.","a":"김해 일신재","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666769.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공양왕 2년(1390)에 처음 지었는데, 당시의 위치는 금구동헌으로부터 동쪽으로 약 2㎞ 떨어진 곳이었다고 한다. 그 뒤 조선 숙종 원년(1675)에 지금 있는 자리로 옮겨 오늘에 이르고 있다. ○○○은 앞면 3칸·옆면 2칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯하여 중국과 우리나라 성현의 위패를 모시고 있다.","a":"금구향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661742.jpg"},{"q":"경상남도 ○○군 도천면 ○○○에 모셔진 불상이다. 자연암석의 한쪽 면을 다듬어서 선으로 새긴 마애불로, 불신과 몸 뒤의 광배(光背)를 나타냈다. 얼굴은 길고 온화하게 표현되었으며 전체적인 조각수법에서 시대가 뒤떨어짐을 알 수 있다. 한국전쟁 때 ○○○가 전부 불탔었는데, 그 때의 충격으로 불상의 중간 부분에 금이 갔다.","a":"창녕 관음사 미륵불비상","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663826.jpg"},{"q":"1930년 건축가 김순하 선생의 설계로 지었다. 지하 1층·지상 2층의 붉은 벽돌건물인데, 2층의 창문이 위·아래로 나뉘어 밖에서 볼 때는 3층으로 보이는 아담한 건물이다. 출입구의 위쪽부터 옥상까지 전체면을 유리로 장식하였고 건물 양 옆의 모서리를 둥글게 곡선처리 하였으며, 동시에 창문도 곡선창을 사용하였다. 출입구 앞 계단의 난간 역시 곡선처리를 하였는데, 이것은 1930년대에 지은 건물로는 매우 혁신적인 면이 돋보인다.","a":"전남도청회의실","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637141.jpg"},{"q":"조선시대의 무신인 ○○○ 장군의 묘비로, 향교골에 자리하고 있다. ○○○는 선조 38년(1605) 무과에 급제하여 벼슬길에 올랐다. 광해군 10년(1618) 여진족의 건주위(建州衛)가 반란을 일으킬 때 명나라에서 조선에 군사를 요청하여 그가 명나라에 원군으로 가 장렬히 싸우다 전사하였다. 이에 대한 공으로 명나라에서는 ○○○이라는 벼슬을 내리고 그 처자에게 백금을 보내 주었으며, 조선의 조정은 영의정으로 벼슬을 높여 주었다. 비는 거북모양의 받침돌 위에 비몸을 세우고 지붕돌을 올렸다.","a":"요동백김응하장군묘비","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638124.jpg"},{"q":"목조 초가민가로 약 200여년 전 건립된 전형적인 전통가옥이며, 가씨 종중에서 1930년대 가옥을 인수 후 현재까지 거주 및 관리하고 있다. 가옥 형태는 안채(78㎡), 사랑채(32㎡), 문간채(59㎡)등으로, ㅁ자형으로 형태를 이루고 있으며, 기구의 기법도 민간의 간이석 덧붙이기 방식을 따랐으며, 지붕 연목도 평연재로 되어있고 마루난간은 亜자형으로 특이한 구조를 이루고 있다.","a":"태안상옥리가영현가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658268.jpg"},{"q":"이 가옥은 1807년(순조 7)에 현 소유자 ○○○閔正基의 6대조인 민형현閔亨顯이 건립한 가옥으로 안채와 사랑채, 사당, 문간채 등을 갖추고 있다. 안채 상량 기록 “숭정기원후사을사중수崇禎紀元後四乙巳重修”로 보아 1845년(헌종 11)에 다시 지은 것이다. 안채는 6칸 규모의 ‘一자형’ 집으로 앞뒤에 툇마루를 두었으며, 대청 한쪽에는 곡식을 저장하는 안광을 설치하였다. 특히 누마루 난간은 아자형, 원형, 조롱목형 등 다양한 문양으로 장식되어 독특하다. 사랑채는 앞면 5칸, 옆면 1칸 규모로 중앙 대청과 양쪽 온돌방을 갖추었다.","a":"해남민정기가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662187.jpg"},{"q":"신도비는 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 2기의 비석은 조선 선조 때 영의정을 지낸 노수신의 할아버지 노익과 아버지 노홍의 행적을 각각 기리고 있다. 두 비석의 크기와 형태가 서로 같아서, 거북받침돌 위에 비몸을 올리고 반원형의 머릿돌을 얹은 모습이다. 거북의 등에는 비를 꽂아두기 위한 직사각형의 비좌(碑座)를 갖추고 있으며, 머릿돌에는 앞·뒤면과 옆면에 용과 구름무늬를 섬세하게 새겨 놓았다. 비문 전체를 다 알아보기는 어려운 상태이다.","a":"노후 및 노홍신도비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640736.jpg"},{"q":"○○○○는 옛날 화성과 광주의 경계에 위치한 지지현의 산마루 위에 있는 비석이다. 조선 제22대 왕인 정조의 지극한 효성을 추모하기 위해 순조 7년(1807) 화성 어사 신현(申絢, 1764~1827)의 건의로 세워졌다. 정조가 아버지 사도세자의 능인 현륭원(顯隆園, 현재 화성시 융릉)에 참배를 하러 갈 때, 아버지의 묘가 내려다보이는 데도 묘까지 가는 시간이 너무 더디게 느껴져 \"왜 이리 더딘가\"하고 한탄하였다고 한다.","a":"지지대비","c":"시도유형문화유산","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637376.jpg"},{"q":"화순 ○○○에 모셔져 있는 ○○○○○좌상으로서 앉은 모습의 석가여래상을 중심으로 가섭존자와 아난존자가 양옆에 서있는 특이한 형식의 ○○○○이다. ○○○는 우리나라 현존 유일의 3층 목탑식 전각이어서 보물로 지정되어 보호하여 왔으나 1984년 불에 타 다시 지었다. 불이 난 당시 다행히도 ○○○○○좌상은 화를 입지 않았다. 가운데 모셔져 있는 석가여래상은 약간 앞으로 고개를 숙이고 있는 모습으로 얼굴은 사각형에 가까우며 머리는 소라모양의 나발이다. 붉은 입술에 미소를 머금고 있으며 귀는 크고 두툼하다. 양어깨를 감싼 옷은 두툼한 느낌을 준다.","a":"화순쌍봉사대웅전목조삼존불상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640159.jpg"},{"q":"조선 중종(재위 1506∼1544) 때 학자이자 서화가인 학포 양팽손의 서재였으나 지금 있는 건물은 당시의 건물이 아니고 1920년대에 후손들이 지은 것이다. 양팽손(1488∼1545)은 조선 중기 문신으로 중종 11년(1516) 과거에 급제한 후 정언, 전랑, 수찬, 교리 등의 직을 역임하였다. 중종 14년(1519) 기묘사화로 관직을 잃은 뒤 고향으로 내려와 1521년 ○○○을 짓고 제자들을 가르치며 시와 그림으로 하루를 보냈다. 글과 그림에 능하였으며 저서로는 『학포유집』 2책이 전하고 있다.","a":"학포당","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654243.jpg"},{"q":"중국 송나라 주자의 영정을 봉안하고 있는 사당이다. 조선 철종 7년(1856)에 주응동이 안성에 사는 김용으로부터 주자의 영정을 기증받아 주씨 문중에서 사당을 짓고 서원을 열었다. 처음에 문곡영당이라 하였는데 흥선대원군의 서원철폐령으로 폐원되었다가 고종 30년(1893)년 다시 지어 사당의 명칭을 ○○○라 하였다. ○○○의 건물 배치를 보면 문을 지나 전면에 제사를 지내는 강당이 있고 그 뒤로 담장을 돌리고 삼문을 설치하였으며 삼문을 지나면 사당이 있다. 강당은 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"음성 태교사","c":"문화유산자료","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660724.jpg"},{"q":"대구 ○○○ 중앙봉의 정상에 위치하고 있는 전체 높이 6m에 달하는 거대한 석불입상이다. 얼굴은 두 볼이 풍만하고 입가에 약간의 미소를 띠고 있어서 자비스러움을 느끼게 한다. 신체에 비해 큰 오른팔은 안쪽으로 늘어뜨렸는데 다섯손가락의 길이가 고르지 않아 부자연스러우며, 왼팔은 가슴 앞으로 올려 무언가를 잡고 있는 듯하나 확실하지 않다. 옷자락 밖으로 노출된 발끝은 발가락의 조각이 뚜렷하여 거대한 불상임에도 안정감을 준다. 거대한 불상에 잘 조화되어 있는 옷주름이나 인상 등의 조각수법으로 보아 관봉(冠峰)의 석조여래좌상과 같은 시대에 만들어진 작품으로 추정된다.","a":"팔공산동봉석조약사여래입상","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636878.jpg"},{"q":"○○○에 소재한 오층석탑과 ○○○○가 위치한 이곳은 고려시대에 큰절이 있었다고 해서 지금도 이곳을 대사동(大寺洞)이라고 부른다. ○○○○의 간대(竿臺)는 중앙에 간을 받치는 부분을 직경 20㎝ 정도로 파고 기둥자리의 원자(圓座)를 양각하였다. 장식적인 의장이나 아무런 조각이 없으며 1개의 통석으로 비교적 작고 소박하게 조성된 것으로 보아 고려 말에서 조선초기에 만들어진 것으로 추정된다.","a":"서산동문동당간지주","c":"시도유형문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639323.jpg"},{"q":"뒤에는 갓등산이 둘러있고 앞에는 반변천이 흐르는 아늑한 자리에 서남향으로 자리잡고 있는 건물이다. 이 정자와 살림집은 조선 중기 효종 때 삼수당 조규(1630∼1679) 선생이 지은 것이다. 솟을대문을 들어서면 왼쪽에 정자가 놓이고 그 앞쪽에 살림집이 있다. ○○○은 앞면 3칸·옆면 2칸의 정자로 왼쪽은 2칸의 온돌방을 두었고 가운데와 오른쪽에는 4칸의 대청마루를 두었다. 건물의 4면에는 돌출한 좁은 마루를 돌렸으며, 대청은 누마루로 높이 올렸다. 세부 건축양식은 일반적인 조선 중기의 모습을 잘 간직하고 있다.","a":"학초정및정침","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658738.jpg"},{"q":"요지란 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○ 백자 마가터는 15∼16세기경에 운영되던 백자 가마터로 추정되며, 2∼3곳의 가마터가 넓게 퍼져 있다. 지름 10∼20m 안에 자기 조각이 흩어져 있고, 불에 구워진 흙 덩어리도 많이 발견되었다. 어두운 청회색·연한청색·백색의 접시와 대접이 발견된다. 그릇의 모양은 대체로 낮으며, 굽은 얇으나 그릇의 모양에 비해 지름이 넓은 편이다. 도자기의 품질은 좋은 것과 나쁜 것 두가지 모두가 발견되었다.","a":"영양화매동백자도요지","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662747.jpg"},{"q":"○○○○○은 탐진안씨가 누대로 세거하고 있는 ○○군 입산마을의 중앙부에서 위치하고 있으며, 1948년 대한민국 정부 수립 때 초대 문교부장관을 역임한 ○○○ 박사의 생가이다. ○○○○○에서 건축사적 가치를 가진 것은 1911년에 건축한 안채뿐이며, 안채를 제외한 아래채, 협문 등은 건축연대가 늦고, 건물 배치 및 외부공간의 구성면에서 볼 때 사랑채와 대문채 및 기타 부속건물의 멸실로 인해 원형이 크게 훼손되어 있는 상태이다.","a":"의령 안호상 고택","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666381.jpg"},{"q":"명종 즉위년(1545)에 을사사화가 일어나자 학자인 하서 김인후가 관직을 그만두고 세상을 피해 숨어 살던 곳이다. 김인후는 낙덕암 주위의 산세를 유난히 좋아했던 것으로 전하며, 자연을 즐기는 한편 후세들에게 성리학을 가르쳤다. 고종 4년(1900)에는 훗날 이곳에서 훌륭한 인재가 나올 것이라는 김노수의 예언을 따라 낙덕암 위에 정자를 지어 오늘에 이르고 있다.","a":"낙덕정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661688.jpg"},{"q":"이 집은 현재 주인인 이서영의 조부인 ○○○이 1917년에 초창(初創) 하였는데, 건축 당시에는 안채, 사랑채, 행랑채, 문간채, 곳간채 등 여러 채가 있었으나, 현재는 안채와 사랑채, 담장과 대문 일부만이 남아 있다.","a":"이배원 가옥","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658344.jpg"},{"q":"고려의 개국공신인 ○○○을 기리는 유적이다. ○○○은 평산 신씨의 시조로서, 918년 배현경, 홍유, 복지겸 등과 함께 궁예를 몰아내고 왕건을 추대하여, 고려의 건국에 이바지한 인물이다. 고려 태조 10년(927) 대구 공산에서 후백제 견훤의 군대와 싸우다가 태조가 적군에게 포위되어 위급해지자, 태조의 옷을 입고 변장하여 맞서다가 전사하였다. 태조는 그의 죽음을 애통히 여겨 그의 시신을 거두어 광해주(지금의 춘천)에 묻고 순절단, 지묘사, 미리사를 세워 명복을 빌었다.","a":"신숭겸장군유적","c":"시도기념물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645328.jpg"},{"q":"○○○은 1884년(고종 21)에 권정기(權政基)가 중추원 의관을 지낸 아버지 광암 권병덕(廣巖 權秉德)을 위해 세운 것이다. 아버지의 호를 따서 광암(廣巖)이라 이름 붙였다. 원래 ○○○은 이곳에서 1㎞ 정도 떨어진 창리(倉里)의 황강변 자연암반 위에 세워졌지만, ○○댐 공사로 수몰을 피하여 1985년 지금의 자리로 옮겨 세운 것이다. 건물은 정면 4칸, 측면 3칸의 누각식 건물로, 마루 중앙에 정면 2칸, 측면 1칸의 방이 있다.","a":"합천 광암정","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664047.jpg"},{"q":"경상북도 봉화군 재산면 ○○○의 바위면에 조각한 마애불로, 진리의 세계를 두루 통솔한다는 의미를 지닌 ○○○○○을 형상화한 것이다. 민머리 위에는 상투 모양의 머리묶음을 낮게 표현했으며, 네모난 얼굴에는 눈·코·입 등을 단정하게 표현하였다. 두 귀는 길어 양 어깨에 닿았으며 목에는 3줄의 삼도(三道)가 뚜렷하다. 양 어깨를 감싸고 있는 옷은 목깃이 중간에서 한번 접혔고, 양 어깨에서 겨드랑이 아래로 비스듬히 내려오는 같은 간격의 옷주름은 선으로 새겼다.","a":"봉화동면리마애비로자나불입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640854.jpg"},{"q":"조선후기 양반가의 전형을 잘 보여주는 집으로 안채와 사랑채, 대문채 등이 원형대로 잘 남아있어 당시의 생활상을 살필 수 있으며, 또한 4형제 중 장남가로서 그 규모를 가늠해 볼 수 있음","a":"거창 최진사 고가","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666753.jpg"},{"q":"상촌(桑村) ○○○선생은 고려의 문신으로 본관은 경주(慶州)이다. 고려말 정세가 어려워지자 모든 관직을 버리고 고향인 안동에 은거하였다. 조선이 개국된 뒤 태종이 형조판서로 불렀으나 나가지 않고, 자손에게 결코 비석을 만들지 말라는 유언을 남기고 자결하였다. 묘는 단분(單墳)이며, 봉분 앞에 혼유석, 석상, 향로석이 있고, 그 앞에 장명등이 있으며 좌우로 석양(石羊)과 망주석이 각 1쌍, 문인석이 2쌍 건립되어 있다. 석상 좌우의 작은 문인석은 양식으로 보아 조선 초기 작품이며, 큰 문인석과 향로석, 망주석 등은 조선후기 작품이다.","a":"김자수선생묘","c":"시도기념물","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646365.jpg"},{"q":"‘○○○’은 남한산성(南漢山城) 안에 있으며, 1672년에 이세화(李世華)가 지은 정자(亭子)이다.‘○○○’이라는 이름은 “군자는 백성들을 잘 포용하여 잘 살도록 길러 나간다” 는 뜻을 담고 있다. ○○○은 앞면 3칸, 옆면 3칸 규모의 건물이지만, 옆면의 1칸이 반 칸 크기여서 전체모양은 앞면이 옆면보다 넓은 장방형 형태를 띠고 있다. 건물은 4면이 모두 개방되어 밖을 볼 수 있다. 그리고 지붕은 옆면에서 볼 때 ‘八(여덟 팔)자’ 모양인 팔작지붕을 하고 있다.","a":"지수당","c":"문화유산자료","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659880.jpg"},{"q":"이 ○○○은 만든 때와 만든 이를 알 수 있는 조선 후기의 중요한 나무 불상이다. 극락전은 극락의 주인으로 계신 ○○○부처를 모신 절집이다. ○○○부처 좌우에서 보좌하여 ○○○을 이루는 보살이 관음보살과 대세지보살이다. 이 ○○○은 관음보살상의 대좌에 쓰여 있는 먹글씨에 의해 1713년에 만들었음을 알 수 있다. 작가가 달라서인지 아니면 원래 같은 짝이 아니어서 그런지 삼존 가운데 본존의 오른쪽 대세지보살상은 크기도 작고 얼굴 표정과 옷차림새도 다르다. 본존 ○○○부처는 신체에 비해 머리가 큰 편이며, 앞으로 약간 움츠린 듯한 자세를 취하고 있다.","a":"고양상운사목조아미타삼존불","c":"시도유형문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020031015272100.JPG"},{"q":"관무량수경의 16관 중 제 14·15·16관에 해당되는 9품이 극락에 간 것을 묘사한 그림으로, 동화사 염불암의 ○○○○○와 함께 동일한 원본을 보고 그린 것이다. 비단 바탕에 채색하였으며, 가로 170.8㎝, 세로 166.3㎝의 규모이다. 얼굴의 이목구비를 섬약하게 표현하긴 하였으나, 조선 후기 ○○○○○의 독특한 유형을 잘 보여주며, 음영의 표현이나 적색과 녹색의 대비, 화려한 꽃무늬 등은 19세기의 불화양식을 그대로 나타내고 있다.","a":"지장사 극락구품도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588024.jpg"},{"q":"약 200년전 ○○ 신씨들이 살던 집으로 안채와 사랑채가 앞뒤로 나란히 서 있다. 안채와 사랑채가 각각 ㅁ자, ㄷ자 모양의 독립된 공간으로 나뉘어 남녀가 사용하는 공간 구별이 뚜렷하다. 전형적인 부농 민가 형식을 지니고 있으며 유교적 전통을 엿볼 수 있는 가옥이다.","a":"창녕 영산 신씨고가1","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664071.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○의 창건시기에 대해서는 정확한 시기를 확인할 수가 없으나, 조선 초 각 지방 군·현에 향교들이 건립될 때인 1407년(태종 7)~1413년(태종 13)에 창건되었을 것으로 추측된다. 현재의 ○○○○는 1647년(인조 25)에 지금 있는 자리로 옮겨 세웠다. 현재 남아 있는 건물로는 대성전, 명륜당, 제기고, 전사청, 내삼문, 동협문 등이 있다. 제사를 지내는 공간인 대성전 안에는 공자를 비롯한 4성(聖)과 4현(賢), 우리나라 성현 18분의 위패를 모시고 있다.","a":"연기향교","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1658032.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었고 봉수대는 산 정상에 설치하여 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. ○○○○는 귀덕초등학교 북쪽에 있으며, 명월진에 소속되어 있다. 옛날의 모습은 남아있지 않고, 지금의 연대는 최근에 보수하여 세운 것이다. 이 연대에는 명월진 소속의 별장 6명, 봉군 12명이 배치되어 6교대로 하루 종일 해안선을 지켰다고 한다. 동쪽으로 애월 연대, 서쪽으로 우지 연대와 연결되어 있다.","a":"귀덕연대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657841.jpg"},{"q":"○○○는 대승불교에서 호법선신(護法善神)으로 봉안되어 신앙의 대상이 된 신중(神衆)을 알기 쉽게 그림으로 나타낸 예배용 불화이다. 이 ○○○는 ○○○ 성보박물관에 소장되어 있는 신중탱화로서, 비단 바탕에 채색하여 그렸으며, 크기는 127.0㎝×109.9㎝이다. 구도는 상단에는 중앙에 제석천을 모시고 주위에 천상중을 배치하였으며, 하단 중앙에는 동진보살을 모시고 그 주위에 신장상을 배치하였다.","a":"양산 통도사 동치8년명 신중도","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664734.jpg"},{"q":"○○○○○은 문헌상으로 확인되었던 조선시대 ○○○이 매우 양호한 상태로 발굴된 것으로 조선시대 ○○○의 구조와 규모 등을 명확히 알 수 있는 자료이다.","a":"노변동사직단","c":"시도기념물","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645406.jpg"},{"q":"○○○○○은 조선 광해군 5년(1613)에 세워진 건물로 조선시대 말기인 헌종 8년(1842)에 고쳤다. ○○○은 대적광전이라고도 하며 원래는 비로자나불을 모시는 법당이지만 이곳에서는 최근에 나한을 모시고 있다 해서 영산전이라 부르고 있다. 앞면 3칸·옆면 2칸으로 옆면이 사람 인(人)자 모양인 맞배집이다. 기둥 위에서 지붕 처마를 받치는 공포가 기둥 위와 기둥 사이에도 있는 다포계 양식이다. 가운데 칸은 공포를 2개씩, 양쪽 칸은 1개의 공포를 배치하였다.","a":"청주 안심사 비로전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638571.jpg"},{"q":"산을 뒤로 하고 넓은 들판을 바라보며 남서향으로 자리잡고 있는 집으로, 1700년대 말에 지은 광산 김씨 ○○○공파의 종가이다. ○○○ 김언기(1520∼1588)는 선조 때의 문신으로 ○○지방의 교육에 크게 힘쓴 인물이다. 이 집은 ㅁ자형의 정침과 사당으로 구성되어 있는데, 사당은 정침의 왼쪽 뒤편 약간 높은 언덕 위에 있다. 중문을 들어서면 정면에 안채가 있고 양 옆으로 사랑채와 행랑채가 안마당을 감싸고 있는 폐쇄적인 배치를 하였다. 창호의 구성이나 목재를 다룬 수법이 옛 방식이며, 배치 및 평면구성 등에서는 조선 후기의 건축양식을 잘 보여주는 옛 집이다.","a":"안동 유일재 종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658842.jpg"},{"q":"고려 후기 뛰어난 유학자였던 백이정(1247∼1323)의 사당이다. 백이정은 고려 충렬왕 24년(1298)에 왕을 모시고 중국에 가 10년간 성리학을 연구하였고 우리나라에 돌아와 성리학을 전파한 인물이다. 이제현, 박충좌 등의 제자를 두었으며 충성왕 때 상의회의 도감사를 거쳐 상당군에 봉해졌다. 본당인 ○○○는 앞면 3칸·옆면 1칸 규모이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕을 하고 있으며 내부 정면에 선생의 위패를 모시고 있다. 이 외에 근래에 세운 외삼문과 경내의 도동재 및 내삼문이 있다.","a":"남해 난곡사","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664439.jpg"},{"q":"○○○는 신라 무열왕 1년(654) 원효대사가 벽방산 기슭에 세운 절이다. ○○○는 조선 숙종 12년(1686)에 처음 지었고 헌종 7년(1841)에 고쳐 지어 오늘에 이르고 있다. 앞면 3칸·옆면 2칸 규모를 갖추고 있으며, 문루의 기능은 없이 법회 장소와 종루의 기능으로 사용하고 있다 누각은 일반적으로 절의 중심 건물 앞에 세워 출입의 역할인 문루의 기능과 종을 걸어 놓는 종루의 기능, 법회를 행하는 강당의 기능을 함께 갖는 경우가 많다. 조선시대 경상남도지역에 있던 절에 만들어진 누각의 두드러진 특징을 갖고 있는 건축물이다.","a":"통영 안정사 만세루","c":"문화유산자료","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664174.jpg"},{"q":"신라하대의 진골 귀족으로 강릉 김씨의 시조인 김주원의 묘소이다. 그가 명주군왕으로 봉해졌기에 왕릉이라고 부른다. 태종무열왕의 둘째아들인 김인문의 5세손으로 알려졌으나, 최근 연구에 의하면 무열왕의 셋째아들인 문왕의 5세손이라고 하며, 선덕왕이 죽은 후 왕위를 계승할 사람이 없자 왕가의 혈족인 그가 왕으로 추대되었다. 그러나 그가 경주로 가는 중에 큰 비가 내려 강을 건널 수 없어 회의에 참석치 못하게 되었다. 이에 신하들은 하늘이 그를 왕위에 오르지 못하게 함이니 다른 사람을 뽑자하여 김경신(후의 원성왕)을 왕으로 추대하였다.","a":"명주군왕릉","c":"시도기념물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647703.jpg"},{"q":"1892년에 대웅전 후불화, 감로도 등과 함께 제작된 ○○○○○로서 조성 당시에는 중단탱으로 조성되어 대웅전 측벽에 봉안되었을 것으로 추정되지만 현재는 대웅전 후불벽 뒷면에 봉안되어 있다. 세로 198.4cm, 가로 402.5cm에 달하는 대형의 탱화로 면본에 그렸다. 구도는 가로가 4m나 되는 긴 직사각형의 화면 중앙에 천○○○과 권속을 배치하고, 향우측에 지지보살(持地菩薩)과 권속, 향좌측에 지○○○과 권속을 배치한 전형적인 ○○○○○의 구도를 보여준다.","a":"봉은사 삼장보살도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636423.jpg"},{"q":"19세기 중엽의 하시찬 선생을 모신 재실로 그의 제자들이 세웠다. 하시찬 선생은 조선 영조 26년(1750)에 대구시 수성구에서 태어났으며 예학에 밝아 책을 저술하기도 하였다. 그는 지금의 ○○○가 있는 곳에서 서쪽으로 50m 떨어진 독무암루에서 살았으며, 순조 28년(1828)에 돌아가셨는데 명성이 높아 제자들이 끊이지 않았다고 한다. ○○○ 안은 재실인 ○○○가 있고 그 왼쪽 뒤로는 별도의 담장을 두고 사당인 경덕사가 자리잡고 있다. 앞면 3칸·옆면 1칸 반 규모이며 중앙에 마루를 두었다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양의 맞배지붕으로 꾸몄다.","a":"독무재","c":"문화유산자료","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659475.jpg"},{"q":"<○○○○○>는 시청광장을 대각선으로 가로지르는 ○○○로 광장 남서쪽 모서리에서 시작하여 시청 신청사의 정면 가운데로 흐른다. ○○○○을 가로지르는 간선과 지선1, 지선2 ○○○로 나누어지며, 지선1과 지선2 ○○○는 서쪽에서 흘러와 간선과 합쳐져 청계천으로 흐른다.","a":"서울광장 지하배수로","c":"시도기념물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102310511400.jpg"},{"q":"예덕 저수지와 용암 저수지 사이에 있는 연정재에서 동으로 흘러내린 낮은 구릉에 위치한 무덤들이다. 현재 12기의 무덤이 남아있으나 10여 년전 개간 당시 많은 무덤들이 사라졌다고 한다. 이 무덤들은 그 배치상태에 있어서 다른 무덤들과는 다른 모습을 하고 있다. 남북 또는 동서로 축을 두고 3개씩 무리지어 가지런히 붙어 있는데, 이러한 배치상태로 앞이 네모나고 뒤가 둥근 전방후원무덤 형태로 보는 견해도 있다.","a":"함평예덕리고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654139.jpg"},{"q":"이 불상은 미륵산(彌勒山) 높은 산봉우리 가까이 위치하였는데 뒤편 숲속에 드러나 있던 것을 1970년대에 수습하여 현재의 위치에 세운 석가여래입상으로 전체 높이 180㎝이다. 민머리의 정수리 부분에는 상투 모양의 머리(육계)가 큼직하게 솟아 있고, 얼굴은 원만하며 눈·코·입 또한 솜씨있게 처리되어 있다. 양쪽 귀는 긴 편이 아니나 목에는 3줄의 주름인 삼도(三道)가 뚜렷하며, 양 어깨를 감싸고 있는 옷은 가슴에 굵은 옷주름이 표현되었고 양쪽 팔부터 무릎까지 U자형으로 흘러내리고 있다.","a":"진천 지암리 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638776.jpg"},{"q":"정려비는 국가에서 미풍양속을 권장하기 위해 충신, 효자, 열녀 등 모범이 되는 사람을 표창하고자 세우는 비로, 이 비는 정담 선생의 충절을 기리고 있다. 정담(1548∼1592)은 선조 16년(1583) 무과에 급제하여 이탕개의 변에 공을 세우고 여러 벼슬을 거쳐 선조 25년(1592)에 김제군수가 되었다. 이 해 임진왜란이 일어나, 금산을 거쳐 전주를 점령하려는 일본군을 맞이하여 웅치에서 끝까지 방어하여 적의 진격을 막았으나, 싸움 도중에 45세의 나이로 전사하였다. 비의 형태는 받침돌 위에 비몸을 세우고 용머리가 조각된 머릿돌을 얹은 모습이다.","a":"정담정려비","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663242.jpg"},{"q":"○하장리는 본래 ○○군(報恩郡) 탄부면(炭釜面)지역으로 긴매(長山)아래쪽이 되므로 아래진미 또는 하장산(下長山)이라 하였는데, 1914년 행정구역 폐합에 따라 하장리(下長里)라 하였음. ○○○○○은 이창경(李昌慶), 이원경(李元慶), 이명경(李鳴慶) 등 3형제와 연안김씨(延安金氏), 창녕성씨(昌寧成氏) 등 ○○○○ 문중 5인의 효행과 열행을 기리기 위해 세운 정문임. ○○○○○은 하장리 마을에서 떨어진 외딴곳에 위치하며 경지정리가 완료된 논으로 둘러싸여 있으며, 앞쪽으로는 최근에 건립된 게이트볼장이 있음.","a":"보은 경주이씨 효열각","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2016052015180400.jpg"},{"q":"전라남도 구례군 마산면 ○○○에 있는 불상으로, 머리 부분이 떨어진 것을 다시 붙여놓았다. 신체 일부와 오른쪽 뺨이 다소 훼손된 것을 제외하고는 비교적 원형을 잘 유지하고 있다. 사각에 가까운 얼굴에는 눈·코·입이 큼직하며 체구는 당당하지만 선이 부드럽다. 옷은 왼쪽 어깨에 걸쳐 팔과 무릎으로 흘러내리고 있고, 부드러운 옷주름이 표현되어 있다. 불상이 앉아 있는 팔각형의 대좌(臺座)는 상대·중대·하대로 나누어져 있는데, 상대와 하대에는 연꽃잎이 조각되어 있다. 현재 8각기둥 모양의 중대는 따로 떨어져 옆에 방치되어 있다.","a":"구례사도리석불좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639998.jpg"},{"q":"아양리에 있는 3층 석탑으로, 1935년 탑골이라 불리는 곳에서 밭을 갈던 중 박학중 씨가 발견하여 세워 놓은 것이다. 발견 당시 기단부(基壇部)와 머리장식이 사라진 상태였으며, 현재 3층을 이루는 탑신(塔身)만이 남아 있는데, 그나마 탑신의 2·3층 몸돌은 탑을 옮겨 세울 때 새로 만들어 놓은 것이다. 탑신의 몸돌에는 모서리마다 기둥 모양을 새겼고, 지붕돌 밑면에는 4단의 받침을 두었다. 탑신의 1층 몸돌과 3층 지붕돌은 원래 탑의 석재가 확실하며, 몸돌의 기둥 모양 조각과 지붕돌의 받침 조각 수법은 우수한 편이다.","a":"거제 아주동 삼층석탑","c":"문화유산자료","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663856.jpg"},{"q":"○○○○은 주불을 법신인 비로자나불毘盧遮那佛을 모신 금당을 말한다. ○○○○○은 1987년에 시작하여 1993년에 완공되었다. 중층 목조건물로서, 하층은 정면 5칸, 측면 4칸, 상층은 정면 3칸, 측면 2칸으로서 면적 197.48㎡이다. 공포栱包는 다포식多包式이며 하층은 외3출목出目 내6출목, 상층은 외3출목 내7출목이다. 가구架構는 이고주칠량가二高柱 七樑架이고 천장은 우물(井)반자 천장이며 바닥은 상하층 통층通層으로 우물마루(井抹樓)이다. 지붕은 중첨으로 팔작지붕이다.","a":"선덕사대적광전","c":"문화유산자료","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666846.jpg"},{"q":"동강 김우옹 선생을 추모하기 위해 세운 서원이다. 김우옹(1540∼1603)은 조선 명종과 선조 양대에 이조판서와 대제학, 경영관을 지냈으며, 20권의 문집과 속강목 36권을 펴내기도 하였다. 이 서당은 1902년에 지었으며, 1922년에는 ‘굉정각’이란 서고를 만들어 청주서원에서 보관하고 있던 선생의 문집 판각 600매를 옮겨 왔다. 서당의 전체적인 구조는 배우는 공간인 서당이 앞쪽에 있고 그 뒤로 사당과 판각을 보관하는 전각이 나란히 옆으로 배치되어 있다. 서당은 앞면 5칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"진주 용강서당","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663957.jpg"},{"q":"강응정을 중심으로 양응춘·김문기·김성휘·김필해·남준 등을 기리기 위해 지은 서원이다. 강응정은 조선 전기 문신이며 학자이다. 성균관 유생시절 향약을 만들었으며 효행이 지극하여 효자 정문을 세우기도 했다. 이 서원은 본래 강응정을 모시기 위해 두월리에 세운 것으로 원래 이름은 갈산사였다. 임진왜란 때 불타 없어졌고, 숙종 39년(1713) 지금 있는 자리에 다시 지어 ○○○○이라 하였다. 서익·양응춘·김문기·김성휘·김필해·남준을 추가로 배향하여 오다가, 고종 4년(1867) 서익은 행림서원으로 옮겼다.","a":"효암서원","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661028.jpg"},{"q":"전라남도 도청 앞뜰에 놓여 있는 8각 석등으로, 불을 밝혀두는 화사석(火舍石)을 중심으로 아래에는 3단의 받침을 두고, 위에는 지붕돌과 머리장식을 올렸다. 받침부분은 길쭉한 가운데기둥을 사이에 두고, 아래 ·위 받침돌에 연꽃무늬를 대칭적으로 새겼다. 화사석은 4곳에 창을 두었으며, 그 위에 얹어진 지붕돌은 규모가 작아서인지 다른 부재들과 균형을 이루지 못하고 있다. 전체적으로 통일신라의 일반적인 석등양식을 하고 있으나, 당시에 비해 조각기법이 조잡하고 섬세하지 못하다.","a":"광주재명석등","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637140.jpg"},{"q":"1933년 충청남도 부여군 부여읍 금성산의 천왕사 절터에서 발견되어 현재 국립부여○○○에 옮겨져 있는 불상이다. 몸체에 비하여 머리가 크며 어깨와 하체가 거의 일직선으로 곧바로 서 있는 자세이다. 얼굴은 살이 올라 풍만하며 눈은 반쯤 감겨있다. 목에는 3줄의 주름인 삼도(三道)가 새겨져 있으며, 양 어깨에 걸친 옷은 아무런 무늬없이 발 밑까지 내려져 있다. 오른손은 위로 올려 손바닥이 밖을 향하게 하였고, 왼손은 아래로 늘어뜨려 손바닥이 보이게 하였다.","a":"박물관석조여래입상","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661059.jpg"},{"q":"사찰측의 전언에 따르면 현범어사 주지인 정여스님의 원불로 모시고 있던 불상이었다고 전하며, ○○○○를 개창하면서 기증한 것으로 알려져 있다. 강당건물의 봉안불로 밀폐된 유리함속에 모셔져 있다. 보관장식물을 제외한 보관은 새롭게 재작된 것이며, 전체적으로 도금이 탈락된 것을 제외하면 상태는 양호한 편이다. 최근에 사찰측에서 복장을 개봉하였다고 하는데 이 속에는 황동의 후령통과 이를 싼 황초폭자, 복장발원문, 주서다라니, 경전인쇄물이 발견되었다고 하며, 복장발원문을 복사하고 촬영한 후 다른 복장유물과 재복장한 것으로 전한다.","a":"밀양 여여정사 목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643098.jpg"},{"q":"전북특별자치도 남원의 ○○○ 절터로 추정되는 야산에 위치하고 있는데, 무릎 아래가 묻혀 있던 것을 근래에 발굴하였다. 불상이 놓인 대좌(臺座)의 하대석에서 광배 끝까지의 높이는 2.4m이다. 민머리 위에 상투 모양의 머리묶음이 큼직하고, 얼굴은 마멸이 심해 알아보기 힘들지만 온유한 인상을 풍긴다. 양 어깨를 감싼 옷은 가슴 앞에서 평행을 그리면서 무릎까지 내려왔고, 양 팔에 걸쳐진 옷자락도 다리 좌우로 길게 내려와 있다. 손모양은 왼손을 가슴 높이로 들고 있고, 오른손은 배 앞에서 구부리고 있지만 손가락 모양을 살피기는 어렵다.","a":"낙동리석조여래입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639436.jpg"},{"q":"○○○○○는 보문산권 도○○○유적에 대한 학술조사로 '97.5.17~8.8까지 조사되었다. 발굴조사를 통하여 가마유구 1기와 작업장 시설로 보이는 석축구조물 3기가 확인되었다. 가마유구는 무너져 파손된 청정부위를 제외하고는 보존상태가 매우 양호하다. 가마는 주변의 석비레층을 깊이 파고 들어간 후 천정부분을 진흙으로 덮어씌운 등요의 구조를 갖추고 있다. 이 가마에서는 소성실 사이에 같은 간격으로 설치된 두 개씩의 굵직한 창불기둥과 길고 턱이 낮은 아궁이, 특이하게 배열된 굴뚝부의 석열들을 볼 수 있다.","a":"정생동백자가마터","c":"시도기념물","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645835.jpg"},{"q":"전북특별자치도 남원시 사매면 풍악산 ○○○의 거대한 바위에 조각한 높이 4.5m의 마애불상이다. 자연암벽에 조각된 불상임에도 불구하고 원형이 잘 보존되어 있으며, 불상 앞 공터에는 기와조각이 남아 있어서 예전에 법당이나 요사채가 있었던 것으로 보인다. 불상은 연꽃무늬가 새겨진 대좌(臺座) 위에 앉아 있는 모습이며, 머리와 신체 주위에는 2중의 굵은 띠모양으로 머리광배와 몸광배가 둘러져 있다. 얼굴은 둥근 편으로 입가에 표현된 주름의 표현이 독특하다. 귀는 어깨까지 길게 늘어져 있으며, 어깨는 비교적 넓게 표현되어 있다.","a":"노적봉마애여래좌상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661800.jpg"},{"q":"1630년을 전후한 시기에 조선시대 종4품 관청인 수문관청(守門將廳)에 소속된 ○○○들의 계회를 그린 ○○○이다. 전서체의 제목과 그림, 좌목 세 부분으로 구성된 전형적인 계축의 형식이다. 좌목에는 품직, 이름, 자, 생년, 무과 합격년도, 본관, 거주지 등과 부친의 품직과 이름이 기록되어 있다. 좌목 서두에 “守門將廳”이라 쓰여 있어 ○○○의 제작 주체가 ○○○들이며 총 19명의 ○○○들이 모였었음을 알 수 있다.","a":"수문장계회도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636532.jpg"},{"q":"절의 기록에 의하면 ○○○는 신라 진덕여왕 5년, 백제 의자왕 14년 혜감국사가 지었다고 되어 있는데, 진덕여왕 5년(651)과 의자왕 14년(654)은 다른 해에 해당한다. ○○○ 경내에는 보물 제143호로 지정된 ○○○대웅전을 비롯하여 ○○○, 심검당, 무량수각 등 여러 건물이 남아 있다. ○○○은 지장보살을 모시는 전당으로, 기록에 따르면 조선 인조 24년(1646)에 세웠다. 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양의 익공 양식으로 꾸몄다.","a":"개심사명부전","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661222.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○군 하일면 ○○○의 마을 주위 논밭에는 모두 8기의 고인돌이 밀집하여 분포되어 있는데, 이들은 모두 큰 덮개돌 아래에 작은 받침돌을 마련한 바둑판식 형태를 보인다.","a":"고성 오방리 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654899.jpg"},{"q":"3대에 걸쳐 나라를 위해 목숨을 바친 해주오씨 오충신(五忠臣)의 무덤과 사당인 충렬사가 있는 곳이다. 충렬사는 조선 숙종 7년(1681)에 세웠고 오응정과 그의 아들 욱과 직, 직의 아들 방언을 모셔 사충사라 하였으나 근래에 오응정의 아들 동량도 함께 모심에 따라 오충사라 부르고 있다. 오응정은 조선 선조 7년(1574) 무과에 급제하여 여러 관직에서 공을 쌓았으며 정유재란(1597) 때는 왕을 의주까지 호송하였다. 선조 30년(1597)에 아들 욱, 동량과 더불어 남원성 전투에 참여하였으나 참패하자 화약더미에서 아들과 함께 순절하였다.","a":"삼세오충렬유적","c":"시도기념물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653526.jpg"},{"q":"이 산성은 고창읍에서 서북쪽으로 약 6㎞ 정도 떨어진 석치동 마을 뒷산 섬틀봉에 위치하고 있으며 동·서·남쪽에 하천을 끼고 해발 20m 이하의 작은 지대를 굽어보는 곳에 축성하였다. 자연석을 이용하여 쌓은 테뫼식 석성으로서 남쪽은 비교적 작은 돌로 쌓은 반면에 북쪽은 이 보다 큰 돌로 쌓았다. 성벽은 남쪽 266m, 동쪽 142m, 북쪽 322m 정도로서 전체둘레는 730m에 이르며, 높이는 약 3m 내외이다.","a":"서산산성","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661855.jpg"},{"q":"세종의 국구(國舅 : 왕비의 아버지)이자 소헌왕후의 아버지인 심온(沈溫, 1375~1418) 선생의 묘이다. 묘역은 순흥 안씨(順興安氏)와 합장한 단분(單墳; 하나의 봉분)의 형태이다. 계체석(階砌石; 묘역을 구분하는 편평하고 긴 경계석)을 중심으로 3단의 계단식으로 조성하였는데, 15세기 묘제의 원형이 잘 보관되고 있다. 묘표(墓表 ; 무덤 주인공의 이름 등을 새긴 비석)는 ‘안효’라는 시호가 적혀 있어 1451년 이후에 제작된 것이다. 형태는 규수방부형(圭首方趺形 ; 좌우 모서리의 각을 죽인 머릿돌과 사각 받침돌의 비석 형태)으로 비교적 장대한 규모이다.","a":"심온선생묘","c":"시도기념물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646100.jpg"},{"q":"○○○은 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. ‘○○○○○’은 반월봉 서북사면 해발 30m 지점에 위치하며, ○○○의 서쪽에는 황구지천이 남북으로 흐르고 있다.","a":"오산외삼미동고인돌","c":"시도기념물","nc":"","r":"경기도","s":"오산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647443.jpg"},{"q":"조선 인조 때 한성부서윤이라는 벼슬을 지낸 윤흡(1580∼1633)의 후손이 지은 집이다. 세운 시기를 정확하게 알 수 없으나 윤흡의 장손자인 윤섬 때 지은 것으로 알려져 있다. 원래는 안채 맞은편에 사랑채가 있었고 그 앞으로 삼문이 있었다고 하나 지금은 안채와 행랑채만 남아 있다. ㄷ자형 안채 오른쪽에 ㄴ자형 행랑채를 붙여 전체적으로 ㅁ자형 평면을 갖추고 있다. 안채는 중앙에 넓은 대청마루를 두고 좌우로 안방과 윗방·부엌·건넌방을 배치하였다. 대청마루에는 ‘영사당(永思堂)’이라고 쓴 현판이 걸려 있다.","a":"파평윤씨서윤공파고택","c":"문화유산자료","nc":"","r":"대전광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659740.jpg"},{"q":"고려시대의 명관인 육려·임옥산·박이항 등 3인을 기리기 위한 서원이다. 조선 정조 13년(1789)에 세웠는데, 정조 22년(1798)에 박이겸과 정조 23년(1799)에 김설을 더하여 모셨다. 그 뒤 고종 5년(1868)에 흥선대원군의 서원철폐령으로 폐쇄되자 후손들이 제단을 만들어 제사만 지내오다가 1958년에 다시 세웠다. 현재 서원 안에 있는 건물로 강당인 울흥재, 사당인 압계사, 내삼문, 외삼문 등이 있다. 압계사에는 5인의 위패를 모시고 있으며 해마다 3월에 제사를 지낸다.","a":"압계서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661652.jpg"},{"q":"오포대는 목포시 유달산 입구의 이충무공 동상 남서쪽에 있다. 예전에 오포는 포탄 없이 화약만 넣고 포를 쏘아, 시민들에게 정오가 되었음을 알려주는 기능을 하였다. 처음의 포는 조선식 선입포로 현종 10년(1669)에 제작되었는데, 경기도 광주에서 가져온 것이라고 한다. 1913년 일본식 대포를 구입하여 새로 배치하였으며, 그전의 대포는 송도신사에 보관하던 중 일제시대 후기에 오포대의 대포와 함께 일본정부가 가져갔다고 한다. 당시의 오포대는 현재의 유달산공원의 전망대로 사용되고 있으며, 오포는 주변에 모형을 만들어 전시하고 있다.","a":"목포오포대","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662091.jpg"},{"q":"○○○은 현재 五忠祠의 강당으로 사용되고 있는 1937년에 건립된 건물이다. 오충사는 ○○ 선씨(선윤지, 선형, 선거이, 선세강, 선약해) 5위의 위패를 봉안한 사우로 창건은 1598년 이며 1831년에 사액을 받았다. 오충사는 다른 사우와 마찬가지로 1868년 대원군의 서원 훼철령으로 철폐 되었다가 1961년에 복설되어 오늘에 이르고 있다. ○○○은 본래 사우의 강당용으로 지은 건물이 아니고 현 오충사 담장에 면하여 있었던 최씨 문중의 살림집인 ‘사랑채’ 건물이다.","a":"보성 충의당","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658441.jpg"},{"q":"신라 김유신(595∼673)장군의 위패를 모신 사당이다. 신라가 삼국을 통일한 후에 변방지역에 말갈족이 자꾸 침입하여 괴롭히자, 명주(지금의 강릉)의 화부산 밑에 장군이 머물면서 적을 퇴치하여 평화를 되찾았다고 한다. 그 후 장군이 세상을 떠나자 백성들이 조선 고종 21년(1884) 화부산의 밑에 사당을 짓고 제사를 지내며 장군을 추모하여 오다가, 1936년 강릉역 확장으로 인하여 지금의 위치로 옮겨졌다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"화부산사","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637998.jpg"},{"q":"안채와 사랑채, 행랑채와 곳간채, 문간채로 구성되어 있으며 1938년에 지은 집이다. 안채는 앞면 5칸·옆면 3칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 천장 위에는 모두 다락을 두었고 앞면과 뒷면 창은 빗살창으로 꾸몄다. 사랑채는 안채 앞쪽에 배치되어 있는 건물로 지붕은 팔작지붕이다. ‘영춘헌’이라는 현판이 걸려 있으며, 안채와 같이 천장 위에 다락을 만들었고 ㄱ자형으로 뻗친 대청누각이 있다. 곳간채는 안채와 사랑채 사이에 남북으로 뻗어 있다. 앞면 4칸·옆면 1칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다.","a":"정상윤가옥","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661747.jpg"},{"q":"○○○○○은 영천시 청통면 치일리에 있는 조계종 제10교구 본사 ○○○ 내 암자인 ○○○에 위치하고 있다. 암벽 아래에 암석 틈에 붙어서 불당이 있어서 암자 이름이 ○○○이라 부르게 된 것이라고 전한다. 불당지 한켠에는 불당 창건 때 것으로 추정되는 고려시대의 전형적인 어골문(魚骨文) 기와 조각이 쌓여 있다. 이 석탑은 높이가 약 3m로, 석탑의 양식은 통일신라의 전형적인 ○○○○으로 되어 있다. 잘 다듬은 장대석 4개를 결합하여 지대석으로 깔고, 그 위에 2층 기단과 3층의 탑신부를 올렸다.","a":"은해사중암암삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641069.jpg"},{"q":"충청북도 ○○군 이월면 ○○○에 있는 석조불상으로, 거대한 암벽에 높이 6.1m, 너비 4.2m로 대좌(臺座)와 함께 얕게 새겼다. 전체적인 표현이 형식적이고 도식화되었으나 머리광배와 몸광배가 뚜렷하고, 얼굴에서 풍기는 원만한 모습이 다른 불상과 비교되는 특징이다. 부드러운 미소, 감은 듯한 눈, 양 어깨에 걸치고 있는 옷, 수평으로 조각된 대좌 등에서 고려시대에 만들어진 거대한 불상임을 알 수 있다.","a":"진천 노원리 마애여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638689.jpg"},{"q":"조선 인조 8년(1630)에 지은 전통주택이다. 안채·사랑채·문간채가 ㄷ자형 평면구조를 보이는 우리나라 남부지역에 분포된 전형적인 부농의 가옥형태이다. 안채는 폭이 좁고 길이가 긴 모습의 남향집이다. 부엌·큰방·대청·방이 배열되어 있는데 보수공사를 하면서 부엌과 큰방의 크기가 약간 변경되었다. 안사랑채는 안채의 정면 오른쪽에 위치한 동향집이다. 방 2칸과 대청으로 이루어졌으며, 방 앞면에는 마루를 두고 대청의 뒷면에는 벽을 설치하였다. 대문방향인 옆면에는 문을 달고 앞면은 대문과 직접 마주 보이지 않으므로 개방시켜 놓았다.","a":"단계박씨고가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659032.jpg"},{"q":"화순군은 호남정맥이 중앙으로 지나가고 있기 때문에 산지가 발달되어 있으며 평지는 화순천과 충신강이 합류하여 지석천을 이루는 능주면·도곡면 일대에 발달되어 있을 뿐이다. 고분이 위치한 ○○○ 일대는 강변에 충적평지가 발달되어 있을 뿐 주위로는 국사봉, 연주산, 비봉산 등 해발 300m 내외의 산지로 둘러싸여 있다. 고분은 충신강 서쪽에 형성된 해발 35m 정도의 충적평지에 위치하고 있는데 주변지역은 모두 논으로 경작되고 있다.","a":"화순관영리고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662264.jpg"},{"q":"김호와 김계휘를 모시기 위해 그의 자손들이 묘 근처에 세운 재실이다. 앞면 4칸·옆면 2칸 건물로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다. 오른쪽 1칸은 부엌·가운데 2칸은 방·왼쪽 1칸은 대청으로 되어 있으며 전면에는 넓게 마루를 설치하였다. 세운 시기를 정확하게 알 수 없으나 전통 한옥 양식이며 재실로서 특이한 내부구조를 보여주고 있어 한옥 연구에 좋은 자료가 된다.","a":"모선재","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661395.jpg"},{"q":"○○○○○유적은 1990년 9월 이 지역에 내린 집중 호우로 유적의 퇴적 층위가 깎이어 나가는 과정에서 많은 양의 유물이 지표에 노출·수습되면서 알려지게 되었다. 1996년 조동제축조공사시 구제발굴을 실시하여 신석기∼청동기문화층이 잘 발달되어 있음이 확인되었다. 1997년도에는 청동기시대 집터·불땐자리·움 등 생활유구가 조사되었으며, 2000년도에도 조사되었다.","a":"충주 조동리 유적","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651135.jpg"},{"q":"선조 22년(1589) 기축옥사로 연루되어 회령으로 유배되었을 때 동강 김우옹(1540∼1603)선생이 저술한 『○○○○○목』을 새긴 목판이다. 김우옹은 조선 중기의 문신으로, 남명 조식의 문인이다. 1567년 문과에 급제하였으나, 병으로 나아가지 못하고, 1573년 이후부터 벼슬길에 올랐다. 그가 회령으로 유배된 것은 기축옥사가 일어나자 정여립과 조식에게서 가르침을 함께 받았다는 이유때문이었다. 1597년 대사성과 예조참판을 역임하고 2년 뒤 벼슬을 내놓고 지내다가 다음해 죽었다.","a":"속자치통감강목판목","c":"시도유형문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640806.jpg"},{"q":"○○○에 보존되어 있는 ○○○인데, ○○○이라 함은 사람이 죽어서 3일 만에 만나서 심판을 받게 된다는 지옥의 왕과 그의 권속들을 그림으로 표현한 것을 말한다. 비단 바탕에 채색하여 그린 이 탱화는, 병풍을 두른 상부와 돗자리를 깐 하부로 나누어, 상부에 현왕을, 하부에 권속들을 배치하고 있다. 현왕은 중앙 의자에 앉아 있고, 하부 돗자리 위에 반원형으로 신관과 녹사 등 권속들이 둘러싼 구도를 나타내고 있다. 화면 상단 배경에는 6폭의 병풍이, 하단 바닥에는 화문석이 각각 설치되어 있다.","a":"양산 통도사 동치3년명 현왕탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664855.jpg"}]);